/* ============================================================
   Learner-language text (en, American English) for data/core/grammar-reference.js
   Keys point at ids in the neutral layer; arrays merge by index,
   so their length has to match core. Checked by scripts/parity.mjs.
   Cells in the learned language (German) carry class='it', the
   historical name of that field.

   Contrastive notes are written against English, not translated
   from another language: the point of comparison changes with the
   reader's language.
   ============================================================ */
LINGUAI.addStrings("en", {
  "refsec:titles": [
    "Nouns and articles",
    "Adjectives and adverbs",
    "Pronouns",
    "The verb",
    "Moods and passive",
    "Prepositions",
    "The sentence",
    "Pronunciation and register"
  ],
  "ref:g-genus": {
    title: "Noun gender",
    sub: "der, die, das",
    body: "<p>Every German noun is <b>masculine</b> (<em>der</em>), <b>feminine</b> (<em>die</em>) or <b>neuter</b> (<em>das</em>), objects included: <em>der Tisch, die Lampe, das Buch</em>. English has no grammatical gender, so there is no habit to lean on. The only reliable method is to learn every noun <b>with its article</b>, as one unit: not <em>Tisch</em>, but <em>der Tisch</em>.</p><h4>Cues that help</h4><ul><li><b>die</b>: <em>-ung, -heit, -keit, -schaft, -ion, -tät</em> (<em>die Zeitung, die Gesundheit, die Freundschaft, die Nation, die Universität</em>) and feminine <b>-in</b> (<em>die Lehrerin</em>).</li><li><b>das</b>: <em>-chen, -lein</em> (<em>das Mädchen, das Büchlein</em>). Diminutives are always neuter, even for a girl.</li><li><b>der</b>: nouns that name men specifically (<em>der Mann, der Lehrer</em>; but <em>das Kind</em> and <em>das Baby</em> are neuter even for a boy) and days, months, seasons (<em>der Montag, der Mai</em>).</li></ul><p class='callout callout--trap'><b>Trap:</b> gender is grammatical, not logical. <em>das Mädchen</em> (the girl) is neuter, and English <em>it</em> will not help you: a masculine noun is replaced by <em>er</em> even for a table (<em>Der Tisch ist neu. Er ist groß.</em>).</p>"
  },
  "ref:g-plural": {
    title: "The plural",
    sub: "-e, -er, -(e)n, -s, no ending, umlaut",
    body: "<p>English forms the plural almost always with <em>-s</em>. German has several patterns, and the plural article is <b>die</b> in the nominative and accusative, whatever the gender (the dative <em>den</em> comes later): <em>der Tisch → die Tische</em>, <em>das Kind → die Kinder</em>. Learn the plural together with the singular.</p><div class='table-wrap'><table class='gt'><thead><tr><th>pattern</th><th>singular</th><th>plural</th></tr></thead><tbody><tr><td>-e</td><td class='it'>der Tag</td><td class='it'>die Tage</td></tr><tr><td>-e + umlaut</td><td class='it'>die Stadt</td><td class='it'>die Städte</td></tr><tr><td>-er (+ umlaut)</td><td class='it'>das Kind, das Haus</td><td class='it'>die Kinder, die Häuser</td></tr><tr><td>-(e)n</td><td class='it'>die Frau, das Auge</td><td class='it'>die Frauen, die Augen</td></tr><tr><td>no ending</td><td class='it'>der Lehrer, die Mutter</td><td class='it'>die Lehrer, die Mütter</td></tr><tr><td>-s</td><td class='it'>das Auto, das Handy</td><td class='it'>die Autos, die Handys</td></tr></tbody></table></div><ul><li>Most feminine nouns take <b>-(e)n</b>; <b>-s</b> is rare and mostly for foreign words.</li><li>Only <b>a, o, u, au</b> take an umlaut: <em>der Vater → die Väter</em>.</li></ul><p class='callout callout--trap'><b>Trap:</b> English speakers over-apply <em>-s</em> (<em>*die Tags, *die Kinds</em>). Here <em>-s</em> is the exception, not the rule.</p><h4>C2: double plurals</h4><p>A few nouns have <b>two plurals</b>, each with its own meaning. The dictionary gives both with an explanation: picking the wrong one is not a mistake of form but of meaning.</p><div class='table-wrap'><table class='gt'><thead><tr><th>singular</th><th>plural</th><th>meaning</th></tr></thead><tbody><tr><td class='it'>die Bank</td><td class='it'>die Banken</td><td>banks (financial institutions)</td></tr><tr><td></td><td class='it'>die Bänke</td><td>benches</td></tr><tr><td class='it'>das Wort</td><td class='it'>die Wörter</td><td>single words, counted or listed</td></tr><tr><td></td><td class='it'>die Worte</td><td>words someone says, phrases, remarks</td></tr><tr><td class='it'>die Mutter</td><td class='it'>die Mütter</td><td>mothers</td></tr><tr><td></td><td class='it'>die Muttern</td><td>nuts (for bolts)</td></tr><tr><td class='it'>der Druck</td><td class='it'>die Drucke</td><td>prints, printed works</td></tr><tr><td></td><td class='it'>die Drücke</td><td>pressures (in physics and engineering)</td></tr></tbody></table></div><p><em>Wörter</em> counts units of vocabulary: <em>Der Aufsatz darf höchstens 300 Wörter haben.</em> <em>Worte</em> is about what someone says: <em>mit anderen Worten, Worte des Dankes, Seine Worte haben mich berührt.</em> In speech you will hear <em>Wörter</em> in the second sense too, but fixed phrases keep <em>Worte</em>.</p><p class='callout callout--trap'>English has a handful of pairs like this (<em>brothers / brethren, cloths / clothes, pennies / pence</em>), but they are relics. In German both plurals take the same articles in every case (<em>die, den, der</em>), so only the shape of the noun carries the meaning: learn <em>die Banken</em> and <em>die Bänke</em> as two separate words.</p>"
  },
  "ref:g-artikel-nom": {
    title: "Articles in the nominative",
    sub: "der/die/das/die, ein/eine/ein, kein/keine",
    body: "<p>The nominative is the case of the subject and of the noun after <em>sein</em>. English has one definite article, <em>the</em>; German has four forms, because it shows gender and number.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>pl.</th></tr></thead><tbody><tr><td>the</td><td class='it'>der</td><td class='it'>die</td><td class='it'>das</td><td class='it'>die</td></tr><tr><td>a / an</td><td class='it'>ein</td><td class='it'>eine</td><td class='it'>ein</td><td>-</td></tr><tr><td>no / not a</td><td class='it'>kein</td><td class='it'>keine</td><td class='it'>kein</td><td class='it'>keine</td></tr></tbody></table></div><p>After <em>sein</em> a predicate noun is nominative: <em>Das ist der Kaffee. Er ist Arzt.</em> A predicate adjective takes no case ending: <em>Er ist müde.</em> <em>Ich bin in der Schule</em> is different: <em>in der Schule</em> is a prepositional phrase, not a nominative.</p><ul><li><b>Definite</b>: the thing is known or unique: <em>Der Kaffee ist heiß.</em></li><li><b>Indefinite</b>: it is new or one of many: <em>Das ist ein Kaffee.</em></li><li><b>kein</b> is <em>ein</em> with a <em>k-</em>: it negates a noun (see <em>g-negation</em>): <em>Ich habe keinen Hund.</em></li><li>The indefinite article has <b>no plural</b>, just like English: <em>Das sind Kinder.</em></li></ul><p class='callout callout--trap'><b>Note:</b> <em>ein</em> is also the number <em>one</em>, as in English <em>a / one</em>. With professions German drops the article: <em>Er ist Arzt</em> (He is a doctor).</p>"
  },
  "ref:g-artikel-akk": {
    title: "Articles in the accusative",
    sub: "only the masculine changes: den, einen, keinen",
    body: "<p>The accusative marks the <b>direct object</b>, the thing that is bought, eaten, seen. At A1 there is one rule to remember: <b>only the masculine singular changes</b>. Feminine, neuter and plural look exactly like the nominative.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>pl.</th></tr></thead><tbody><tr><td>nominative</td><td class='it'>der / ein / kein</td><td class='it'>die / eine / keine</td><td class='it'>das / ein / kein</td><td class='it'>die / - / keine</td></tr><tr><td>accusative</td><td class='it'><b>den / einen / keinen</b></td><td class='it'>die / eine / keine</td><td class='it'>das / ein / kein</td><td class='it'>die / - / keine</td></tr></tbody></table></div><ul><li><em>Der Kaffee ist gut.</em> → <em>Ich nehme <b>den</b> Kaffee.</em></li><li><em>Einen Kaffee, bitte.</em> (I would like a coffee.)</li><li><em>Ich habe <b>keinen</b> Hunger.</em> but <em>Ich habe <b>keine</b> Zeit.</em></li></ul><p class='callout callout--trap'><b>For English speakers:</b> English marks case only on pronouns (<em>he / him</em>). German marks it on the article of a noun, so the word order <em>Den Kaffee trinke ich</em> still tells you who drinks what. Check whether the noun is masculine before choosing the article.</p>"
  },
  "ref:g-artikel-dat": {
    title: "Articles in the dative",
    sub: "dem, der, dem, den + -n; einem, einer; meinem",
    body: "<p>The dative is the case used after certain prepositions (<em>mit, zu, bei, aus, von, nach, seit</em>) and, with two-way prepositions (<em>in, an, auf, unter, vor, hinter, neben, über, zwischen</em>), to say <em>where</em> something is (<em>in der Küche</em>); other prepositions govern their own case. Unlike the accusative, <b>every gender changes</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>plural</th></tr></thead><tbody><tr><td>the</td><td class='it'>dem</td><td class='it'>der</td><td class='it'>dem</td><td class='it'>den + <b>-n</b></td></tr><tr><td>a / an</td><td class='it'>einem</td><td class='it'>einer</td><td class='it'>einem</td><td>(none)</td></tr><tr><td>no / not a</td><td class='it'>keinem</td><td class='it'>keiner</td><td class='it'>keinem</td><td class='it'>keinen + <b>-n</b></td></tr><tr><td>possessive (mein, my)</td><td class='it'>meinem</td><td class='it'>meiner</td><td class='it'>meinem</td><td class='it'>meinen + <b>-n</b></td></tr></tbody></table></div><p>Examples: <em>Ich fahre mit dem Bus. Ich wohne bei meiner Schwester. Er kommt aus der Stadt.</em></p><p>In the plural the dative adds <b>-n</b> to the noun, unless the plural already ends in <em>-n</em> or <em>-s</em>: <em>die Kinder → mit den Kindern</em>, <em>die Freunde → mit den Freunden</em>, but <em>die Frauen → mit den Frauen</em> and <em>die Autos → mit den Autos</em>. Some foreign plurals in <em>-a</em> don't take it either: <em>die Praktika → mit den Praktika</em>.</p><p class='callout callout--trap'><b>For English speakers:</b> English nouns and articles look the same whatever job they do (<em>the man, with the man, to the man</em>); case survives only in pronouns (<em>he / him, we / us</em>). German keeps case on the <b>article</b> as well: <em>mit der Frau</em>, not <em>*mit die Frau</em>. Learn each preposition together with the case it asks for (<em>mit + Dativ</em>).</p><p>The prepositions that take the dative have their own entry. For now just recognize the form: after <em>mit</em> the masculine singular article is <em>dem</em>, not <em>den</em>: <em>mit dem Mann</em>.</p>"
  },
  "ref:g-genitiv": {
    title: "The genitive",
    sub: "des Mannes, der Frau, des Kindes: who owns what, and wegen, während, innerhalb",
    body: "<p>The <b>genitive</b> is the fourth case. It says whom something belongs to or whom you are talking about, and it comes <b>after</b> the noun it refers to: <em>das Auto des Mannes</em> (the man’s car). The article carries the case:</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>plural</th></tr></thead><tbody><tr><td>definite article</td><td class='it'>des</td><td class='it'>der</td><td class='it'>des</td><td class='it'>der</td></tr><tr><td>indefinite article</td><td class='it'>eines</td><td class='it'>einer</td><td class='it'>eines</td><td class='it'>-</td></tr><tr><td>example</td><td class='it'>das Auto des Mannes</td><td class='it'>die Tasche der Frau</td><td class='it'>das Spielzeug des Kindes</td><td class='it'>die Zimmer der Kinder</td></tr></tbody></table></div><p>In the masculine and neuter the <b>noun</b> also takes an ending: <b>-es</b> or <b>-s</b>. <em>-es</em> usually appears after short nouns or nouns that end in <em>s, ß, x, z</em> (<em>des Tages, des Hauses</em>) and <em>-s</em> after longer nouns (<em>des Vaters, des Computers</em>). Some weak masculines take <em>-(e)n</em> (<em>des Studenten, des Kollegen</em>). Feminine and plural nouns do not change. After an article or a possessive, the adjective in the genitive takes <em>-en</em>: <em>des alten Hauses, der jungen Frau, meines neuen Autos</em>. Without an article, the masculine and neuter have <em>-en</em> (<em>trotz starken Regens</em>), the feminine and plural <em>-er</em> (<em>wegen kalter Milch, die Hilfe guter Freunde</em>).</p><p><b>Proper names</b> take <em>-s</em> and come <b>before</b> the noun, with no article and no apostrophe: <em>Annas Auto, Toms Bruder</em>. A name ending in a sibilant (<em>-s, -x, -z, -ß</em>) takes only the apostrophe: <em>Hans’ Auto, Max’ Buch</em>. In speech the genitive is often replaced by <b>von + dative</b>: <em>das Auto von meinem Vater</em>.</p><h4>Prepositions with the genitive</h4><div class='table-wrap'><table class='gt'><thead><tr><th>preposition</th><th>meaning</th><th>example</th></tr></thead><tbody><tr><td class='it'>wegen</td><td>because of</td><td class='it'>Wegen des Regens bleiben wir zu Hause.</td></tr><tr><td class='it'>während</td><td>during</td><td class='it'>Während des Urlaubs habe ich viel gelesen.</td></tr><tr><td class='it'>innerhalb</td><td>within</td><td class='it'>Innerhalb einer Woche bekommen Sie eine Antwort.</td></tr><tr><td class='it'>trotz</td><td>despite, in spite of</td><td class='it'>Trotz der Kälte gehen wir spazieren.</td></tr></tbody></table></div><p>In speech you often hear the dative after <em>wegen</em> and <em>trotz</em> (<em>wegen dem Wetter</em>); in a written or official text the genitive is used.</p><p class='callout callout--trap'><b>For English speakers:</b> English has two ways to show possession: the possessor first with <em>’s</em> (<em>the man’s car</em>) or after the noun with <em>of</em> (<em>the car of the man</em>). The German genitive with a common noun has the order of the second one, <em>das Auto des Mannes</em>, but it marks the possessor on the <b>article</b> (<em>des, der</em>) instead of using a separate word. With a name the order is the one you know from <em>’s</em>, but there is <b>no apostrophe</b>: <em>Annas Buch</em>, not <s>Anna’s Buch</s>.</p><p class='callout callout--trap'><b>For English speakers:</b> English keeps <em>during</em> (before a noun) and <em>while</em> (before a clause) apart. German has one word for both: <em>während</em> is a conjunction that sends the verb to the end (<em>Während ich arbeite, ...</em>) and also a preposition with the genitive (<em>während des Urlaubs</em>), with no conjugated verb after it.</p><h4>C2: verbs and adjectives with the genitive</h4><p>A small group of verbs and adjectives take an object in the <b>genitive</b>, with no preposition. They belong to formal writing, legal language and official speeches, where a C2 reader meets them often.</p><div class='table-wrap'><table class='gt'><thead><tr><th>verb or adjective</th><th>example</th><th>meaning</th></tr></thead><tbody><tr><td class='it'>bedürfen</td><td class='it'>Das bedarf einer Erklärung.</td><td>to require, to need</td></tr><tr><td class='it'>gedenken</td><td class='it'>Wir gedenken der Opfer.</td><td>to commemorate</td></tr><tr><td class='it'>sich enthalten</td><td class='it'>Sie enthielt sich der Stimme.</td><td>to abstain (from voting)</td></tr><tr><td class='it'>sich bedienen</td><td class='it'>Er bediente sich eines Tricks.</td><td>to make use of</td></tr><tr><td class='it'>jemanden beschuldigen</td><td class='it'>Man beschuldigt ihn des Diebstahls.</td><td>to accuse someone of</td></tr><tr><td class='it'>sich bewusst sein</td><td class='it'>Ich bin mir des Risikos bewusst.</td><td>to be aware of</td></tr><tr><td class='it'>sich sicher sein</td><td class='it'>Sie ist sich ihres Erfolgs sicher.</td><td>to be sure of</td></tr><tr><td class='it'>würdig sein</td><td class='it'>Er ist dieses Vertrauens würdig.</td><td>to be worthy of</td></tr></tbody></table></div><p>In neutral word order the genitive object comes <b>before</b> the adjective, and with <em>bewusst</em> and <em>sicher</em> the reflexive pronoun is <b>dative</b>: <em>Ich bin mir des Risikos bewusst.</em> The genitive has to show on an article or at least on an adjective ending, so a noun with no marking at all is avoided: <em>Es bedarf großer Geduld</em>, where <em>-er</em> carries the case. In everyday German an alternative is preferred: <em>brauchen</em> for <em>bedürfen</em>, <em>erinnern an</em> + accusative for <em>gedenken</em> (<em>Eine Tafel erinnert an die Opfer.</em>), <em>benutzen</em> for <em>sich bedienen</em>.</p><p class='callout callout--trap'>English uses <em>of</em> in most of these (<em>aware of, sure of, worthy of, accuse someone of</em>), and the logic is the same, but German has no preposition here: the case marking on the noun phrase (article, adjective ending or noun) does the job. Do not translate <em>of</em> with <em>von</em> (<em>sich des Risikos bewusst</em>, not <s>sich von dem Risiko bewusst</s>). And it does not work the other way round: most English <em>of</em> adjectives take a preposition in German (<em>proud of</em> is <em>stolz auf</em>, <em>afraid of</em> is <em>Angst haben vor</em>).</p>"
  },
  "ref:g-n-deklination": {
    title: "Weak masculine nouns",
    sub: "der Kunde, den Kunden, dem Kunden, des Kunden",
    body: "<p>A group of <b>masculine</b> nouns takes <b>-n</b> or <b>-en</b> in every case except the nominative singular. This is the <b>n-Deklination</b>:</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>der Kunde</th><th>der Student</th><th>der Mensch</th></tr></thead><tbody><tr><td>nominative</td><td class='it'>der Kunde</td><td class='it'>der Student</td><td class='it'>der Mensch</td></tr><tr><td>accusative</td><td class='it'>den Kunden</td><td class='it'>den Studenten</td><td class='it'>den Menschen</td></tr><tr><td>dative</td><td class='it'>dem Kunden</td><td class='it'>dem Studenten</td><td class='it'>dem Menschen</td></tr><tr><td>genitive</td><td class='it'>des Kunden</td><td class='it'>des Studenten</td><td class='it'>des Menschen</td></tr><tr><td>plural</td><td class='it'>die Kunden</td><td class='it'>die Studenten</td><td class='it'>die Menschen</td></tr></tbody></table></div><ul><li><b>masculines in -e</b> for people or animals: <em>der Kollege, der Junge, der Neffe, der Zeuge, der Löwe, der Affe</em></li><li><b>masculines of foreign origin</b> in <em>-ent, -ant, -ist, -at, -oge</em>: <em>der Präsident, der Praktikant, der Polizist, der Journalist, der Kandidat, der Soldat, der Biologe</em></li><li><b>a few others</b>: <em>der Mensch, der Herr, der Nachbar, der Bauer, der Held, der Bär</em>. <em>Herr</em> takes <em>-n</em> in the singular and <em>-en</em> in the plural: <em>Ich schreibe Herrn Müller. Meine Damen und Herren!</em></li></ul><p>A few nouns also take <b>-ns</b> in the genitive: <em>der Name, des Namens</em>; likewise <em>der Gedanke, der Glaube, der Buchstabe</em>. <em>das Herz</em> is neuter and has <em>dem Herzen, des Herzens</em>.</p><p>Examples: <em>Ich habe den Kunden angerufen. Ich spreche mit dem Kollegen. Das ist das Büro des Präsidenten.</em></p><p class='callout callout--trap'>English nouns change only for the plural and the possessive <em>'s</em>, so the <em>-n</em> looks like a plural. <em>den Kunden</em> can be one customer (accusative singular) or the customers (dative plural), with the same article: the case required by the verb decides. <em>sehen</em> takes the accusative, so <em>Ich sehe den Kunden</em> is one customer; <em>helfen</em> takes the dative, so <em>Ich helfe den Kunden</em> is the customers, and one customer would be <em>Ich helfe dem Kunden</em>. The usual mistake is leaving the ending out: <s>Ich frage den Student</s> instead of <em>den Studenten</em>. Feminine nouns never follow this pattern: <em>die Kundin, der Kundin</em>.</p>"
  },
  "ref:g-wortbildung": {
    title: "Compound nouns",
    sub: "the last element decides the gender: die Hand + die Tasche = die Handtasche",
    body: "<p>German builds new words by <b>sticking</b> two nouns (or more) together into a single word. It is written as one word, and the noun at the <b>end</b> is the one that counts: it gives the <b>gender</b> and the basic meaning, while the element in front specifies it.</p><div class='table-wrap'><table class='gt'><thead><tr><th>compound</th><th>formation</th><th>meaning</th></tr></thead><tbody><tr><td class='it'>der Apfelsaft</td><td class='it'>der Apfel + der Saft</td><td>apple juice</td></tr><tr><td class='it'>die Handtasche</td><td class='it'>die Hand + die Tasche</td><td>handbag</td></tr><tr><td class='it'>die Haustür</td><td class='it'>das Haus + die Tür</td><td>front door</td></tr><tr><td class='it'>das Wörterbuch</td><td class='it'>die Wörter + das Buch</td><td>dictionary</td></tr><tr><td class='it'>der Geburtstag</td><td class='it'>die Geburt + s + der Tag</td><td>birthday</td></tr><tr><td class='it'>das Schlafzimmer</td><td class='it'>schlafen + das Zimmer</td><td>bedroom</td></tr></tbody></table></div><p>The gender always follows the last element: <em>die Haustür</em> is feminine because <em>die Tür</em> is, even though <em>das Haus</em> is neuter. So with a new compound you only need to look at the end: <em>das Zimmer → das Schlafzimmer</em>.</p><p>Sometimes a small linking element appears between the two parts (<em>-s-, -n-, -er-</em>): <em>Geburt<b>s</b>tag, Küche<b>n</b>tür, Kind<b>er</b>zimmer</em>. There is no simple rule for it: learn the whole compound with its article. The first element can also be a verb or an adjective (<em>das Schlafzimmer, die Großmutter</em>).</p><p class='callout callout--trap'><b>For English speakers:</b> the logic will look familiar, because English also puts the base word last and the specifying word first (<em>apple juice, front door, birthday</em>). The difference is the spelling: English writes many compounds as two words (<em>apple juice, front door</em>) or with a hyphen, while German writes them as <b>one word</b>. Do not leave a space in the middle: <em>die Haus Tür</em> is an error. Also, German does not rebuild the idea with <em>of</em> (<em>door of the house</em>): <em>die Haustür</em>, not <em>*die Tür Haus</em>. Word formation with prefixes and suffixes, and longer compounds, comes at later levels.</p><h4>C2: linking elements and derivation</h4><p>The linking element between the parts of a compound (<em>Fugenelement</em>) adds no meaning: usage fixes it. Some regularities help you predict it.</p><div class='table-wrap'><table class='gt'><thead><tr><th>link</th><th>when</th><th>example</th></tr></thead><tbody><tr><td>none</td><td>the most frequent case</td><td class='it'>die Haustür, der Apfelsaft</td></tr><tr><td class='it'>-s-</td><td>almost always after -ung, -heit, -keit, -schaft, -ion, -tät; often after a masculine or neuter noun</td><td class='it'>der Zeitungsartikel, die Informationsquelle, das Geburtstagsgeschenk</td></tr><tr><td class='it'>-es-</td><td>after some short masculine and neuter nouns</td><td class='it'>das Tageslicht, das Bundesland</td></tr><tr><td class='it'>-n-</td><td>after feminine nouns in -e</td><td class='it'>der Sonnenschein, der Küchentisch</td></tr><tr><td class='it'>-en-</td><td>after weak masculine nouns and some feminine ones</td><td class='it'>das Menschenrecht, das Studentenwohnheim, der Frauenarzt</td></tr><tr><td class='it'>-er-</td><td>as in the plural in -er</td><td class='it'>der Kindergarten, das Bilderbuch</td></tr></tbody></table></div><p>Sometimes a final <em>-e</em> drops (<em>die Schule → das Schuljahr, die Sprache → der Sprachkurs</em>), and the same word can behave differently in different compounds: <em>das Rindfleisch</em> but <em>der Rinderbraten</em>. The <em>-s-</em> rule does not work backwards: some feminine nouns without those suffixes take it too (<em>die Arbeit → der Arbeitsplatz</em>).</p><p><b>Derivation</b> makes a new word from another with a suffix or a prefix. Noun suffixes also fix the gender: <em>-ung, -heit, -keit, -schaft</em> always give a feminine noun, and where there is a plural it ends in <em>-en</em>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>affix</th><th>meaning</th><th>example</th></tr></thead><tbody><tr><td class='it'>-ung</td><td>from a verb: action or result</td><td class='it'>bilden → die Bildung, erfahren → die Erfahrung</td></tr><tr><td class='it'>-heit</td><td>from an adjective or noun: quality, state</td><td class='it'>frei → die Freiheit, das Kind → die Kindheit</td></tr><tr><td class='it'>-keit</td><td>from adjectives in -ig, -lich, -bar, -sam</td><td class='it'>möglich → die Möglichkeit, einsam → die Einsamkeit</td></tr><tr><td class='it'>-schaft</td><td>from a noun: group, relationship</td><td class='it'>der Freund → die Freundschaft, das Land → die Landschaft</td></tr><tr><td class='it'>ver-</td><td>change, getting it wrong, using up</td><td class='it'>sich verlaufen, verschlafen, verbrauchen</td></tr><tr><td class='it'>zer-</td><td>to pieces</td><td class='it'>zerbrechen, zerreißen, zerschneiden</td></tr><tr><td class='it'>ent-</td><td>removing, getting away, coming into being</td><td class='it'>entdecken, entfernen, entstehen</td></tr></tbody></table></div><p><b>Foreign words</b> have suffixes that predict the gender quite reliably. Feminine: <em>-ion, -tät, -ik, -ie, -ur, -enz, -anz</em> (<em>die Nation, die Qualität, die Politik, die Demokratie, die Kultur, die Konferenz, die Toleranz</em>; exception: <em>das Abitur</em>). Masculine: <em>-ismus</em> and nouns for people in <em>-ist, -ant, -ent</em> (<em>der Tourismus, der Journalist, der Praktikant, der Student</em>); the people nouns are weak: <em>des Studenten, dem Journalisten</em>. Neuter: <em>-ment, -um</em> (<em>das Dokument, das Zentrum</em>), with the plurals <em>die Dokumente, die Zentren, die Museen</em>.</p><p class='callout callout--trap'>Several suffixes have English cousins, which makes them easy to spot: <em>-heit</em> is <em>-hood</em> (<em>die Kindheit</em>, childhood), <em>-schaft</em> is <em>-ship</em> (<em>die Freundschaft</em>, friendship), <em>-tät</em> is <em>-ity</em>, <em>-ismus</em> is <em>-ism</em>. English has no gender, so take the gift: the suffix tells you the article. One trap: <em>physics, politics, mathematics</em> look plural in English, but <em>die Physik, die Politik, die Mathematik</em> are singular feminine nouns.</p>"
  },
  "ref:g-adjektivdeklination": {
    title: "Predicate adjectives",
    sub: "Der Pullover ist rot: no ending",
    body: "<p>When the adjective comes after <em>sein</em> (or <em>werden, bleiben</em>) it stays <b>unchanged</b>: it does not agree with the noun in gender or number.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sentence</th></tr></thead><tbody><tr><td>masculine</td><td class='it'>Der Pullover ist rot.</td></tr><tr><td>feminine</td><td class='it'>Die Jacke ist rot.</td></tr><tr><td>neuter</td><td class='it'>Das Hemd ist rot.</td></tr><tr><td>plural</td><td class='it'>Die Schuhe sind rot.</td></tr></tbody></table></div><p>More examples: <em>Der Mantel ist teuer. Sie ist nett. Das Zimmer ist klein. Mein Bruder ist unfreundlich.</em> Also with <em>aussehen</em>: <em>Wie sieht er aus? Er sieht müde aus.</em></p><p class='callout callout--trap'><b>For English speakers:</b> this part will feel familiar, because English adjectives never change either (<em>the shoes are red</em>). The difference comes when the adjective stands <b>before the noun</b>: there German adjectives do take endings (<em>ein roter Pullover</em>), which English never does. Those endings are in the A2 part below. After <em>sein</em> the adjective takes no ending: <em>Die Schuhe sind rot</em>, not <em>*roten</em> or <em>*rote</em>.</p><p>To ask what something is like: <em>Wie ist der Pullover?</em> Colors and other basic adjectives are in the vocabulary of units 4 and 8.</p><h4>A2: the adjective before the noun, after ein, kein and possessives</h4><p>Before the noun the adjective takes an <b>ending</b> that shows gender, number and case. After <em>ein, kein</em> and the possessives (<em>mein, dein, sein ...</em>) the endings are these:</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>plural (kein, mein)</th></tr></thead><tbody><tr><td>nominative</td><td class='it'>ein roter Pullover</td><td class='it'>eine rote Jacke</td><td class='it'>ein rotes Hemd</td><td class='it'>keine roten Schuhe</td></tr><tr><td>accusative</td><td class='it'>einen roten Pullover</td><td class='it'>eine rote Jacke</td><td class='it'>ein rotes Hemd</td><td class='it'>keine roten Schuhe</td></tr><tr><td>dative</td><td class='it'>einem roten Pullover</td><td class='it'>einer roten Jacke</td><td class='it'>einem roten Hemd</td><td class='it'>keinen roten Schuhen</td></tr></tbody></table></div><p>Rule of thumb: where <em>ein</em> has no ending (masculine nominative, neuter nominative and accusative) the adjective carries it (<em>-er, -es</em>); the adjective takes <em>-e</em> in the feminine nominative and accusative and <em>-en</em> in all the other cases (the dative included). <em>mein, kein, ihr ...</em> behave the same way: <em>Das ist mein neues Handy. Ich habe keinen großen Hunger.</em> The adjective after <em>sein</em> stays unchanged. The patterns after <em>der, die, das</em> and without an article are in the B1 part below.</p><p class='callout callout--trap'><b>For English speakers:</b> the position is familiar, because the English adjective also comes before the noun (<em>a red sweater</em>). What is new is the ending: English adjectives never change, while the German one carries gender, number and <b>case</b>: <em>ein roter Pullover</em> (nominative), <em>einen roten Pullover</em> (accusative). Mixing up <em>-en</em> and <em>-er</em> is the most frequent mistake.</p><h4>B1: the adjective after der, die, das and without an article</h4><p>After the definite article (and <em>dieser, jeder, welcher</em>) the ending is almost always <b>-en</b>; <b>-e</b> appears only in the nominative singular of all three genders and in the accusative of the feminine and neuter:</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>plural</th></tr></thead><tbody><tr><td>nominative</td><td class='it'>der rote Pullover</td><td class='it'>die rote Jacke</td><td class='it'>das rote Hemd</td><td class='it'>die roten Schuhe</td></tr><tr><td>accusative</td><td class='it'>den roten Pullover</td><td class='it'>die rote Jacke</td><td class='it'>das rote Hemd</td><td class='it'>die roten Schuhe</td></tr><tr><td>dative</td><td class='it'>dem roten Pullover</td><td class='it'>der roten Jacke</td><td class='it'>dem roten Hemd</td><td class='it'>den roten Schuhen</td></tr><tr><td>genitive</td><td class='it'>des roten Pullovers</td><td class='it'>der roten Jacke</td><td class='it'>des roten Hemds</td><td class='it'>der roten Schuhe</td></tr></tbody></table></div><p>Without an article (before a noun with no determiner, in particular in the plural and with mass nouns) the adjective itself carries the signal for gender and case, with the endings of the article: <em>-er, -e, -es, -e; -en, -e, -es, -e; -em, -er, -em, -en</em>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>plural</th></tr></thead><tbody><tr><td>nominative</td><td class='it'>roter Wein</td><td class='it'>rote Milch</td><td class='it'>rotes Brot</td><td class='it'>rote Äpfel</td></tr><tr><td>accusative</td><td class='it'>roten Wein</td><td class='it'>rote Milch</td><td class='it'>rotes Brot</td><td class='it'>rote Äpfel</td></tr><tr><td>dative</td><td class='it'>rotem Wein</td><td class='it'>roter Milch</td><td class='it'>rotem Brot</td><td class='it'>roten Äpfeln</td></tr></tbody></table></div><p>Several adjectives before the same noun have the same ending: <em>ein großer, schöner Garten; mit alten, neuen Freunden</em>. After <em>ein, kein</em> and the possessives, the endings of the A2 part above apply.</p><p class='callout callout--trap'><b>For English speakers:</b> the English adjective is the same wherever it stands (<em>red wine, the red sweater, a red sweater</em>), and the noun alone is enough. In German the ending carries the <b>case</b> too, and it depends on what comes <b>before</b>: broadly, the signal of gender and case shows up once, on the article if there is one (<em>der rote Pullover</em>, with <em>-e</em> because <em>der</em> already says it) or on the adjective if there is not (<em>roter Wein</em>). After the definite article the endings are only <em>-e</em> and <em>-en</em>: do not look for <em>-er</em> or <em>-es</em> there.</p><h4>C1: adjectives and participles used as nouns</h4><p>An adjective or participle used as a noun is capitalized and declined like an adjective, depending on the article in front of it:</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>with der, die, das</th><th>with ein or no article</th></tr></thead><tbody><tr><td>masculine</td><td class='it'>der Bekannte</td><td class='it'>ein Bekannter</td></tr><tr><td>feminine</td><td class='it'>die Bekannte</td><td class='it'>eine Bekannte</td></tr><tr><td>plural</td><td class='it'>die Bekannten</td><td class='it'>Bekannte</td></tr><tr><td>dative</td><td class='it'>dem Bekannten</td><td class='it'>einem Bekannten</td></tr></tbody></table></div><p>With <em>kein</em> the singular follows <em>ein</em> (<em>kein Bekannter</em>) and the plural follows the possessives (<em>keine Bekannten</em>). The same goes for <em>der Angestellte, der Erwachsene, der Deutsche, der Reisende, der Verletzte</em>. For <em>etwas Neues, nichts Gutes</em> see the entry on indefinite pronouns.</p><p class='callout callout--trap'>English turns adjectives into nouns only in a few fixed cases (<em>the rich, the injured</em>) and otherwise needs a noun (<em>an acquaintance, an employee</em>). German does it freely, and the ending follows the article: <em>der Bekannte</em> but <em>ein Bekannter</em>, <em>die Deutschen</em> but <em>viele Deutsche</em>.</p>"
  },
  "ref:g-komparation": {
    title: "Comparative and superlative",
    sub: "-er ... als, so ... wie, am -sten",
    body: "<p>The comparative of superiority is formed with <b>-er</b>, the predicate superlative with <b>am ... -sten</b>. Comparisons of inequality use <b>als</b> (<em>than</em>; inferiority is <b>weniger ... als</b>, <em>weniger schön als</em>, without <b>-er</b>), equality uses <b>so ... wie</b> (<em>as ... as</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th>base</th><th>comparative</th><th>superlative</th></tr></thead><tbody><tr><td class='it'>klein</td><td class='it'>kleiner</td><td class='it'>am kleinsten</td></tr><tr><td class='it'>schnell</td><td class='it'>schneller</td><td class='it'>am schnellsten</td></tr><tr><td class='it'>alt</td><td class='it'>älter</td><td class='it'>am ältesten</td></tr><tr><td class='it'>jung</td><td class='it'>jünger</td><td class='it'>am jüngsten</td></tr><tr><td class='it'>groß</td><td class='it'>größer</td><td class='it'>am größten</td></tr><tr><td class='it'>gut</td><td class='it'>besser</td><td class='it'>am besten</td></tr><tr><td class='it'>viel</td><td class='it'>mehr</td><td class='it'>am meisten</td></tr><tr><td class='it'>gern</td><td class='it'>lieber</td><td class='it'>am liebsten</td></tr></tbody></table></div><p>Examples: <em>Er ist größer als du. Sie ist so groß wie ich. Anna ist am größten. Ich trinke lieber Tee als Kaffee. Am liebsten trinke ich Wasser.</em></p><p>Many short adjectives take an <b>umlaut</b> (<em>alt, jung, groß</em>); <em>gut, viel, gern</em> have forms of their own and must be learned, as English does with <em>good, better, best</em> and <em>much, more, most</em>.</p><p class='callout callout--trap'><b>For English speakers:</b> <em>than</em> is <b>als</b> and <em>as ... as</em> is <b>so ... wie</b>: <em>bigger than you</em> is <em>größer als du</em>, <em>as big as you</em> is <em>so groß wie du</em>. Do not swap the two little words. German always adds <b>-er</b>, even on long adjectives: there is no <em>more + adjective</em> as in <em>more beautiful</em> (it is <em>schöner</em>). English has the article in the superlative (<em>the biggest</em>); here, referring to the subject of the sentence, German says <em>Er ist am größten</em>. <em>gern → lieber → am liebsten</em> has no single English adjective behind it: it corresponds to <em>like to, prefer, like best</em>.</p><p>Only the comparative as a predicate is shown here; before a noun (<em>der größere Bruder</em>) it comes later with the adjective endings.</p><h4>B2: je ... desto / umso</h4><p><b>je</b> + comparative opens a subordinate clause with the verb at the end; <b>desto</b> or <b>umso</b> + comparative opens the main clause, and the verb follows the whole comparative phrase, including any noun: <em>Je mehr ich lese, desto besser verstehe ich. Je mehr ich lese, desto mehr Wörter verstehe ich. Je länger ich warte, umso nervöser werde ich.</em> Also as a short form: <em>Je früher, desto besser.</em> A noun follows the comparative directly: <em>Je mehr Zeit ich habe, ...</em></p><p class='callout callout--trap'>English says <em>the more I read, the better I understand</em>, with the same word twice and normal word order in both halves. German uses two different words (<em>je ... desto</em>) and two different word orders: verb at the end in the first half, verb right after the comparative in the second. <s>Je mehr ich lese, desto ich verstehe besser</s> is wrong.</p><h4>C1: a very high degree</h4><p>For a very high degree without comparison, German puts an adverb before the adjective: <em>sehr</em>, and in writing <b>höchst, äußerst, besonders, überaus</b> (<em>ein höchst interessanter Vorschlag, eine äußerst schwierige Lage</em>). In speech you also hear <em>total, echt, super</em>. The superlative with <em>am</em> remains a comparison: <em>Dieser Weg ist am kürzesten.</em> Formal writing also has <em>aufs</em> + superlative: <em>Sie hat uns aufs Herzlichste begrüßt.</em></p><p class='callout callout--trap'>English uses <em>most</em> both ways: <em>the most difficult</em> (a comparison) and <em>a most interesting proposal</em> (a very high degree). German keeps them apart: <em>am schwierigsten</em> compares, <em>ein höchst interessanter Vorschlag</em> just intensifies.</p>"
  },
  "ref:g-possessiv": {
    title: "Possessives",
    sub: "mein, dein, sein, ihr, unser, euer, Ihr",
    body: "<p>You choose the possessive by the <b>owner</b>; it then takes the endings of <em>ein</em> according to the gender and case of the <b>thing owned</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>owner</th><th>possessive</th><th>English</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>mein</td><td>my</td></tr><tr><td class='it'>du</td><td class='it'>dein</td><td>your</td></tr><tr><td class='it'>er</td><td class='it'>sein</td><td>his</td></tr><tr><td class='it'>sie (she)</td><td class='it'>ihr</td><td>her</td></tr><tr><td class='it'>es</td><td class='it'>sein</td><td>its</td></tr><tr><td class='it'>wir</td><td class='it'>unser</td><td>our</td></tr><tr><td class='it'>ihr</td><td class='it'>euer</td><td>your (plural)</td></tr><tr><td class='it'>sie (they)</td><td class='it'>ihr</td><td>their</td></tr><tr><td class='it'>Sie (formal)</td><td class='it'>Ihr</td><td>your (formal)</td></tr></tbody></table></div><p>Examples: <em>Meine Mutter heißt Anna. Mein Chef ist nett. Das ist unser Haus. Ich sehe meinen Bruder.</em> In the nominative and accusative, with feminine nouns and in the plural: <em>mein</em> + <b>-e</b> (<em>meine Mutter, meine Eltern</em>); in the dative it is <em>meiner Mutter, meinen Eltern</em>; masculine accusative: <em>meinen</em>. <em>euer</em> drops its <em>e</em> before an ending: <em>eure Mutter, euren Bruder</em>.</p><p>With first names the genitive is made with <b>-s</b>, with no apostrophe: <em>Annas Mutter, Peters Auto</em>. If the name ends in a sibilant (<em>-s, -x, -z, -ß</em>) you add only the apostrophe: <em>Hans’ Mutter, Max’ Auto</em>.</p><p class='callout callout--trap'><b>For English speakers:</b> the owner decides which word you use, exactly as in English: <em>seine Mutter</em> is <em>his mother</em>, <em>ihre Mutter</em> is <em>her mother</em>. What English lacks is the ending, which follows the <b>thing owned</b>, not the owner: <em>Er liebt seine Mutter</em> (feminine noun, so <em>-e</em>) but <em>Sie liebt ihren Vater</em> (masculine accusative, so <em>-en</em>). Remember too that <em>ihr</em> can mean <em>her</em> or <em>their</em>, and that there is no <em>’s</em>: <em>Annas Mutter</em> is <em>Anna’s mother</em>.</p><p>The formal <em>Ihr</em> is capitalized, like <em>Sie</em>: <em>Wie ist Ihr Name?</em></p>"
  },
  "ref:g-adverbien": {
    title: "Adverbs",
    sub: "sehr, zu, viel, wenig; immer, oft, manchmal, nie; gut",
    body: "<h4>Degree</h4><ul><li><b>sehr</b> (very) before an adjective: <em>Der Kaffee ist sehr gut.</em></li><li><b>zu</b> (too): <em>Die Hose ist zu klein.</em> <b>ziemlich</b> (fairly, quite), <b>ein bisschen</b> (a little).</li><li><b>viel</b> and <b>wenig</b> (a lot, little) after the verb: <em>Ich arbeite viel. Er schläft wenig.</em></li></ul><h4>Frequency</h4><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>meaning</th></tr></thead><tbody><tr><td class='it'>immer</td><td>always</td></tr><tr><td class='it'>oft</td><td>often</td></tr><tr><td class='it'>manchmal</td><td>sometimes</td></tr><tr><td class='it'>selten</td><td>rarely</td></tr><tr><td class='it'>nie</td><td>never</td></tr></tbody></table></div><p>They usually come after the verb: <em>Ich trinke immer Kaffee.</em> If one opens the sentence, the subject moves behind the verb: <em>Morgens trinke ich immer Kaffee.</em></p><h4>Manner</h4><p>The adjective, with no ending, doubles as the adverb: <em>Er spricht gut. Sie fährt schnell. Das Kind schläft ruhig.</em> <em>gern</em> (gladly) is an adverb too: <em>Ich lese gern.</em></p><p class='callout callout--trap'><b>For English speakers:</b> English adds <em>-ly</em> or changes the word (<em>quick / quickly, good / well</em>); German uses the same word both times: <em>Der Kaffee ist gut</em> (is good) and <em>Er spricht gut</em> (speaks well). English frequency adverbs sit before the verb (<em>I always drink coffee</em>); in German the verb stays second and the adverb follows it. As in English, <b>sehr</b> goes with adjectives and adverbs (<em>very good</em>) and <b>viel</b> with quantity (<em>a lot of time, I sleep a lot</em>); <em>*viel gut</em> is wrong. <em>gern</em> has no direct English adverb: <em>Ich lese gern</em> is <em>I like reading</em> or <em>I like to read</em>. Like English <em>never</em>, <em>nie</em> already carries the negation: <em>Ich trinke nie Bier</em>, with no <em>nicht</em>.</p>"
  },
  "ref:g-personalpron": {
    title: "Personal pronouns",
    sub: "ich, du, er/sie/es, wir, ihr, sie, Sie",
    body: "<div class='table-wrap'><table class='gt'><thead><tr><th></th><th>singular</th><th>plural</th></tr></thead><tbody><tr><td>1st person</td><td class='it'>ich</td><td class='it'>wir</td></tr><tr><td>2nd person, informal</td><td class='it'>du</td><td class='it'>ihr</td></tr><tr><td>3rd person</td><td class='it'>er, sie, es</td><td class='it'>sie</td></tr><tr><td>formal (sing. and pl.)</td><td class='it' colspan='2'>Sie</td></tr></tbody></table></div><ul><li><b>ich</b> is not capitalized mid-sentence (<em>Heute bin ich müde</em>); <b>Sie</b> (formal you) always is.</li><li>For objects, <b>er / sie / es</b> follow the noun's gender, not its meaning: <em>der Tisch → er</em>, <em>die Lampe → sie</em>, <em>das Buch → es</em>. For people the natural gender can also win, especially beyond the first clause: <em>das Mädchen</em> is often followed by <em>sie</em>.</li><li><b>sie</b> has three meanings: <em>she</em>, <em>they</em>, and the formal <em>Sie</em>. The verb separates the singular <em>sie kommt</em> (she) from the other two; <em>sie kommen</em> (they) and <em>Sie kommen</em> (you, formal) look and sound alike, so the capital letter in writing and the context in speech decide.</li></ul><p class='callout callout--trap'><b>For English speakers:</b> English <em>you</em> covers one person, many people, friends and strangers. German splits it in three: <em>du</em> (one friend), <em>ihr</em> (several friends), <em>Sie</em> (one or more strangers, formal, singular or plural). And a pronoun subject is not normally dropped in statements and questions: <em>Ich komme</em>, not <em>Komme</em>. The informal imperative omits it (<em>Komm! Kommt!</em>); the formal one keeps it (<em>Kommen Sie!</em>). Coordinated main clauses can also leave out a shared subject: <em>Ich gehe ins Kino und sehe einen Film.</em></p>"
  },
  "ref:g-pron-akk": {
    title: "Pronouns in the accusative",
    sub: "mich, dich, ihn, sie, es, uns, euch, sie, Sie",
    body: "<p>When the direct object is already known, you replace it with an accusative pronoun. <em>ich, du, er, wir, ihr</em> change; <em>sie, es</em> and <em>sie/Sie</em> stay the same as in the nominative.</p><div class='table-wrap'><table class='gt'><thead><tr><th>nominative</th><th>accusative</th><th>English</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>mich</td><td>I / me</td></tr><tr><td class='it'>du</td><td class='it'>dich</td><td>you / you</td></tr><tr><td class='it'>er</td><td class='it'>ihn</td><td>he / him</td></tr><tr><td class='it'>sie</td><td class='it'>sie</td><td>she / her</td></tr><tr><td class='it'>es</td><td class='it'>es</td><td>it / it</td></tr><tr><td class='it'>wir</td><td class='it'>uns</td><td>we / us</td></tr><tr><td class='it'>ihr</td><td class='it'>euch</td><td>you / you (plural)</td></tr><tr><td class='it'>sie</td><td class='it'>sie</td><td>they / them</td></tr><tr><td class='it'>Sie</td><td class='it'>Sie</td><td>you / you (formal)</td></tr></tbody></table></div><p>For things the pronoun follows the <b>gender of the German noun</b>: <em>Was kostet der Pullover? Ich nehme ihn. Wie findest du die Jacke? Ich nehme sie. Das Hemd? Ich nehme es.</em> With people: <em>Ich sehe dich. Er ruft uns an. Ich liebe sie.</em></p><p class='callout callout--trap'><b>For English speakers:</b> you already know this idea from <em>he / him, we / us</em>, and the pronoun comes after the verb just as in English (<em>Ich nehme ihn</em>, <em>I take it</em>). Two things differ. English uses <em>it</em> for every thing, while German says <b>ihn / sie / es</b> according to the noun: <em>der Pullover</em> gives <em>ihn</em>, not <em>es</em>. And the pairs that stay unchanged are not the same ones: English keeps <em>you</em> and <em>it</em>, German keeps <em>sie, es, Sie</em>, so <em>du</em> and <em>ihr</em> do change (<em>dich, euch</em>). <em>Ich sehe sie</em> can be <em>I see her</em> or <em>I see them</em>; context decides.</p>"
  },
  "ref:g-pron-dat": {
    title: "Personal pronouns in the dative",
    sub: "mir, dir, ihm, ihr, ihm, uns, euch, ihnen",
    body: "<p>The dative is the case of the <b>indirect object</b> (<em>to whom?</em>) and of some verbs that always take it. After the nominative and the accusative, here are the three forms side by side.</p><div class='table-wrap'><table class='gt'><thead><tr><th>nominative</th><th>accusative</th><th>dative</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>mich</td><td class='it'>mir</td></tr><tr><td class='it'>du</td><td class='it'>dich</td><td class='it'>dir</td></tr><tr><td class='it'>er</td><td class='it'>ihn</td><td class='it'>ihm</td></tr><tr><td class='it'>sie</td><td class='it'>sie</td><td class='it'>ihr</td></tr><tr><td class='it'>es</td><td class='it'>es</td><td class='it'>ihm</td></tr><tr><td class='it'>wir</td><td class='it'>uns</td><td class='it'>uns</td></tr><tr><td class='it'>ihr</td><td class='it'>euch</td><td class='it'>euch</td></tr><tr><td class='it'>sie</td><td class='it'>sie</td><td class='it'>ihnen</td></tr><tr><td class='it'>Sie</td><td class='it'>Sie</td><td class='it'>Ihnen</td></tr></tbody></table></div><p>Examples: <em>Ich gebe ihm das Buch. Wir schicken dir eine Nachricht. Das Kleid gefällt ihr. Ich helfe Ihnen gern.</em> The dative also appears in expressions of feeling and state: <em>Wie geht es dir? Mir ist kalt. Mir geht es gut.</em></p><p>In a neutral main clause the pronoun stands after the conjugated verb, in the middle field; in a subordinate clause it comes before the verb (<em>..., weil ich ihm helfe</em>). When the sentence also has an accusative object, the order depends on the type of word (see the entry on word order): <em>Ich gebe ihm das Buch. Ich gebe es ihm.</em></p><p class='callout callout--trap'><b>For English speakers:</b> English has one object form (<em>me, him, her, us, them</em>) that does the work of both the accusative and the dative: <em>I see him</em> and <em>I give him the book</em> use the same word. German splits them: <em>ihn</em> (accusative) and <em>ihm</em> (dative), <em>mich</em> and <em>mir</em>. And German has no <em>to</em> to mark the indirect object: the dative form does that job (<em>Ich gebe es ihm</em>, <em>I give it to him</em>). Watch the words that look alike: <em>ihr</em> is also the nominative <em>you</em> (plural) in <em>Ihr seid müde</em>, and <em>ihnen</em> (to them) is not <em>Ihnen</em> (to you, formal, always capitalized). <em>ihm</em> covers both masculine and neuter.</p>"
  },
  "ref:g-indefinitpron": {
    title: "einer, eins, welche, keiner",
    sub: "pronouns that replace a noun already mentioned",
    body: "<p>To avoid repeating a noun you use forms of <em>ein</em>, <em>kein</em> and <em>welche</em> without the noun. The ending shows gender and case.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>plural</th></tr></thead><tbody><tr><td>nominative</td><td class='it'>einer</td><td class='it'>eine</td><td class='it'>eins</td><td class='it'>welche</td></tr><tr><td>accusative</td><td class='it'>einen</td><td class='it'>eine</td><td class='it'>eins</td><td class='it'>welche</td></tr><tr><td>negative (nom.)</td><td class='it'>keiner</td><td class='it'>keine</td><td class='it'>keins</td><td class='it'>keine</td></tr><tr><td>negative (acc.)</td><td class='it'>keinen</td><td class='it'>keine</td><td class='it'>keins</td><td class='it'>keine</td></tr></tbody></table></div><p>Examples: <em>Ich brauche einen Stuhl. Haben Sie einen? Ja, ich habe einen. Haben Sie Brötchen? Ja, wir haben welche. Nein, wir haben keine. Ein Bier? Ich nehme eins.</em></p><p>With a number the number is enough: <em>Ich nehme zwei.</em> <b>welche</b> replaces a plural noun that has already been mentioned: <em>Hast du Brötchen? Ja, ich habe welche.</em> (<em>Do you have rolls? Yes, I have some.</em>). The bare noun stays possible when you first name it: <em>Ich kaufe Brötchen.</em></p><p class='callout callout--trap'><b>For English speakers:</b> English has <em>one</em>, <em>some</em> and <em>none</em> for this job, and they do not change for gender or case (<em>Do you have a brother? Yes, I have one</em>). German uses the form of <b>einer</b> that fits the noun (<em>einen</em> is only the masculine accusative), <b>welche</b> for <em>some</em> and <b>keinen / keine</b> for <em>none</em>, and the ending agrees with the noun you leave out: <em>Hast du einen Bruder? Ja, ich habe einen.</em> For a neuter noun the form is <em>eins</em> (in written German also <em>eines</em>). In a short answer German still needs the pronoun: <em>Ja, ich habe welche</em>, not just <em>Ja, ich habe</em>. The fuller forms with <em>jemand, jeder, etwas</em> are in the B1 part below.</p><h4>B1: jemand, niemand, jeder, etwas, nichts</h4><p>These pronouns do not refer back to a noun already mentioned: they talk about people or things in a general way.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>people, regardless of gender</th></tr></thead><tbody><tr><td>nominative</td><td class='it'>jeder</td><td class='it'>jede</td><td class='it'>jedes</td><td class='it'>jemand, niemand</td></tr><tr><td>accusative</td><td class='it'>jeden</td><td class='it'>jede</td><td class='it'>jedes</td><td class='it'>jemand(en), niemand(en)</td></tr><tr><td>dative</td><td class='it'>jedem</td><td class='it'>jeder</td><td class='it'>jedem</td><td class='it'>jemand(em), niemand(em)</td></tr></tbody></table></div><p><b>jemand</b> (somebody) and <b>niemand</b> (nobody) can stay unchanged or take <em>-en</em> in the accusative and <em>-em</em> in the dative: <em>Ich habe niemanden gesehen / Ich habe niemand gesehen. Ich habe jemandem geholfen.</em> <b>jeder</b> (each, everyone) is <b>singular</b> and declines like <em>dieser</em>: <em>Jeder weiß das. Ich kenne jeden hier.</em> <b>alle</b> is plural: <em>Alle sind da.</em></p><p><b>etwas</b> (something) and <b>nichts</b> (nothing) do not change; an adjective after them is capitalized and takes <em>-es</em> in the nominative and accusative (<em>etwas Neues, nichts Besonderes</em>) and <em>-em</em> in the dative (<em>mit etwas Neuem, mit nichts Besonderem</em>). For <em>somebody else</em> you say <em>jemand anders</em>.</p><p class='callout callout--trap'><b>For English speakers:</b> English <em>somebody, nobody, everybody, something, nothing</em> line up with <em>jemand, niemand, jeder, etwas, nichts</em>, and <em>everybody</em> is singular in English too (<em>Everyone has an opinion</em>), as <em>jeder</em> is, while <em>alle</em> is plural like <em>all</em>. The adjective also follows the word, as in English (<em>something new</em>), but German capitalizes it and adds an ending: <em>etwas Neues</em>. The trap is the negation. English <em>I didn’t see anyone, I didn’t do anything</em> does not carry over word for word: German puts the negation in the pronoun, <em>Ich habe niemanden gesehen. Ich habe nichts gemacht</em>, and does not add <em>nicht</em>.</p>"
  },
  "ref:g-es": {
    title: "es gibt, es regnet, es geht",
    sub: "es with no meaning of its own",
    body: "<p>In many German sentences the subject <em>es</em> does not stand for anything, but it is needed: as a rule the sentence requires an expressed subject.</p><h4>es gibt (there is, there are)</h4><p>The form is <b>always singular</b>, and after <em>gibt</em> the noun goes in the <b>accusative</b>: <em>Es gibt einen Bahnhof. Es gibt keinen Supermarkt hier. Es gibt drei Kinos in der Stadt.</em> Question: <em>Gibt es hier ein Café?</em></p><h4>Weather, time, states</h4><ul><li><em>Es regnet. Es schneit. Es ist kalt. Es ist heiß.</em></li><li><em>Es ist Montag. Wie spät ist es? Es ist acht Uhr.</em></li><li><em>Wie geht’s? Es geht.</em></li></ul><p class='callout callout--trap'><b>For English speakers:</b> English needs a dummy subject too (<em>it rains, it’s cold, it’s Monday, what time is it?</em>), so <em>es</em> will feel natural there: you cannot leave it out (<em>Es regnet</em>, not <em>*Regnet</em>). The new thing is <b>es gibt</b>. <em>There is</em> and <em>there are</em> both become <em>es gibt</em>, and the verb never changes: <em>Es gibt drei Kinos</em>. German also keeps the two jobs apart: <em>es gibt</em> introduces something new (<em>Es gibt ein Café</em>), while for placing something already known you use <em>sein</em> (<em>Wo ist das Café? Es ist neben der Post.</em>). <em>Wie geht’s?</em> is <em>How’s it going?</em> and <em>Es geht</em> means roughly <em>so-so, I’m managing</em>.</p><p>Uses of <em>es</em> as a placeholder or as a pointer to a subordinate clause come much later.</p><h4>C1: es announcing a clause</h4><p>When a clause with <em>dass</em>, <em>ob</em> or an infinitive with <em>zu</em> acts as subject or object, the main clause can contain <b>es</b> as a placeholder: <em>Es freut mich, dass du kommst. Ich finde es gut, dass du fragst. Es ist wichtig, pünktlich zu sein.</em> If the clause moves to first position, the subject placeholder disappears: <em>Dass du kommst, freut mich.</em> With verbs that take a preposition, the placeholder is <em>darauf, daran, dafür</em> (see the entry on verbs with prepositions).</p><p class='callout callout--trap'>English works the same way with <em>it</em>: <em>It's important to be on time. I think it's good that you're asking.</em> And both languages drop the placeholder when the clause itself takes the subject position (<em>To be on time is important</em> = <em>Pünktlich zu sein ist wichtig</em>). The difference is that German uses <em>es</em> with more verbs, including objects: <em>Ich finde es gut, dass ...</em>, <em>Ich bedaure es, dass ...</em>.</p>"
  },
  "ref:g-man": {
    title: "The impersonal subject man",
    sub: "Man spricht Deutsch: man + third person singular",
    body: "<p><b>man</b> is a pronoun for any person at all, people in general: <em>one</em>, <em>you</em>, <em>they</em>, <em>people</em>. It is used for rules, habits and instructions, when it does not matter who acts.</p><p><em>Man spricht hier Deutsch. Man darf hier nicht rauchen. Wie sagt man das auf Deutsch? In Italien isst man spät zu Abend.</em></p><p>The verb always goes in the <b>third person singular</b>, even when the meaning is plural (<em>man sagt</em>, not <em>*man sagen</em>). The pronoun has three forms, which follow the pattern of <em>ein</em>:</p><div class='table-wrap'><table class='gt'><thead><tr><th>case</th><th>form</th><th>example</th></tr></thead><tbody><tr><td>nominative</td><td class='it'>man</td><td class='it'>Man kann hier parken.</td></tr><tr><td>accusative</td><td class='it'>einen</td><td class='it'>Das ärgert einen.</td></tr><tr><td>dative</td><td class='it'>einem</td><td class='it'>Dort hilft einem jeder.</td></tr></tbody></table></div><p>The matching possessive is <em>sein</em> and the reflexive is <em>sich</em>: <em>Man muss seine Hausaufgaben machen. Man sollte sich Zeit nehmen.</em></p><p class='callout callout--trap'><b>For English speakers:</b> <b>man</b> is not <b>der Mann</b> (the man) and does not mean <em>a man</em>: it has one <em>n</em> and no capital letter. English <em>one</em> (<em>one speaks German here</em>) is a close match, including the third person singular verb, but it sounds formal. In everyday English you say <em>you</em> (<em>you can’t smoke here</em>), <em>they</em> (<em>they speak German here</em>) or use a passive (<em>German is spoken here</em>). German <em>man</em> is the normal, neutral word for all of these: <em>Man darf hier nicht rauchen</em>. Note the possessive too: where English says <em>you have to do your homework</em>, German says <em>seine</em>, not <em>deine</em>. In speech <em>man</em> often replaces <em>wir</em> as well (<em>Man trifft sich um acht</em>, <em>we’ll meet at eight</em>).</p>"
  },
  "ref:g-praesens": {
    title: "The present tense",
    sub: "stem + -e, -st, -t, -en, -t, -en; sein, haben; vowel change",
    body: "<p>The present covers both <em>I drink</em> and <em>I am drinking</em>: German has <b>no regular progressive form</b> to learn at this level, so one tense does both jobs. <em>Ich trinke Kaffee</em> can mean either. It also works for the near future: <em>Morgen fahre ich nach Berlin.</em></p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>machen</th><th>sein</th><th>haben</th></tr></thead><tbody><tr><td>ich</td><td class='it'>mache</td><td class='it'>bin</td><td class='it'>habe</td></tr><tr><td>du</td><td class='it'>machst</td><td class='it'>bist</td><td class='it'>hast</td></tr><tr><td>er/sie/es</td><td class='it'>macht</td><td class='it'>ist</td><td class='it'>hat</td></tr><tr><td>wir</td><td class='it'>machen</td><td class='it'>sind</td><td class='it'>haben</td></tr><tr><td>ihr</td><td class='it'>macht</td><td class='it'>seid</td><td class='it'>habt</td></tr><tr><td>sie/Sie</td><td class='it'>machen</td><td class='it'>sind</td><td class='it'>haben</td></tr></tbody></table></div><ul><li>Regular stems in <b>-t / -d</b> add <b>-e-</b>: <em>du arbeitest, er arbeitet, ihr arbeitet</em>. Strong verbs whose stem vowel changes do not add it with <em>du</em> and <em>er/sie/es</em>: <em>du hältst, er hält; du lädst, er lädt</em>; <em>ihr</em> keeps the -e-: <em>ihr haltet, ihr ladet</em>. In verbs in <b>-eln</b> the <em>e</em> of the stem is usually dropped after <em>ich</em>: <em>sammeln → ich sammle</em>; in <b>-ern</b> it normally stays: <em>wandern → ich wandere</em>. <em>wir</em> and <em>sie/Sie</em> match the infinitive: <em>sammeln, wandern</em>.</li><li>Stems in <b>-s, -ß, -z</b> drop the <em>-s</em> of <em>-st</em>: <em>du heißt, du tanzt</em>.</li><li><b>Vowel change</b> in <em>du</em> and <em>er/sie/es</em> only: <em>e → i</em> (<em>essen: du isst, er isst; nehmen: du nimmst; sprechen: du sprichst</em>), <em>e → ie</em> (<em>sehen: du siehst</em>), <em>a → ä</em> (<em>fahren: du fährst</em>).</li><li><b>gern</b> adds <em>like to</em>: <em>Ich trinke gern Tee.</em></li></ul>"
  },
  "ref:g-modalverben": {
    title: "Modal verbs",
    sub: "können, wollen, müssen, möchte; the verbal bracket",
    body: "<p>Modals express ability (<em>können</em>), will (<em>wollen</em>), obligation (<em>müssen</em>) and polite wishes (<em>möchte</em>). They conjugate in their own way: with <em>können, wollen, müssen</em> the 1st and 3rd person singular are <b>identical and have no ending</b> (<em>ich kann, er kann</em>), much like English <em>I can, he can</em>. <em>möchte</em> is the exception: it has <em>-e</em> (<em>ich möchte, er möchte</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>können</th><th>wollen</th><th>müssen</th><th>möchten</th></tr></thead><tbody><tr><td>ich</td><td class='it'>kann</td><td class='it'>will</td><td class='it'>muss</td><td class='it'>möchte</td></tr><tr><td>du</td><td class='it'>kannst</td><td class='it'>willst</td><td class='it'>musst</td><td class='it'>möchtest</td></tr><tr><td>er/sie/es</td><td class='it'>kann</td><td class='it'>will</td><td class='it'>muss</td><td class='it'>möchte</td></tr><tr><td>wir</td><td class='it'>können</td><td class='it'>wollen</td><td class='it'>müssen</td><td class='it'>möchten</td></tr><tr><td>ihr</td><td class='it'>könnt</td><td class='it'>wollt</td><td class='it'>müsst</td><td class='it'>möchtet</td></tr><tr><td>sie/Sie</td><td class='it'>können</td><td class='it'>wollen</td><td class='it'>müssen</td><td class='it'>möchten</td></tr></tbody></table></div><p>The modal is in <b>second position</b> and the infinitive goes at the <b>end of the sentence</b>: <em>Ich kann heute nicht kommen. Ich muss um sieben aufstehen. Wir wollen am Samstag ins Kino gehen.</em> The modal and the infinitive form a <b>bracket</b> around the rest of the sentence.</p><p><em>möchte</em> is the Konjunktiv II form of <em>mögen</em>, commonly used for polite wishes and requests; at this level treat it as a ready-made formula: <em>Ich möchte einen Kaffee.</em> (the infinitive can be left out). In a restaurant <em>Ich hätte gern das Schnitzel</em> is also a fixed formula.</p><p class='callout callout--trap'><b>For English speakers:</b> the pattern <em>modal + bare infinitive</em> is the same as in <em>I can come</em>, but English keeps the infinitive right behind the modal and German sends it to the end. <em>I can go to the movies with you tonight</em> becomes <em>Ich kann heute Abend mit dir ins Kino gehen</em>, and <em>*Ich kann gehen heute Abend ins Kino</em> is an error. Also, <em>want to</em> and <em>have to</em> need <em>to</em> in English, but German has no <em>zu</em> after the modal: <em>Ich will gehen, Ich muss gehen.</em> <em>Ich will einen Kaffee</em> sounds blunt, like <em>I want a coffee</em>; for a polite request use <em>möchte</em>, close to <em>I would like</em>. <em>dürfen</em> and <em>sollen</em> come later.</p><h4>B2: the double infinitive</h4><p>In the Perfekt and the past Konjunktiv II, a modal verb that goes with another verb does not use its participle (<em>gekonnt, gemusst</em>) but its <b>infinitive</b>: two infinitives stand at the end of the sentence, first the main verb and then the modal. The auxiliary is always <b>haben</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>example</th></tr></thead><tbody><tr><td>Perfekt</td><td class='it'>Ich habe gestern nicht kommen können.</td></tr><tr><td>past Konjunktiv II</td><td class='it'>Ich hätte dich früher anrufen sollen.</td></tr><tr><td>reproach</td><td class='it'>Du hättest es mir sagen müssen.</td></tr><tr><td>subordinate clause</td><td class='it'>..., weil ich nicht hätte kommen dürfen.</td></tr></tbody></table></div><p>In a subordinate clause the auxiliary does not go to the end: it stands <b>before the two infinitives</b> (<em>..., dass er nicht hat kommen können</em>). When the modal stands alone, without another verb, it takes its normal participle: <em>Ich habe das nicht gekonnt.</em></p><p class='callout callout--trap'>English builds this with <em>have</em> + past participle after the modal: <em>I should have called</em>, <em>you could have told me</em>. German turns it around: the auxiliary is conjugated, the modal comes last as an infinitive: <em>Ich hätte anrufen sollen</em>. For regret or reproach about a call that was not made, German uses <em>Ich hätte anrufen sollen</em>; the word-for-word <em>Ich sollte (bis dahin) angerufen haben</em> speaks instead of an expectation that the call was made by a certain time. A reported claim (<em>they say I called</em>) is <em>Ich soll angerufen haben</em>.</p><h4>C1: the subjective use of modal verbs</h4><p>Besides their basic meaning, modal verbs say how sure the speaker is, or where a piece of information comes from:</p><div class='table-wrap'><table class='gt'><thead><tr><th>modal</th><th>meaning</th><th>example</th></tr></thead><tbody><tr><td class='it'>muss</td><td>almost certain</td><td class='it'>Er muss zu Hause sein, das Licht ist an.</td></tr><tr><td class='it'>dürfte</td><td>probable</td><td class='it'>Das dürfte reichen.</td></tr><tr><td class='it'>kann, könnte</td><td>possible</td><td class='it'>Sie könnte recht haben.</td></tr><tr><td class='it'>soll</td><td>others say so</td><td class='it'>Der Film soll gut sein.</td></tr><tr><td class='it'>will</td><td>he claims it himself; the speaker may signal distance or doubt</td><td class='it'>Er will nichts gesehen haben.</td></tr></tbody></table></div><p>For a supposition about the past, the modal stays in the present and the infinitive changes: <em>Er muss den Schlüssel vergessen haben.</em></p><p class='callout callout--trap'>English has the same pattern for <em>must</em> and <em>might</em> (<em>he must have forgotten the key</em>), but not for <em>soll</em> and <em>will</em>: <em>Der Film soll gut sein</em> is “the film is supposed to be good”, <em>Er will nichts gesehen haben</em> is “he claims not to have seen anything”. German <em>will</em> is never a future here; and <em>dürfte</em> has nothing to do with permission: it means “probably”.</p>"
  },
  "ref:g-trennbare-verben": {
    title: "Separable verbs",
    sub: "aufstehen: Ich stehe um sieben auf",
    body: "<p>Many verbs have a stressed prefix that, in a main clause, <b>detaches</b> and goes to the end of the sentence. The infinitive stays in one piece.</p><div class='table-wrap'><table class='gt'><thead><tr><th>infinitive</th><th>present</th><th>meaning</th></tr></thead><tbody><tr><td class='it'>aufstehen</td><td class='it'>Ich stehe um sieben auf.</td><td>get up</td></tr><tr><td class='it'>einkaufen</td><td class='it'>Wir kaufen am Samstag ein.</td><td>shop, go shopping</td></tr><tr><td class='it'>anrufen</td><td class='it'>Ich rufe dich an.</td><td>call, phone</td></tr><tr><td class='it'>fernsehen</td><td class='it'>Er sieht abends fern.</td><td>watch TV</td></tr><tr><td class='it'>mitkommen</td><td class='it'>Kommst du mit?</td><td>come along</td></tr><tr><td class='it'>ankommen</td><td class='it'>Der Zug kommt um acht an.</td><td>arrive</td></tr></tbody></table></div><p>With a modal the verb is whole again, at the end: <em>Ich muss um sieben aufstehen. Ich möchte heute einkaufen.</em> The two parts enclose the sentence, like the bracket of the modal.</p><p class='callout callout--trap'><b>For English speakers:</b> English phrasal verbs are a useful analogy: <em>get up, call up, come along, turn on</em> are also a verb plus a small particle with its own meaning. But the English particle stays close to the verb (<em>I get up at seven</em>), while the German one jumps to the <b>very end</b> of the clause: <em>Ich stehe um sieben auf</em>. The stem also keeps its vowel change: <em>fernsehen → er sieht fern</em>, <em>einladen → er lädt ein</em>.</p><p>Common separable prefixes: <em>auf-, an-, ein-, mit-, aus-, fern-, zurück-</em>. They are always stressed: <em>’aufstehen, ’anrufen</em>.</p><p class='callout callout--trap'><b>For English speakers:</b> the <b>inseparable</b> prefixes (<em>be-, ver-, er-, ent-, ge-</em>) are unstressed and <b>never detach</b>: <em>besuchen → Ich besuche dich</em>, <em>verstehen → Ich verstehe das</em>, <em>bekommen → Er bekommt ein Geschenk</em>. Watch out: <em>bekommen</em> means <em>to get, to receive</em>, not <em>to become</em> (that is <em>werden</em>). The Partizip II takes no <em>ge-</em> (<em>besucht, verstanden, bekommen</em>). The prefixes <em>über-, um-, unter-, durch-</em> can go either way; they come later.</p><h4>C1: separable or inseparable prefixes</h4><p>The prefixes <b>durch-, über-, um-, unter-, wieder-</b> can be separable or inseparable, and the meaning often changes. Separable: stress on the prefix, prefix detached in finite forms and, if the base verb takes <em>ge-</em>, a participle with <em>-ge-</em> in the middle (<em>umgefahren</em>); usually a concrete meaning. Inseparable: stress on the stem, prefix always attached, participle without <em>ge-</em>; often a figurative meaning.</p><div class='table-wrap'><table class='gt'><thead><tr><th>separable</th><th>inseparable</th></tr></thead><tbody><tr><td class='it'>Er hat das Schild umgefahren.</td><td class='it'>Wir haben den Stau umfahren.</td></tr><tr><td>he knocked the sign over with his car</td><td>we drove around the traffic jam</td></tr><tr><td class='it'>Die Fähre setzt uns über.</td><td class='it'>Sie hat den Text übersetzt.</td></tr><tr><td>the ferry takes us across</td><td>she translated the text</td></tr><tr><td class='it'>Wir sind die ganze Nacht durchgefahren.</td><td class='it'>Wir haben die Schweiz in drei Stunden durchfahren.</td></tr><tr><td>we drove all night without stopping</td><td>we crossed Switzerland</td></tr></tbody></table></div><p class='callout callout--trap'>English phrasal verbs are a useful comparison: the particle can move away from the verb (<em>run the sign over</em>), just like a separable prefix. But in the infinitive both German verbs are spelled the same (<em>umfahren</em>) and only the stress tells them apart; in other forms the separation and the participle help too. The pairs have to be learned one by one.</p>"
  },
  "ref:g-imperativ": {
    title: "The polite imperative",
    sub: "Gehen Sie geradeaus!",
    body: "<p>With <b>Sie</b> the imperative is formed with the <b>infinitive + Sie</b>: the verb comes first and the pronoun right after it.</p><div class='table-wrap'><table class='gt'><thead><tr><th>infinitive</th><th>imperative</th></tr></thead><tbody><tr><td class='it'>gehen</td><td class='it'>Gehen Sie geradeaus!</td></tr><tr><td class='it'>nehmen</td><td class='it'>Nehmen Sie die erste Straße links!</td></tr><tr><td class='it'>abbiegen</td><td class='it'>Biegen Sie rechts ab!</td></tr><tr><td class='it'>warten</td><td class='it'>Warten Sie bitte!</td></tr><tr><td class='it'>entschuldigen</td><td class='it'>Entschuldigen Sie, wo ist der Bahnhof?</td></tr></tbody></table></div><p>Separable verbs send the prefix to the end: <em>Biegen Sie rechts ab. Steigen Sie hier aus.</em> Exception: <em>sein</em> makes <b>Seien Sie</b> (<em>Seien Sie bitte pünktlich!</em>), not <em>*Sind Sie</em>. For directions you also need <em>geradeaus, links, rechts, die erste, die zweite Straße</em>.</p><p class='callout callout--trap'><b>For English speakers:</b> an English command is just the bare verb (<em>Go straight ahead!</em>), with no <em>you</em>. German keeps the pronoun in the polite form: <em>Gehen Sie!</em>, verb first, then <em>Sie</em> (the only exception is <em>sein</em>: <em>Seien Sie!</em>). This also means the command has the same word order as a yes/no question: <em>Gehen Sie geradeaus!</em> or <em>Gehen Sie geradeaus?</em> English separates them with <em>do</em> (<em>Do you go straight?</em>), but German has no <em>do</em>: context, intonation and, in writing, punctuation tell them apart. A polite request can also end with a period, not only an exclamation mark.</p><h4>A2: the imperative with du and ihr</h4><p>With <b>du</b> you use the verb stem, without <em>-st</em> and <b>without a pronoun</b>: <em>Komm! Mach das bitte! Sei ruhig!</em> With <b>ihr</b> you use the present form, again without a pronoun: <em>Kommt! Macht das bitte! Seid ruhig!</em></p><div class='table-wrap'><table class='gt'><thead><tr><th>infinitive</th><th>Sie</th><th>du</th><th>ihr</th></tr></thead><tbody><tr><td class='it'>gehen</td><td class='it'>Gehen Sie!</td><td class='it'>Geh!</td><td class='it'>Geht!</td></tr><tr><td class='it'>warten</td><td class='it'>Warten Sie!</td><td class='it'>Warte!</td><td class='it'>Wartet!</td></tr><tr><td class='it'>nehmen</td><td class='it'>Nehmen Sie!</td><td class='it'>Nimm!</td><td class='it'>Nehmt!</td></tr><tr><td class='it'>lesen</td><td class='it'>Lesen Sie!</td><td class='it'>Lies!</td><td class='it'>Lest!</td></tr><tr><td class='it'>fahren</td><td class='it'>Fahren Sie!</td><td class='it'>Fahr!</td><td class='it'>Fahrt!</td></tr><tr><td class='it'>aufstehen</td><td class='it'>Stehen Sie auf!</td><td class='it'>Steh auf!</td><td class='it'>Steht auf!</td></tr><tr><td class='it'>sein</td><td class='it'>Seien Sie!</td><td class='it'>Sei!</td><td class='it'>Seid!</td></tr></tbody></table></div><p>Three particulars: weak verbs with a stem in <em>-t, -d</em> normally have <em>-e</em> (<em>Warte! Arbeite!</em>), while strong verbs differ (<em>Tritt! Halt!</em>; <em>Lad!</em> or <em>Lade!</em>); verbs with an <em>e → i/ie</em> change keep it in the <em>du</em> form (<em>Nimm! Lies! Sprich langsamer!</em>), while the <em>a → ä</em> change does not occur (<em>Fahr!</em>); in separable verbs the prefix goes to the end (<em>Steh auf!</em>).</p><p class='callout callout--trap'><b>For English speakers:</b> the <em>du</em> form will feel natural: like the English command, it is the bare verb with no pronoun (<em>Come! Wait!</em>), and <em>ihr</em> is the same as a command to several people. The difference is the negative: English needs <em>do</em> (<em>Don’t smoke!</em>), but German has no <em>do</em>: the verb stays in the imperative and <em>nicht</em> is added: <em>Rauch nicht! Geht nicht allein!</em> To soften a request add <em>bitte</em> or <em>mal</em>: <em>Komm mal her!</em></p>"
  },
  "ref:g-perfekt": {
    title: "The Perfekt",
    sub: "haben/sein + Partizip II",
    body: "<p>In speech the past is formed with the <b>Perfekt</b>: the auxiliary (<em>haben</em> or <em>sein</em>) in second position and the <b>Partizip II</b> at the end of the sentence.</p><p><em>Ich habe gegessen. Wir haben einen Film gesehen. Ich bin nach Berlin gefahren. Sie ist früh aufgestanden.</em></p><div class='table-wrap'><table class='gt'><thead><tr><th>type</th><th>infinitive</th><th>Partizip II</th></tr></thead><tbody><tr><td>regular: ge- ... -t</td><td class='it'>machen</td><td class='it'>gemacht</td></tr><tr><td></td><td class='it'>kaufen</td><td class='it'>gekauft</td></tr><tr><td>strong: ge- ... -en</td><td class='it'>essen</td><td class='it'>gegessen</td></tr><tr><td></td><td class='it'>sehen</td><td class='it'>gesehen</td></tr><tr><td>with sein</td><td class='it'>fahren</td><td class='it'>gefahren</td></tr><tr><td></td><td class='it'>gehen</td><td class='it'>gegangen</td></tr><tr><td></td><td class='it'>kommen</td><td class='it'>gekommen</td></tr><tr><td>separable: ge- in the middle</td><td class='it'>aufstehen</td><td class='it'>aufgestanden</td></tr><tr><td></td><td class='it'>einkaufen</td><td class='it'>eingekauft</td></tr><tr><td>no ge-</td><td class='it'>studieren</td><td class='it'>studiert</td></tr><tr><td></td><td class='it'>besuchen</td><td class='it'>besucht</td></tr></tbody></table></div><p>The participles of strong verbs must be learned together with the infinitive (<em>trinken, getrunken; schreiben, geschrieben</em>), much like English <em>drink, drunk; write, written</em>. Verbs in <em>-ieren</em> and verbs with an inseparable prefix (<em>be-, ver-, er-</em>) take no <em>ge-</em>.</p><p>You use <b>sein</b> with intransitive verbs of <b>change of place or state</b> (<em>fahren, gehen, kommen, fliegen, aufstehen</em>) and with <em>sein, bleiben, werden, passieren</em>; with almost all other verbs you use <b>haben</b>. When a motion verb is used transitively, with an accusative direct object, it generally takes <em>haben</em>: <em>Ich habe das Auto gefahren.</em> A dative object does not force <em>haben</em>: <em>Ich bin ihm gefolgt.</em> For <em>sein</em> and <em>haben</em> themselves, <em>war</em> and <em>hatte</em> are preferred: <em>Ich war in Berlin.</em></p><p class='callout callout--trap'><b>For English speakers:</b> the Perfekt looks like the English present perfect (<em>I have eaten</em> = <em>Ich habe gegessen</em>), but in speech it is the <b>ordinary past tense</b>. <em>Gestern habe ich einen Film gesehen</em> means <em>Yesterday I saw a movie</em>; English would not say <em>*Yesterday I have seen</em>. Two more differences: the participle goes at the <b>end of the clause</b> (<em>Wir haben gestern einen Film gesehen</em>), and the auxiliary is not always <em>have</em>: <em>I have gone</em> is <em>Ich bin gegangen</em>. Check the verb.</p>"
  },
  "ref:g-praeteritum": {
    title: "The Präteritum",
    sub: "war, hatte, konnte, wollte: the past of sein, haben and the modals",
    body: "<p>Besides the Perfekt, German has a second past tense, the <b>Präteritum</b>. At this level it matters mostly for <em>sein</em>, <em>haben</em> and the <b>modal verbs</b>: in speech these simple forms are preferred to the Perfekt.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sein</th><th>haben</th><th>können</th><th>wollen</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>war</td><td class='it'>hatte</td><td class='it'>konnte</td><td class='it'>wollte</td></tr><tr><td class='it'>du</td><td class='it'>warst</td><td class='it'>hattest</td><td class='it'>konntest</td><td class='it'>wolltest</td></tr><tr><td class='it'>er/sie/es</td><td class='it'>war</td><td class='it'>hatte</td><td class='it'>konnte</td><td class='it'>wollte</td></tr><tr><td class='it'>wir</td><td class='it'>waren</td><td class='it'>hatten</td><td class='it'>konnten</td><td class='it'>wollten</td></tr><tr><td class='it'>ihr</td><td class='it'>wart</td><td class='it'>hattet</td><td class='it'>konntet</td><td class='it'>wolltet</td></tr><tr><td class='it'>sie/Sie</td><td class='it'>waren</td><td class='it'>hatten</td><td class='it'>konnten</td><td class='it'>wollten</td></tr></tbody></table></div><p>The other modals follow the same pattern, with one rule to remember: in the Präteritum <em>können, müssen, dürfen, mögen</em> lose the Umlaut (<em>konnte, musste, durfte, mochte</em>), while <em>wollen</em> and <em>sollen</em> never had one (<em>wollte, sollte</em>). In the 1st and 3rd person singular the form is the same: <em>ich war, er war</em>.</p><p>Examples: <em>Gestern war ich müde. Wir hatten keine Zeit. Ich konnte nicht kommen. Sie wollte nach Hause gehen.</em></p><p>For many other verbs, speech prefers the <b>Perfekt</b> (<em>Ich habe gearbeitet</em>); some frequent verbs (<em>wusste, dachte, gab</em>) are also common in the Präteritum. The Präteritum of other verbs (<em>ging, kam, sagte</em>) you meet mostly in narrative writing, for example in stories and newspapers: at this level it is enough to recognize it. How the Präteritum of weak and strong verbs is formed and how it is used in writing are in the B1 part below.</p><p class='callout callout--trap'><b>For English speakers:</b> for <em>sein, haben</em> and the modals the match is easy: <em>war</em> is <em>was/were</em>, <em>hatte</em> is <em>had</em>, <em>konnte</em> is <em>could</em> (past ability) and <em>wollte</em> is <em>wanted</em>. The trap is the other verbs. English chooses between the simple past (<em>I worked</em>) and the present perfect (<em>I have worked</em>) by meaning: the present perfect connects the past to now. German does not split them that way: the Perfekt (<em>Ich habe gearbeitet</em>) can render both, and the choice between Perfekt and Präteritum is mostly about speech versus writing. So <em>Ich war in Berlin</em> is more usual in speech than <em>Ich bin in Berlin gewesen</em>, and <em>Ich konnte nicht</em> more usual than <em>Ich habe nicht gekonnt</em>.</p><h4>B1: the Präteritum in written texts</h4><p>In <b>written texts</b> (novels, fairy tales, newspapers, reports) the Präteritum is the main past tense of narration; in conversation the Perfekt often prevails, but <em>sein</em>, <em>haben</em>, the modals and some other frequent verbs commonly appear in the Präteritum. <b>Weak</b> verbs add <b>-te</b> to the stem (<em>machte, sagte, lernte</em>; if the stem ends in <em>-t</em> or <em>-d</em>, <em>-ete</em>: <em>arbeitete, antwortete</em>). <b>Strong</b> verbs change the stem vowel (<em>ging, kam, sah</em>) and <b>have no ending in the 1st and 3rd person singular</b>. <b>Mixed</b> verbs (<em>dachte, brachte</em>) change the stem and take the weak endings (<em>-te</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th>infinitive</th><th>Präteritum (ich/er)</th><th>past participle</th></tr></thead><tbody><tr><td class='it'>machen</td><td class='it'>machte</td><td class='it'>gemacht</td></tr><tr><td class='it'>arbeiten</td><td class='it'>arbeitete</td><td class='it'>gearbeitet</td></tr><tr><td class='it'>gehen</td><td class='it'>ging</td><td class='it'>gegangen</td></tr><tr><td class='it'>kommen</td><td class='it'>kam</td><td class='it'>gekommen</td></tr><tr><td class='it'>sehen</td><td class='it'>sah</td><td class='it'>gesehen</td></tr><tr><td class='it'>geben</td><td class='it'>gab</td><td class='it'>gegeben</td></tr><tr><td class='it'>schreiben</td><td class='it'>schrieb</td><td class='it'>geschrieben</td></tr><tr><td class='it'>finden</td><td class='it'>fand</td><td class='it'>gefunden</td></tr><tr><td class='it'>denken</td><td class='it'>dachte</td><td class='it'>gedacht</td></tr><tr><td class='it'>bringen</td><td class='it'>brachte</td><td class='it'>gebracht</td></tr></tbody></table></div><p>The persons: <em>ich ging, du gingst, er ging, wir gingen, ihr gingt, sie gingen</em>. With a separable verb the particle goes to the end of the main clause (<em>Er stand um sieben auf</em>) and stays attached in the subordinate clause (<em>..., weil er um sieben aufstand</em>).</p><p>A narrative text alternates the Präteritum, for the story, and the Plusquamperfekt, for what happened before (<em>Sie öffnete die Tür. Niemand hatte sie gerufen.</em>).</p><p class='callout callout--trap'><b>For English speakers:</b> the system will look familiar: weak verbs add a suffix like English <em>-ed</em> (<em>worked</em> is <em>arbeitete</em>), and strong verbs change the vowel like <em>sing, sang, sung</em> (<em>singen, sang, gesungen</em>). But a verb that is irregular in English is not always strong in German: <em>said</em> is irregular, and <em>sagte</em> is weak. Learn each strong verb with its three forms, as you did in English. And English splits <em>went</em> from <em>was going</em>, where German has no such split: <em>Er ging nach Hause</em> can be either.</p><h4>B2: the Präteritum in narration</h4><p>In stories, fairy tales, biographies and news reports the past tense is the <b>Präteritum</b>, strong verbs included. The Perfekt stays in the characters' dialogue and in speech; the Plusquamperfekt marks what had happened before.</p><p><em>Es war schon spät. Anna saß am Fenster und las. Plötzlich klingelte das Telefon. Sie stand auf, nahm den Hörer ab und erschrak: Ihr Bruder hatte einen Unfall gehabt.</em></p><p>Some strong verbs common in narration:</p><div class='table-wrap'><table class='gt'><thead><tr><th>infinitive</th><th>Präteritum</th><th>infinitive</th><th>Präteritum</th></tr></thead><tbody><tr><td class='it'>fallen</td><td class='it'>fiel</td><td class='it'>laufen</td><td class='it'>lief</td></tr><tr><td class='it'>rufen</td><td class='it'>rief</td><td class='it'>schreien</td><td class='it'>schrie</td></tr><tr><td class='it'>sitzen</td><td class='it'>saß</td><td class='it'>liegen</td><td class='it'>lag</td></tr><tr><td class='it'>stehen</td><td class='it'>stand</td><td class='it'>ziehen</td><td class='it'>zog</td></tr><tr><td class='it'>verlieren</td><td class='it'>verlor</td><td class='it'>beginnen</td><td class='it'>begann</td></tr><tr><td class='it'>bitten</td><td class='it'>bat</td><td class='it'>treffen</td><td class='it'>traf</td></tr><tr><td class='it'>erschrecken</td><td class='it'>erschrak</td><td class='it'>sterben</td><td class='it'>starb</td></tr></tbody></table></div><p class='callout callout--trap'>English separates the simple past (<em>she stood up</em>) from the past progressive (<em>she was sitting</em>). German has no progressive form: <em>Sie saß am Fenster</em> is <em>she was sitting</em> and <em>Plötzlich stand sie auf</em> is <em>she suddenly stood up</em>. Context and adverbs (<em>plötzlich, immer, gerade</em>) do the work. Avoid <s>Sie war sitzend</s>, which is not German.</p>"
  },
  "ref:g-plusquamperfekt": {
    title: "The Plusquamperfekt",
    sub: "hatte gemacht, war gegangen: the past of the past",
    body: "<p>The <b>Plusquamperfekt</b> is formed like the Perfekt, but with the auxiliary in the <b>Präteritum</b>: <em>hatte</em> or <em>war</em> + past participle. The auxiliary is the same one as in the Perfekt (<em>haben</em> or <em>sein</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>haben</th><th>sein</th></tr></thead><tbody><tr><td>ich</td><td class='it'>hatte gemacht</td><td class='it'>war gegangen</td></tr><tr><td>du</td><td class='it'>hattest gemacht</td><td class='it'>warst gegangen</td></tr><tr><td>er/sie/es</td><td class='it'>hatte gemacht</td><td class='it'>war gegangen</td></tr><tr><td>wir</td><td class='it'>hatten gemacht</td><td class='it'>waren gegangen</td></tr><tr><td>ihr</td><td class='it'>hattet gemacht</td><td class='it'>wart gegangen</td></tr><tr><td>sie/Sie</td><td class='it'>hatten gemacht</td><td class='it'>waren gegangen</td></tr></tbody></table></div><p>You use it for something that happened <b>before</b> another past event: <em>Als ich ankam, war der Zug schon abgefahren. Ich habe ihn nicht erkannt, weil er sich verändert hatte.</em> The verb of the more recent action is in the Präteritum or the Perfekt. In written texts the pair is Präteritum + Plusquamperfekt, in speech Perfekt + Plusquamperfekt.</p><p>After <b>nachdem</b> (after) the standard pattern puts the Plusquamperfekt in the subordinate clause: <em>Nachdem ich gegessen hatte, bin ich spazieren gegangen.</em> If the main verb is in the present, the subordinate clause has the Perfekt (see the B1 part of the entry on <em>als</em> and <em>wenn</em>).</p><p class='callout callout--trap'><b>For English speakers:</b> the form matches the English past perfect (<em>had eaten, had gone</em>), and the German auxiliary follows the Perfekt rule: <em>war gegangen</em> where English still says <em>had</em>. The difference is in how the earlier event is marked. English often lets the simple past do the work (<em>After I ate, I went for a walk</em>) or uses a gerund (<em>After eating, I went out</em>). German has no gerund: you need a subordinate clause with its own subject, <em>Nachdem ich gegessen hatte, ...</em>, or a noun: <em>Nach dem Essen ...</em>.</p>"
  },
  "ref:g-reflexivverben": {
    title: "Reflexive verbs",
    sub: "sich waschen, sich freuen: mich/mir, dich/dir, sich",
    body: "<p>In reflexive verbs the action turns back on the subject: <em>Ich wasche mich</em> (I wash myself). The reflexive pronoun has two forms, <b>accusative</b> and <b>dative</b>, which differ only in the 1st and 2nd person singular.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>accusative</th><th>dative</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>mich</td><td class='it'>mir</td></tr><tr><td class='it'>du</td><td class='it'>dich</td><td class='it'>dir</td></tr><tr><td class='it'>er/sie/es</td><td class='it'>sich</td><td class='it'>sich</td></tr><tr><td class='it'>wir</td><td class='it'>uns</td><td class='it'>uns</td></tr><tr><td class='it'>ihr</td><td class='it'>euch</td><td class='it'>euch</td></tr><tr><td class='it'>sie/Sie</td><td class='it'>sich</td><td class='it'>sich</td></tr></tbody></table></div><p>Usually the <b>accusative</b> is needed: <em>Ich wasche mich. Er duscht sich. Wir freuen uns. Ich interessiere mich für Musik.</em> In constructions with a part of the body or a piece of clothing (<em>sich die Hände waschen</em>, <em>sich einen Pullover anziehen</em>) the reflexive is <b>dative</b>; the case depends on the verb construction (<em>Ich frage mich etwas</em> keeps <em>mich</em>), so learn it with the verb: <em>Ich wasche mir die Hände. Du putzt dir die Zähne. Sie zieht sich einen Pullover an.</em></p><p>The pronoun stands after the conjugated verb. With a pronoun subject it usually follows the subject, with a noun subject it often comes before it: <em>Ich treffe mich morgen mit Anna. Heute freue ich mich. Heute freut sich meine Schwester. Der Zug verspätet sich.</em> In the Perfekt the auxiliary is <em>haben</em>: <em>Ich habe mich gewaschen.</em></p><p>Useful verbs: <em>sich waschen, sich duschen, sich anziehen, sich setzen</em>, <em>sich treffen mit</em> + dative, <em>sich freuen auf</em> + accusative (looking forward: <em>Ich freue mich auf den Urlaub</em>), <em>sich freuen über</em> + accusative (being glad about something present or past: <em>Ich freue mich über das Geschenk</em>), <em>sich erinnern an</em> + accusative, <em>sich interessieren für</em> + accusative, <em>sich ärgern über</em> + accusative. The preposition and its case are learned together with the verb.</p><p class='callout callout--trap'><b>For English speakers:</b> English has reflexive pronouns (<em>myself, himself</em>), but usually drops them: <em>I wash, I get dressed, I sit down, I get annoyed</em>. German keeps the pronoun on many of these verbs: <em>Ich wasche mich, ich setze mich, ich ärgere mich</em>. The two languages do not match verb for verb, so learn each German verb with its pronoun. For parts of the body English uses a possessive (<em>I wash my hands</em>); German uses the dative reflexive with the article: <em>Ich wasche mir die Hände</em> is the usual form (<em>Ich wasche meine Hände</em> is correct too, but less natural). English also distinguishes <em>look forward to</em> from <em>be glad about</em> with different phrases, and German does the same with <em>freuen auf</em> and <em>freuen über</em>.</p>"
  },
  "ref:g-verben-dativ": {
    title: "Verbs with the dative",
    sub: "helfen, danken, gefallen, gehören, gratulieren: the object is in the dative",
    body: "<p>Some verbs take a single object, and this object is in the <b>dative</b> instead of the accusative. They have to be learned together with the verb.</p><div class='table-wrap'><table class='gt'><thead><tr><th>verb</th><th>example</th></tr></thead><tbody><tr><td class='it'>helfen</td><td class='it'>Ich helfe meinem Bruder.</td></tr><tr><td class='it'>danken</td><td class='it'>Wir danken Ihnen für die Einladung.</td></tr><tr><td class='it'>gratulieren</td><td class='it'>Ich gratuliere dir zum Geburtstag.</td></tr><tr><td class='it'>antworten</td><td class='it'>Er antwortet mir nicht.</td></tr><tr><td class='it'>gefallen</td><td class='it'>Das Hemd gefällt mir.</td></tr><tr><td class='it'>gehören</td><td class='it'>Das Auto gehört meiner Mutter.</td></tr><tr><td class='it'>schmecken</td><td class='it'>Die Pizza schmeckt uns.</td></tr><tr><td class='it'>passen</td><td class='it'>Die Schuhe passen ihm.</td></tr><tr><td class='it'>fehlen</td><td class='it'>Du fehlst mir.</td></tr></tbody></table></div><p>Some of these verbs work like <em>please</em> in English: the thing that is liked is the <b>subject</b> (nominative) and the person is in the dative, and the verb agrees with the thing: <em>Das Buch gefällt mir. Die Schuhe gefallen mir.</em> The same goes for <em>schmecken, passen, fehlen</em>. To state a personal taste with a direct object there is also <em>mögen</em> (<em>Ich mag das Buch</em>). In the Perfekt these verbs use <em>haben</em>: <em>Ich habe ihm geholfen.</em></p><p class='callout callout--trap'><b>For English speakers:</b> English <em>him</em> hides the difference: <em>I help him</em> looks the same whatever the case, but German needs the dative: <em>Ich helfe <b>ihm</b></em>, not <em>*Ich helfe ihn</em>; <em>Ich danke <b>dir</b></em>. With nouns, German shows the dative on the article of the masculine and neuter (<em>dem, einem</em>) and the feminine (<em>der, einer</em>): in <em>Ich helfe der Frau</em> the dative is the feminine <em>der</em>. Some of these verbs also turn the English sentence around: <em>I like the shirt</em> is <em>Das Hemd gefällt mir</em> (the shirt is the subject), and <em>I miss you</em> is <em>Du fehlst mir</em> (<em>you</em> is the subject). It is best to learn each verb with an example, not with a one-word translation.</p>"
  },
  "ref:g-futur": {
    title: "The future",
    sub: "Präsens with a time expression, or werden + infinitive",
    body: "<p>To talk about the future German usually uses the <b>present tense</b>, together with a time expression: <em>Morgen fahre ich nach Wien. Nächste Woche habe ich Urlaub. Bald ziehen wir um.</em></p><p>There is also the <b>Futur I</b>, formed with <em>werden</em> conjugated in second position and the <b>infinitive at the end</b> of the sentence.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>werden</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>werde</td></tr><tr><td class='it'>du</td><td class='it'>wirst</td></tr><tr><td class='it'>er/sie/es</td><td class='it'>wird</td></tr><tr><td class='it'>wir</td><td class='it'>werden</td></tr><tr><td class='it'>ihr</td><td class='it'>werdet</td></tr><tr><td class='it'>sie/Sie</td><td class='it'>werden</td></tr></tbody></table></div><p><em>Ich werde dich morgen anrufen. Es wird heute Abend regnen. Wir werden im Sommer nach Spanien fahren.</em> The Futur I is used to stress a promise, a decision or a prediction, or when there is no time expression to make the future clear: <em>Ich werde es nie vergessen.</em></p><p class='callout callout--trap'><b>For English speakers:</b> <em>werden</em> + infinitive looks like <em>will</em> + infinitive, with one difference: <em>will</em> is a modal with no endings, while <em>werden</em> is conjugated (<em>ich werde, du wirst, er wird</em>) and the infinitive goes to the end of the sentence. English uses <em>will</em> or <em>going to</em> for most future statements, but German speech prefers the present, much as English does with plans (<em>I’m going to the cinema tomorrow</em>): <em>Morgen gehe ich ins Kino</em> is the normal form; <em>Morgen werde ich ins Kino gehen</em> is correct but less frequent. <em>werden</em> is also a full verb: <em>Er wird Arzt</em> (he is becoming a doctor), <em>Es wird kalt</em> (it is getting cold): if there is no infinitive at the end, it is not a future. Using <em>werden</em> for assumptions about the present comes at later levels.</p><h4>C1: the future of supposition</h4><p>With <b>wohl</b>, <b>sicher</b> or <b>vermutlich</b>, the Futur I expresses a supposition about the present; the <b>Futur II</b> (<em>werden</em> + past participle + <em>haben</em> or <em>sein</em>) a supposition about the past, or an action that will be finished before a point in the future.</p><div class='table-wrap'><table class='gt'><thead><tr><th>example</th><th>meaning</th></tr></thead><tbody><tr><td class='it'>Er wird wohl müde sein.</td><td>supposition about the present</td></tr><tr><td class='it'>Sie wird den Zug wohl verpasst haben.</td><td>supposition about the past</td></tr><tr><td class='it'>Bis Montag werde ich den Bericht geschrieben haben.</td><td>finished before a future point</td></tr></tbody></table></div><p class='callout callout--trap'>English uses <em>must</em> or <em>will</em> for this: <em>he must be tired</em>, <em>she'll have missed the train</em>. German uses <em>werden</em>, and <em>wohl</em>, <em>sicher</em> or <em>vermutlich</em> make the supposition explicit; without an adverb the context decides, and <em>Er wird müde sein</em> can also be a prediction. The Futur II matches the English future perfect: <em>by Monday I will have written the report</em>.</p>"
  },
  "ref:g-praep-verben": {
    title: "Verbs with a fixed preposition",
    sub: "warten auf, denken an, sich freuen über: the preposition is part of the verb",
    body: "<p>Many verbs take a <b>fixed preposition</b> and a <b>fixed case</b>. Learn the verb together with its preposition and the case, the way you learn a noun with its article.</p><div class='table-wrap'><table class='gt'><thead><tr><th>verb + preposition</th><th>case</th><th>example</th></tr></thead><tbody><tr><td class='it'>warten auf</td><td>accusative</td><td class='it'>Ich warte auf den Bus.</td></tr><tr><td class='it'>denken an</td><td>accusative</td><td class='it'>Ich denke oft an meine Familie.</td></tr><tr><td class='it'>sich freuen auf (future)</td><td>accusative</td><td class='it'>Ich freue mich auf den Urlaub.</td></tr><tr><td class='it'>sich freuen über (present, past)</td><td>accusative</td><td class='it'>Ich freue mich über das Geschenk.</td></tr><tr><td class='it'>sich ärgern über</td><td>accusative</td><td class='it'>Er ärgert sich über den Lärm.</td></tr><tr><td class='it'>sich interessieren für</td><td>accusative</td><td class='it'>Sie interessiert sich für Musik.</td></tr><tr><td class='it'>sich kümmern um</td><td>accusative</td><td class='it'>Wir kümmern uns um die Kinder.</td></tr><tr><td class='it'>bitten um</td><td>accusative</td><td class='it'>Ich bitte um Hilfe.</td></tr><tr><td class='it'>träumen von</td><td>dative</td><td class='it'>Er träumt von einem Haus am Meer.</td></tr><tr><td class='it'>Angst haben vor</td><td>dative</td><td class='it'>Sie hat Angst vor dem Test.</td></tr><tr><td class='it'>teilnehmen an</td><td>dative</td><td class='it'>Wir nehmen an dem Kurs teil.</td></tr><tr><td class='it'>abhängen von</td><td>dative</td><td class='it'>Das hängt vom Wetter ab.</td></tr></tbody></table></div><p>The preposition <em>an</em> takes the accusative with <em>denken</em> and the dative with <em>teilnehmen</em>: the case cannot be worked out from the meaning, so learn it with the verb.</p><h4>darauf, worauf: the preposition without a noun</h4><p>For a <b>thing</b> or a situation already known, the preposition joins <b>da-</b> (<b>dar-</b> before a vowel): <em>Ich warte darauf. Ich freue mich darauf. Er denkt daran. Wir sprechen davon.</em> To ask the question you use <b>wo-</b> (<b>wor-</b> before a vowel): <em>Worauf wartest du? Woran denkst du? Wofür interessierst du dich?</em></p><p>For a <b>person</b> you use the preposition with the pronoun or with <em>wen, wem</em>: <em>Ich warte auf ihn. Auf wen wartest du? Mit wem sprichst du?</em></p><p><b>darauf</b> can also announce a subordinate clause or an infinitive: <em>Ich freue mich darauf, dass du kommst. Ich warte darauf, dich zu sehen.</em></p><p class='callout callout--trap'><b>For English speakers:</b> English also has verbs tied to a preposition, but the two languages rarely match one to one. English uses <em>for</em>, but German requires <em>auf</em> + accusative: <em>Ich warte auf den Bus</em>. Likewise <em>think of/about</em> is <em>denken an</em>, <em>be interested in</em> is <em>sich interessieren für</em> (not <em>in</em>), <em>be afraid of</em> is <em>Angst haben vor</em> (not <em>von</em>), <em>dream of</em> is <em>träumen von</em>, <em>ask for</em> is <em>bitten um</em>, <em>depend on</em> is <em>abhängen von</em>, <em>take part in</em> is <em>teilnehmen an</em>. Learn each German pair as given instead of translating the preposition.</p><p class='callout callout--trap'><b>For English speakers:</b> in a question English usually leaves the preposition at the end (<em>What are you thinking about? Who are you waiting for?</em>). German keeps it in front: <em>Woran denkst du?</em> for a thing, <em>Auf wen wartest du?</em> for a person. And where English says <em>for it, about it, of it</em>, German uses <em>darauf, daran, davon</em> for things only: <em>Ich denke daran</em> (<em>I’m thinking about it</em>). For a person the form does not exist: <em>Ich denke an ihn</em>.</p>"
  },
  "ref:g-konjunktiv2": {
    title: "The polite Konjunktiv II",
    sub: "Könnten Sie mir helfen? Ich hätte gern ...: requests and advice",
    body: "<p>The <b>Konjunktiv II</b> is used to make a sentence more polite or less direct. At this level a few forms of very frequent verbs are enough.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sein</th><th>haben</th><th>können</th><th>werden</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>wäre</td><td class='it'>hätte</td><td class='it'>könnte</td><td class='it'>würde</td></tr><tr><td class='it'>du</td><td class='it'>wärst</td><td class='it'>hättest</td><td class='it'>könntest</td><td class='it'>würdest</td></tr><tr><td class='it'>er/sie/es</td><td class='it'>wäre</td><td class='it'>hätte</td><td class='it'>könnte</td><td class='it'>würde</td></tr><tr><td class='it'>wir</td><td class='it'>wären</td><td class='it'>hätten</td><td class='it'>könnten</td><td class='it'>würden</td></tr><tr><td class='it'>ihr</td><td class='it'>wärt</td><td class='it'>hättet</td><td class='it'>könntet</td><td class='it'>würdet</td></tr><tr><td class='it'>sie/Sie</td><td class='it'>wären</td><td class='it'>hätten</td><td class='it'>könnten</td><td class='it'>würden</td></tr></tbody></table></div><h4>Requests, wishes, advice</h4><ul><li><b>Polite request</b>: <em>Könnten Sie mir bitte helfen? Würden Sie das Fenster öffnen? Hätten Sie einen Moment Zeit?</em></li><li><b>Wish</b>: <em>Ich hätte gern einen Kaffee. Ich möchte ein Zimmer.</em> <em>möchte</em> is also a Konjunktiv II (of <em>mögen</em>), and it is the polite form of <em>ich will</em>.</li><li><b>Advice</b>: <em>Du solltest mehr schlafen. Ich würde zum Arzt gehen.</em></li></ul><p>With most verbs the Konjunktiv II is formed with <b>würde + infinitive at the end</b> (<em>Ich würde gern nach Wien fahren</em>), and the proper forms (<em>wäre, hätte, könnte</em>) are used with the frequent verbs. For <em>sollen</em> and <em>wollen</em> the form coincides with the Präteritum (<em>du solltest</em>), and the context shows that it is a recommendation. The unreal condition (<em>Wenn ich Zeit hätte, ...</em>) is in the B1 part below; the past (<em>Wenn ich Zeit gehabt hätte, ...</em>) comes at later levels.</p><p class='callout callout--trap'><b>For English speakers:</b> English makes requests polite with <em>could, would</em> and <em>I’d like</em>, and German does the same with <em>könnte, würde, ich hätte gern</em>: <em>Könnten Sie mir helfen?</em> is <em>Could you help me?</em> and <em>würde helfen</em> is <em>would help</em>. The difference is that <em>could</em> does two jobs in English, and German splits them: <em>Ich konnte nicht</em> (Präteritum) is past ability, <em>I couldn’t</em>, while <em>Ich könnte</em> (Konjunktiv II) is polite or hypothetical, <em>I could</em>. The Konjunktiv II is a mood, not a tense. A request without it can come across as abrupt, as in English: <em>Können Sie mir helfen?</em> is fine, but <em>Könnten Sie mir helfen?</em> is softer, and <em>Ich will einen Kaffee</em> sounds as blunt as <em>I want a coffee</em>.</p><h4>B1: the complete Konjunktiv II in the present</h4><p>Every verb has a synthetic Konjunktiv II, but in everyday use you mostly hear it with <em>sein, haben</em>, the modals and a few frequent verbs (<em>wüsste, käme, ginge</em>). In <b>strong verbs</b> and in some frequent verbs the proper forms come from the <b>Präteritum</b>: same stem, often with an <b>Umlaut</b> on <em>a, o, u</em>, and the endings <em>-e, -est, -e, -en, -et, -en</em> (<em>war → wäre, kam → käme, ging → ginge</em>). In <b>weak verbs</b> the form is the same as the Präteritum, with no Umlaut (<em>machte, spielte</em>), which is why <em>würde</em> + infinitive is used instead. Some mixed verbs have proper forms to learn one by one (<em>wusste → wüsste, brachte → brächte, dachte → dächte</em>). With the <b>modal verbs</b> the Umlaut appears in the verbs that already have it in the infinitive:</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>können</th><th>müssen</th><th>dürfen</th><th>mögen</th><th>sollen</th><th>wollen</th></tr></thead><tbody><tr><td>ich/er</td><td class='it'>könnte</td><td class='it'>müsste</td><td class='it'>dürfte</td><td class='it'>möchte</td><td class='it'>sollte</td><td class='it'>wollte</td></tr><tr><td>du</td><td class='it'>könntest</td><td class='it'>müsstest</td><td class='it'>dürftest</td><td class='it'>möchtest</td><td class='it'>solltest</td><td class='it'>wolltest</td></tr><tr><td>wir/sie</td><td class='it'>könnten</td><td class='it'>müssten</td><td class='it'>dürften</td><td class='it'>möchten</td><td class='it'>sollten</td><td class='it'>wollten</td></tr></tbody></table></div><p>For <em>sollen</em> and <em>wollen</em> the form is the same as the Präteritum (<em>sollte, wollte</em>) and the context shows it is a Konjunktiv II. <em>Ich möchte</em> is the polite form you already know.</p><ul><li><b>Unreal condition</b>: <em>Wenn ich mehr Zeit hätte, würde ich reisen. Wenn ich du wäre, würde ich das nicht tun.</em> (the full construction is in the entry on the conditional clause)</li><li><b>Wish</b>: <em>Ich wäre gern Pilot. Wenn ich doch mehr Zeit hätte!</em></li><li><b>Advice</b>: <em>An deiner Stelle würde ich mit ihr sprechen. Du solltest mehr schlafen.</em></li><li><b>Cautious opinion</b>: <em>Ich würde sagen, dass das keine gute Idee ist. Das wäre schön.</em></li></ul><p>With most verbs (above all weak verbs, whose form would coincide with the Präteritum) you use <b>würde + infinitive</b>; the proper forms stay for <em>sein, haben</em>, the modals and a few frequent verbs like <em>wissen, kommen, gehen, geben</em>.</p><p class='callout callout--trap'><b>For English speakers:</b> English works the same way: for most verbs the hypothetical form is just the past (<em>If I worked less</em>), so you can’t tell it from a real past, and <em>would</em> does the rest. German weak verbs behave alike, which is why <em>würde</em> + infinitive takes over. <em>should</em> is <em>sollte</em> (advice: <em>Ich sollte mehr schlafen</em>); a stronger necessity (<em>I really have to see a doctor</em>) is <em>müsste</em>: <em>Ich müsste dringend zum Arzt</em>. In the if-clause German allows <em>würde</em>, which standard English avoids (<em>If I would have time</em>), but with <em>haben</em> or <em>sein</em> the proper forms are much more common: <em>Wenn ich Zeit hätte</em> is far more usual than <em>Wenn ich Zeit haben würde</em>, which is correct but heavier.</p><h4>B2: the past Konjunktiv II</h4><p>For a hypothesis or a regret about the <b>past</b>, German uses <b>hätte</b> or <b>wäre</b> + past participle. The choice between <em>hätte</em> and <em>wäre</em> follows the Perfekt: <em>wäre</em> with verbs of motion, change of state and <em>sein</em>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>Perfekt</th><th>past Konjunktiv II</th></tr></thead><tbody><tr><td>machen</td><td class='it'>ich habe gemacht</td><td class='it'>ich hätte gemacht</td></tr><tr><td>gehen</td><td class='it'>ich bin gegangen</td><td class='it'>ich wäre gegangen</td></tr><tr><td>sein</td><td class='it'>ich bin gewesen</td><td class='it'>ich wäre gewesen</td></tr><tr><td>wissen</td><td class='it'>ich habe gewusst</td><td class='it'>ich hätte gewusst</td></tr></tbody></table></div><ul><li><b>Regret</b>: <em>Hätte ich das bloß gewusst! Ich wäre gern mitgekommen.</em></li><li><b>Unreal hypothesis</b>: <em>Wenn du früher gekommen wärst, hättest du ihn gesehen.</em></li><li><b>Reproach</b>, with a modal and the double infinitive: <em>Du hättest mich anrufen können.</em></li></ul><p>The form <em>ich würde gemacht haben</em> exists but is rare and heavy: for the past, use <em>hätte</em> or <em>wäre</em>.</p><h4>B2: als ob, als wenn</h4><p><b>als ob</b> and <b>als wenn</b> (<em>as if</em>) introduce an unreal comparison with the Konjunktiv II and the verb at the end. For something happening at the same time, use the present (<em>Er tut so, als ob er nichts wüsste</em>); for something earlier, the past (<em>Sie sieht aus, als ob sie nicht geschlafen hätte</em>). With <b>als</b> alone the verb comes right after it: <em>Er tut so, als wüsste er nichts.</em></p><p class='callout callout--trap'><em>If I had known, I would have come</em>: English uses the past perfect in the if-clause and <em>would have</em> in the main clause. German uses the past Konjunktiv II in both halves: <em>Wenn ich es gewusst hätte, wäre ich gekommen.</em> Avoid <s>Wenn ich es gewusst habe</s>: the Perfekt is a real past, not a hypothesis. After <em>as if</em> English often uses a plain past (<em>as if he knew</em>); for unreal comparisons German usually takes the Konjunktiv II (<em>als ob er wüsste</em>), in speech often <em>würde</em>; the indicative and the Konjunktiv I also occur, but the Konjunktiv II is the form taught here.</p>"
  },
  "ref:g-konjunktiv1": {
    title: "Konjunktiv I and reported speech",
    sub: "Sie sagte, sie sei krank: reporting at a distance",
    body: "<p>Newspapers, minutes and reports render someone else's words with the <b>Konjunktiv I</b>: the writer signals that this is that person's account, not a fact the writer vouches for. It is formed from the infinitive stem with the endings <em>-e, -est, -e, -en, -et, -en</em> and is used mostly in the <b>third person singular</b>, where it differs from the indicative. <em>sein</em> is irregular: <em>ich sei, du seist, er sei, wir seien, ihr seiet, sie seien</em>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>infinitive</th><th>indicative</th><th>Konjunktiv I</th></tr></thead><tbody><tr><td>sein</td><td class='it'>er ist</td><td class='it'>er sei</td></tr><tr><td>haben</td><td class='it'>er hat</td><td class='it'>er habe</td></tr><tr><td>können</td><td class='it'>er kann</td><td class='it'>er könne</td></tr><tr><td>werden</td><td class='it'>er wird</td><td class='it'>er werde</td></tr><tr><td>wissen</td><td class='it'>er weiß</td><td class='it'>er wisse</td></tr><tr><td>kommen</td><td class='it'>er kommt</td><td class='it'>er komme</td></tr></tbody></table></div><p>The Konjunktiv I has a single past, with <em>habe</em> or <em>sei</em> + participle (<em>er habe gearbeitet, sie sei gegangen</em>), and a future with <em>werde</em> + infinitive (<em>er werde kommen</em>).</p><p>Where the Konjunktiv I looks like the indicative (<em>ich habe, wir haben, sie kommen</em>), German uses the <b>Konjunktiv II</b>: <em>Sie sagten, sie hätten keine Zeit.</em> If the Konjunktiv II also looks like the Präteritum, use <em>würde</em>: <em>Sie sagten, sie würden morgen anrufen.</em> In speech the indicative is common: <em>Er hat gesagt, er ist krank.</em></p><h4>Questions, commands, time and place</h4><ul><li><b>questions</b>: with <em>ob</em> or the question word, verb at the end. <em>Er fragte, ob ich Zeit hätte. Sie fragte, wann der Zug fahre.</em></li><li><b>commands</b>: with <em>sollen</em>. <em>Warte!</em> becomes <em>Sie sagte, ich solle warten.</em></li><li><b>person, time and place</b> shift as in English: <em>ich</em> becomes <em>er</em> or <em>sie</em>, <em>heute</em> becomes <em>an diesem Tag</em>, <em>morgen</em> becomes <em>am nächsten Tag</em>, <em>gestern</em> becomes <em>am Tag davor</em>, <em>hier</em> becomes <em>dort</em>. <em>Ich komme morgen.</em> becomes <em>Er sagte, er komme am nächsten Tag.</em></li></ul><p>With <em>dass</em> the verb goes to the end: <em>Sie sagte, dass sie krank sei.</em></p><p class='callout callout--trap'>English shifts the tense back in reported speech (<em>I am ill</em> becomes <em>she said she was ill</em>; <em>I will come</em> becomes <em>he said he would come</em>). German does not backshift: it keeps the time relation of the direct speech (present, past or future) and changes the mood; for the past, Konjunktiv I has a single compound form. <em>Ich bin krank</em> becomes <em>sie sei krank</em>, <em>Ich war krank</em> becomes <em>sie sei krank gewesen</em>, <em>Ich werde kommen</em> becomes <em>er werde kommen</em>. German does not backshift automatically: <em>sie sei krank</em> refers to the time of her words. <em>Sie sagte, sie war krank</em> is heard in speech, but it can be read as an earlier illness, and it gives up the distance that the Konjunktiv I marks in writing. Outside reported speech the Konjunktiv I appears in fixed formulas (<em>Es lebe ...!, Gott sei Dank!</em>), in instructions such as recipes (<em>Man nehme zwei Eier</em>) and in mathematical definitions (<em>Sei x eine natürliche Zahl</em>).</p>"
  },
  "ref:g-passiv": {
    title: "The passive",
    sub: "Das Formular wird ausgefüllt: werden + past participle",
    body: "<p>In the passive the attention goes to <b>what happens</b>, not to who does it. It is formed with a conjugated <b>werden</b> and the <b>past participle</b> at the end of the clause:</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>Präsens</th><th>Präteritum</th></tr></thead><tbody><tr><td>ich</td><td class='it'>werde gefragt</td><td class='it'>wurde gefragt</td></tr><tr><td>du</td><td class='it'>wirst gefragt</td><td class='it'>wurdest gefragt</td></tr><tr><td>er/sie/es</td><td class='it'>wird gefragt</td><td class='it'>wurde gefragt</td></tr><tr><td>wir</td><td class='it'>werden gefragt</td><td class='it'>wurden gefragt</td></tr><tr><td>ihr</td><td class='it'>werdet gefragt</td><td class='it'>wurdet gefragt</td></tr><tr><td>sie/Sie</td><td class='it'>werden gefragt</td><td class='it'>wurden gefragt</td></tr></tbody></table></div><p>The direct object of the active sentence (accusative) becomes the <b>subject</b> (nominative) of the passive sentence:</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>example</th></tr></thead><tbody><tr><td>active</td><td class='it'>Die Beamtin prüft den Antrag.</td></tr><tr><td>passive, present</td><td class='it'>Der Antrag wird (von der Beamtin) geprüft.</td></tr><tr><td>passive, Präteritum</td><td class='it'>Der Antrag wurde (von der Beamtin) geprüft.</td></tr></tbody></table></div><p>Who performs the action, if you need to say it, is introduced with <b>von + dative</b> (<em>von der Beamtin</em>); for a cause or a means you use <b>durch + accusative</b> (<em>Das Haus wurde durch einen Sturm beschädigt</em>). Very often there is no agent: <em>Hier wird nicht geraucht. Die Wohnung wurde gestern vermietet.</em></p><p>In a main declarative clause <em>werden</em> is in second position and the participle at the end; in a subordinate clause <em>werden</em> goes to the very end, after the participle: <em>..., dass der Antrag geprüft wird.</em> With a modal verb the passive uses an infinitive: <em>Der Antrag muss bis Freitag abgegeben werden.</em></p><p><b>wird geöffnet</b> describes the process, that is the action as it happens, now, habitually or in the future (<em>Die Tür wird um acht geöffnet</em>); <b>ist geöffnet</b> describes the resulting state (<em>Die Tür ist geöffnet</em>). They are two different passives: the first, with <em>werden</em>, is the process passive (Vorgangspassiv) and is the one in this entry; the second, with <em>sein</em>, is the state passive (Zustandspassiv) and comes back at level B2.</p><p class='callout callout--trap'><b>For English speakers:</b> English builds the passive with <em>be</em> (<em>the form is filled out</em>), and the same sentence can mean either the process (<em>is filled out by the clerk</em>) or the state (<em>is already filled out</em>). German keeps them apart: the process takes <b>werden</b>, the state takes <em>sein</em>. So <em>be</em> is not translated with <em>sein</em> here: <em>Das Formular wird ausgefüllt</em> is <em>is being filled out</em>, while <em>Das Formular ist ausgefüllt</em> means the form is already filled out.</p><p class='callout callout--trap'><b>For English speakers:</b> where English says <em>one</em> or <em>they</em> (<em>They speak German here</em>), German has two ways: the passive (<em>Hier wird Deutsch gesprochen</em>) or <em>man</em> with an active verb (<em>Hier spricht man Deutsch</em>). The passive suits formal texts such as forms and contracts; <em>man</em> suits speech.</p><h4>B2: the passive in the Perfekt, with modals, and the state passive</h4><p>In the <b>Perfekt</b> the passive is <b>sein</b> + past participle + <b>worden</b>; in the Plusquamperfekt it is <em>war</em> + participle + <em>worden</em>. With a <b>modal verb</b> the modal is conjugated and the passive stays in the infinitive (participle + <em>werden</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>example</th></tr></thead><tbody><tr><td>Perfekt</td><td class='it'>Das Haus ist 1900 gebaut worden.</td></tr><tr><td>Plusquamperfekt</td><td class='it'>Die Straße war schon gesperrt worden.</td></tr><tr><td>modal, present</td><td class='it'>Der Antrag muss bis Freitag geprüft werden.</td></tr><tr><td>modal, Präteritum</td><td class='it'>Das Problem konnte nicht gelöst werden.</td></tr><tr><td>subordinate clause</td><td class='it'>..., dass die Brücke renoviert worden ist.</td></tr></tbody></table></div><p>The <b>state passive</b> (Zustandspassiv) is <b>sein</b> + past participle and describes the result of a finished action: <em>Die Tür ist geschlossen. Das Geschäft war gestern geschlossen.</em> The process passive says what is happening: <em>Die Tür wird um acht geschlossen.</em></p><p class='callout callout--trap'>English has one auxiliary for both: <em>the door is closed</em> can be a state or a habit (<em>is closed at eight</em>). German splits them: <em>ist geschlossen</em> for the state, <em>wird geschlossen</em> for the action. In the passive Perfekt the participle of <em>werden</em> is <b>worden</b>, not <em>geworden</em>, which is the full verb (<em>Er ist Arzt geworden</em>). <em>Has been built</em> is <em>ist gebaut worden</em>, never <s>hat gebaut gewesen</s>.</p><h4>C1: alternatives to the passive</h4><p>In formal texts German also expresses possibility or necessity without naming who acts, using forms that combine the passive idea with a modal meaning:</p><div class='table-wrap'><table class='gt'><thead><tr><th>form</th><th>meaning</th><th>example</th></tr></thead><tbody><tr><td class='it'>sich lassen + infinitive</td><td>can be done</td><td class='it'>Das lässt sich leicht erklären.</td></tr><tr><td class='it'>sein + zu + infinitive</td><td>can or must be done</td><td class='it'>Der Antrag ist bis Freitag abzugeben. Das ist nicht zu ändern.</td></tr><tr><td class='it'>adjective in -bar</td><td>-able</td><td class='it'>Das Wasser ist trinkbar. Die Aufgabe ist lösbar.</td></tr><tr><td class='it'>man + active verb</td><td>impersonal</td><td class='it'>Das macht man so.</td></tr></tbody></table></div><p><em>sein + zu</em> can mean “can be” or “must be”: the context decides, and in regulations it is usually an obligation (<em>Der Antrag ist abzugeben</em> = <em>muss abgegeben werden</em>). With a separable verb, <em>zu</em> goes between the particle and the verb: <em>abzugeben</em>.</p><p class='callout callout--trap'>English <em>to be</em> + <em>to</em>-infinitive is a close match: <em>the form is to be handed in by Friday</em> = <em>ist bis Freitag abzugeben</em>. And the suffix <em>-bar</em> works like <em>-able</em>: <em>trinkbar</em> “drinkable”, <em>lösbar</em> “solvable”. <em>sich lassen</em> is not “let itself”: <em>Das lässt sich erklären</em> is “that can be explained”.</p>"
  },
  "ref:g-praep-akk": {
    title: "Prepositions with the accusative",
    sub: "für, ohne, um, durch, gegen",
    body: "<p>These prepositions always take the <b>accusative</b>, so only the masculine changes (<em>den, einen, keinen, meinen</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>meaning</th><th>example</th></tr></thead><tbody><tr><td class='it'>für</td><td>for</td><td class='it'>Das Geschenk ist für den Lehrer.</td></tr><tr><td class='it'>ohne</td><td>without</td><td class='it'>Ich trinke Kaffee ohne Zucker.</td></tr><tr><td class='it'>um</td><td>around; at (clock times)</td><td class='it'>Wir gehen um die Ecke. Um acht Uhr.</td></tr><tr><td class='it'>durch</td><td>through</td><td class='it'>Wir gehen durch den Park.</td></tr><tr><td class='it'>gegen</td><td>against; around (approximate time)</td><td class='it'>Ich bin gegen den Plan.</td></tr></tbody></table></div><p>With pronouns: <em>für mich, für dich, für ihn, ohne sie, gegen uns</em>. A useful phrase for the city: <em>Gehen wir ins Kino?</em> (<em>ins</em> = <em>in das</em>; the use of <em>in</em> with movement comes later).</p><p class='callout callout--trap'><b>For English speakers:</b> English nouns do not change after a preposition (<em>for the man</em>); only pronouns do (<em>for him</em>). German does the same with pronouns (<em>für ihn</em>) but also marks the case on the masculine article: <em>für den Mann</em>, <em>für einen Freund</em>, not <em>*für der Mann</em>. With <em>ohne</em> before a mass noun the article is normally left out, as in English (<em>ohne Zucker, ohne Milch</em>).</p>"
  },
  "ref:g-praep-dativ": {
    title: "Prepositions with the dative",
    sub: "mit, zu, bei, aus, von, nach, seit",
    body: "<p>These seven prepositions always take the <b>dative</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>meaning</th><th>example</th></tr></thead><tbody><tr><td class='it'>mit</td><td>with; by (means of transport)</td><td class='it'>Ich fahre mit dem Bus.</td></tr><tr><td class='it'>zu</td><td>to (a person or a place)</td><td class='it'>Ich gehe zum Bahnhof. Wir gehen zur Schule.</td></tr><tr><td class='it'>bei</td><td>at (someone’s place), near</td><td class='it'>Ich wohne bei meiner Tante. Er ist beim Arzt.</td></tr><tr><td class='it'>aus</td><td>from (origin), out of</td><td class='it'>Ich komme aus Italien.</td></tr><tr><td class='it'>von</td><td>from (starting point), of, by</td><td class='it'>Der Brief ist von meiner Mutter.</td></tr><tr><td class='it'>nach</td><td>to (cities and countries without an article); after</td><td class='it'>Ich fahre nach Berlin. Wir fliegen nach Italien. Nach dem Essen.</td></tr><tr><td class='it'>seit</td><td>since, for (with a duration)</td><td class='it'>Ich wohne seit einem Jahr hier.</td></tr></tbody></table></div><p>Many prepositions merge with the article: <b>zu dem → zum</b>, <b>zu der → zur</b>, <b>bei dem → beim</b>, <b>von dem → vom</b>. <em>Gehen Sie zum Bahnhof. Er ist beim Friseur. Ich komme vom Bahnhof.</em> English has no such contractions, so learn them as single words.</p><p class='callout callout--trap'><b>For English speakers:</b> <em>by bus</em> is <b>mit dem Bus</b> (<em>Ich fahre mit dem Bus</em>): German uses <em>mit</em> and an article, while <em>im Bus</em> means being inside the vehicle (<em>Ich sitze im Bus</em>). <em>to</em> splits three ways: <em>zu</em> (<em>zum Arzt, zum Bahnhof</em>), <em>nach</em> (<em>nach Berlin</em>) and, for countries that have an article, <em>in</em> + accusative (<em>in die Schweiz, in die Türkei, in die USA</em>), a contrast to know, not to use yet. <em>from</em> splits too: <em>aus</em> for origin (<em>Ich komme aus Rom</em>) and <em>von</em> for a starting point (<em>vom Bahnhof</em>). And with <em>seit</em> German uses the <b>present tense</b> where English uses the present perfect: <em>Ich wohne seit einem Jahr hier</em> is <em>I have lived here for a year</em>. Some fixed phrases: <em>zu Fuß</em> (on foot), <em>nach Hause</em> (home, as in <em>I’m going home</em>), <em>zu Hause</em> (at home).</p>"
  },
  "ref:g-wechselpraep": {
    title: "Prepositions with dative or accusative",
    sub: "wo? with the dative: in, an, auf, vor, hinter, neben, ...",
    body: "<p>Nine prepositions can take either the dative or the accusative. For now you only see the answer to <b>wo?</b> (where? position, location), which takes the <b>dative</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>meaning</th><th>example</th></tr></thead><tbody><tr><td class='it'>in</td><td>in, inside</td><td class='it'>Ich bin in der Küche. Er wohnt in der Stadt.</td></tr><tr><td class='it'>an</td><td>on (a wall, an edge); at</td><td class='it'>Das Bild hängt an der Wand. Ich sitze am Fenster.</td></tr><tr><td class='it'>auf</td><td>on, on top of</td><td class='it'>Das Buch liegt auf dem Tisch.</td></tr><tr><td class='it'>vor</td><td>in front of</td><td class='it'>Der Bus hält vor dem Hotel.</td></tr><tr><td class='it'>hinter</td><td>behind</td><td class='it'>Der Bahnhof ist hinter dem Rathaus.</td></tr><tr><td class='it'>neben</td><td>next to</td><td class='it'>Das Café ist neben der Post.</td></tr><tr><td class='it'>über</td><td>above, over (no contact)</td><td class='it'>Die Lampe hängt über dem Tisch.</td></tr><tr><td class='it'>unter</td><td>under</td><td class='it'>Die Katze schläft unter dem Tisch.</td></tr><tr><td class='it'>zwischen</td><td>between</td><td class='it'>Das Kino ist zwischen der Bank und dem Park.</td></tr></tbody></table></div><p>Contractions: <b>in dem → im</b>, <b>an dem → am</b>: <em>Ich bin im Park. Wir sind am Bahnhof.</em> Question: <em>Wo ist der Bahnhof? Hinter dem Rathaus.</em></p><p class='callout callout--trap'><b>For English speakers:</b> English sometimes marks the difference between location and movement with a different word (<em>in / into, on / onto</em>); German uses the <b>same preposition</b> and changes the case: <em>in der Küche</em> (dative) is where you <em>are</em>, while movement into the place (<em>in die Küche</em>, accusative) is in the A2 part below. First ask yourself <em>wo?</em>: then use the dative. Also, English <em>on</em> covers two German words: <em>auf dem Tisch</em> (on top of) and <em>an der Wand</em> (on a vertical surface, hanging). <em>an</em> is also <em>at</em>: <em>am Fenster, am Bahnhof</em>.</p><h4>A2: wohin? with the accusative</h4><p>When the sentence answers <b>wohin?</b> (where to?), that is, there is a movement or a change of place toward the location, the same prepositions take the <b>accusative</b>: <em>Ich gehe in die Küche. Er legt das Buch auf den Tisch. Wir fahren ans Meer.</em> The contractions are <em>in das → ins, an das → ans, auf das → aufs</em>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>wo? (dative)</th><th>wohin? (accusative)</th></tr></thead><tbody><tr><td class='it'>Ich bin im Park.</td><td class='it'>Ich gehe in den Park.</td></tr><tr><td class='it'>Das Buch liegt auf dem Tisch.</td><td class='it'>Ich lege das Buch auf den Tisch.</td></tr><tr><td class='it'>Die Flasche steht auf dem Tisch.</td><td class='it'>Ich stelle die Flasche auf den Tisch.</td></tr><tr><td class='it'>Er sitzt am Fenster.</td><td class='it'>Er setzt sich ans Fenster.</td></tr></tbody></table></div><p>German chooses the verb according to the position of the object: <b>stellen / stehen</b> for an upright object, <b>legen / liegen</b> for one lying flat, <b>setzen / sitzen</b> for someone sitting down or sitting. The verbs of action (<em>stellen, legen, setzen</em>) go with <em>wohin</em> and the accusative; those of state (<em>stehen, liegen, sitzen</em>) go with <em>wo</em> and the dative. With names of cities and countries without an article you use <em>nach</em> (<em>Ich fahre nach Berlin</em>), with people <em>zu</em> + dative (<em>Ich gehe zu meiner Freundin</em>).</p><p class='callout callout--trap'><b>For English speakers:</b> English <em>put</em> covers several German placement verbs (<em>stellen, legen, setzen</em>: <em>I put the book on the table</em>), while for position English often just uses <em>be</em> (<em>the book is on the table</em>) where German distinguishes <em>stehen, liegen, sitzen</em>; it marks movement with <em>into</em> and <em>onto</em> only sometimes. English does have pairs like <em>lay / lie</em> and <em>set / sit</em>, but German makes the distinction systematically and twice: with the <b>verb</b> (<em>stellen / stehen</em>, <em>legen / liegen</em>) and with the <b>case</b> (accusative / dative). German <em>stellen</em> and <em>legen</em> are both <em>put</em>: you choose by whether the thing stands or lies.</p>"
  },
  "ref:g-temporalangaben": {
    title: "Time, days, months and dates",
    sub: "um, am, im; von ... bis, vor, seit",
    body: "<h4>The time</h4><p><em>Wie spät ist es?</em> / <em>Wie viel Uhr ist es?</em> Answer: <em>Es ist acht Uhr.</em> For a precise time: <em>Um acht Uhr.</em></p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>time</th></tr></thead><tbody><tr><td>7:00</td><td class='it'>Es ist sieben Uhr.</td></tr><tr><td>7:15</td><td class='it'>Es ist Viertel nach sieben.</td></tr><tr><td>7:30</td><td class='it'>Es ist <b>halb acht</b>.</td></tr><tr><td>7:45</td><td class='it'>Es ist Viertel vor acht.</td></tr><tr><td>7:10</td><td class='it'>Es ist zehn nach sieben.</td></tr><tr><td>7:50</td><td class='it'>Es ist zehn vor acht.</td></tr></tbody></table></div><p class='callout callout--trap'><b>For English speakers:</b> <b><em>halb acht</em> is half past seven</b>, not half past eight: German counts toward the hour that is coming, while English <em>half past seven</em> counts from the hour that has just gone by. This is the most common trap. <em>Viertel nach / Viertel vor</em> work like <em>quarter past / quarter to</em>, and <em>zehn nach / zehn vor</em> like <em>ten past / ten to</em>.</p><h4>Prepositions of time</h4><ul><li><b>um</b> + clock time: <em>um acht Uhr</em> (at eight)</li><li><b>am</b> + day, part of the day, date: <em>am Montag, am Abend, am 3. Mai</em> (but <em>in der Nacht</em>)</li><li><b>im</b> + month, season: <em>im Januar, im Sommer</em></li><li><b>von ... bis</b>: <em>von Montag bis Freitag, von acht bis vier</em></li><li><b>vor</b> (ago) and <b>seit</b> (since) + dative: <em>vor einer Woche, seit Montag</em></li></ul><p>The days: <em>Montag, Dienstag, Mittwoch, Donnerstag, Freitag, Samstag, Sonntag</em>. With <b>-s</b> you say that something happens every time: <em>montags, morgens, abends</em> (on Mondays, in the mornings, in the evenings). Dates use the ordinal, as in English <em>May 3rd</em>: <em>am ersten, zweiten, dritten, vierten Mai</em>; written <em>am 1. Mai</em>.</p><p class='callout callout--trap'><b>For English speakers:</b> the prepositions do not map one to one. <em>in the evening</em> is <em>am Abend</em> (not <em>in</em>), while <em>at night</em> is <em>in der Nacht</em>; <em>on Monday</em> is <em>am Montag</em> and <em>in January</em> is <em>im Januar</em>. <em>ago</em> goes <b>before</b> the noun: <em>a week ago</em> is <em>vor einer Woche</em>. And, as with <em>seit</em> above, German uses the present tense where English uses the present perfect: <em>seit Montag</em> in <em>Ich bin seit Montag hier</em> is <em>I have been here since Monday</em>.</p>"
  },
  "ref:g-satz-v2": {
    title: "Verb in second position",
    sub: "V2, inversion, questions",
    body: "<p>In a German declarative main clause the <b>conjugated verb is always the second element</b>. The first position can be the subject, but also a time or place word. English keeps subject-verb-object almost always; German keeps only the verb fixed.</p><ul><li><em>Ich gehe heute ins Kino.</em></li><li><em>Heute <b>gehe</b> ich ins Kino.</em> (the subject moves behind the verb: <b>inversion</b>)</li></ul><p class='callout callout--trap'><b>For English speakers:</b> the English order <em>Today I go</em> does not carry over: <em>*Heute ich gehe</em> is wrong. German says <em>Heute gehe ich</em>, with the verb still in second place: time word first, then the verb, then the subject.</p><h4>Questions</h4><ul><li><b>W-questions</b>: question word, then the verb: <em>Wo wohnst du? Was trinkst du? Wann kommt er?</em></li><li><b>Yes/no questions</b>: the verb goes <b>first</b>: <em>Kommst du aus Berlin? Hast du Zeit?</em></li></ul><p>German has no <em>do</em>-support: not <em>*Machst du trinken?</em>. You simply move the verb: <em>Trinkst du Kaffee?</em> Words like <em>und, aber, oder</em> do not count as a position, so the verb is still second after them.</p>"
  },
  "ref:g-negation": {
    title: "Negation: nicht and kein",
    sub: "nicht vs kein, position, doch",
    body: "<p>German has two negators, where English uses <em>not</em> and <em>no</em>.</p><ul><li><b>kein</b> negates a <b>noun with an indefinite article or no article</b>: <em>Ich habe einen Hund → Ich habe keinen Hund. Ich habe Zeit → Ich habe keine Zeit.</em> It takes the endings of <em>ein</em> (<em>keinen, keine, kein</em>).</li><li><b>nicht</b> negates <b>everything else</b>: verbs, adjectives, adverbs, nouns with a definite article: <em>Ich komme nicht. Das ist nicht gut. Ich nehme den Kaffee nicht.</em></li></ul><h4>Position of nicht</h4><ul><li>In a simple sentence it goes at the <b>end</b> when the whole sentence is negated: <em>Ich kenne ihn nicht.</em> If the sentence ends in an infinitive or a separable particle, <em>nicht</em> comes before that final verb part; its exact position depends on what is negated, and other complements may stand in between: <em>Ich kann nicht kommen. Ich kann nicht nach Berlin kommen. Ich rufe ihn nicht an. Ich rufe nicht jeden Tag an.</em></li><li>Placement is a tendency, not a fixed rule: it usually goes <b>before</b> an adjective, adverb, destination or predicate: <em>Das ist nicht teuer. Er wohnt nicht hier.</em></li></ul><h4>doch</h4><p>To contradict a negative question or statement, German uses <b>doch</b> where English says <em>yes</em>: <em>Kommst du nicht? - Doch, ich komme!</em> (Yes, I am coming.) <em>Doch</em> contradicts the negation explicitly. To confirm it, say <em>Nein, ich komme nicht</em>; a bare <em>ja</em> can be ambiguous.</p><p class='callout callout--trap'><b>For English speakers:</b> there is no <em>do not</em>. <em>I don't drink coffee</em> is <em>Ich trinke keinen Kaffee</em>, while <em>Ich trinke den Kaffee nicht</em> means <em>I'm not drinking the coffee</em> (that particular one); the verb never changes shape.</p>"
  },
  "ref:g-konnektoren": {
    title: "Linking clauses: und, aber, oder, denn",
    sub: "position zero: the word order does not change",
    body: "<p>These four conjunctions link two main clauses and stand in <b>position zero</b>: they do not count as the first element and they do not change the order of their clause: the verb stays in <b>second position</b> in statements and in <b>first position</b> in yes/no questions (<em>Gehen wir ins Kino, oder bleiben wir zu Hause?</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>meaning</th><th>example</th></tr></thead><tbody><tr><td class='it'>und</td><td>and</td><td class='it'>Ich gehe ins Kino, und er bleibt zu Hause.</td></tr><tr><td class='it'>aber</td><td>but</td><td class='it'>Ich bin müde, aber ich gehe ins Kino.</td></tr><tr><td class='it'>oder</td><td>or</td><td class='it'>Gehen wir ins Kino, oder bleiben wir zu Hause?</td></tr><tr><td class='it'>denn</td><td>because, for (gives the reason)</td><td class='it'>Ich bleibe zu Hause, denn ich bin müde.</td></tr></tbody></table></div><p>In a clause that starts with the subject, the subject stays before the verb; if the second clause has another element in front, the verb keeps its position anyway: <em>Ich arbeite, aber am Samstag habe ich frei.</em> If the subject is the same it can be left out after <b>und, oder, aber</b>: <em>Ich gehe ins Kino und sehe einen Film.</em> Not after <b>denn</b>: the subject is repeated (<em>Ich bleibe zu Hause, denn ich bin müde</em>).</p><p>Before <b>aber</b> and <b>denn</b> the comma is required; before <b>und</b> and <b>oder</b> it is optional between two main clauses.</p><p class='callout callout--trap'><b>For English speakers:</b> after <em>but</em> English keeps subject-then-verb (<em>but on Saturday I’m off</em>), whereas German puts the verb second even after a time phrase, so the subject moves behind it: <em>aber am Samstag habe ich frei</em>. German also requires the comma before <em>aber</em> and <em>denn</em>, which English often leaves out. <em>because</em> has two German equivalents: <b>denn</b> gives the reason and does <b>not</b> move the verb (<em>denn ich bin müde</em>); it introduces the reason for a preceding statement and keeps main-clause order, and it can start a new sentence (<em>Ich bleibe zu Hause. Denn ich bin müde.</em>); <b>weil</b>, which sends the verb to the end, has its own entry. With <em>denn</em> the verb stays where it is.</p><h4>A2: deshalb and trotzdem</h4><p><b>deshalb</b> (that is why, therefore) and <b>trotzdem</b> (still, nevertheless) connect two main clauses, but they behave differently from <em>und, aber, denn</em>: they occupy the <b>first position</b> of the second clause, so the <b>verb comes right after</b> and the subject follows it.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>meaning</th><th>example</th></tr></thead><tbody><tr><td class='it'>deshalb</td><td>consequence</td><td class='it'>Es regnet. Deshalb bleibe ich zu Hause.</td></tr><tr><td class='it'>trotzdem</td><td>contrast, in spite of everything</td><td class='it'>Ich bin müde. Trotzdem gehe ich ins Kino.</td></tr></tbody></table></div><p>They can be used after a period or after a comma, and they can also stand further along in the sentence, without taking the first position: <em>Ich bleibe deshalb zu Hause.</em> Synonyms of <em>deshalb</em>: <em>deswegen, darum</em>.</p><p class='callout callout--trap'><b>For English speakers:</b> English adverbs like <em>therefore, however</em> or <em>still</em> do not change the order of the sentence (<em>It’s raining. Therefore I stay home</em>). German <em>deshalb</em> and <em>trotzdem</em> invert subject and verb: <em>Deshalb <b>bleibe ich</b></em>, not <em>*Deshalb ich bleibe</em>. They are not subordinating conjunctions either: they do not send the verb to the end, as <em>weil</em> does.</p><h4>B1: zwar ... aber, sowohl ... als auch, weder ... noch</h4><p>Some conjunctions work in pairs and link two elements.</p><div class='table-wrap'><table class='gt'><thead><tr><th>pair</th><th>meaning</th><th>example</th></tr></thead><tbody><tr><td class='it'>zwar ... aber</td><td>it is true that ... but</td><td class='it'>Das Hotel ist zwar teuer, aber es liegt zentral.</td></tr><tr><td class='it'>sowohl ... als auch</td><td>both ... and</td><td class='it'>Sie spricht sowohl Deutsch als auch Englisch.</td></tr><tr><td class='it'>weder ... noch</td><td>neither ... nor</td><td class='it'>Ich habe weder Zeit noch Lust.</td></tr></tbody></table></div><p><b>zwar</b> concedes something, <b>aber</b> introduces the contrast and stays in position zero (the verb is in second position after the element that follows). <em>zwar</em> can also stand at the beginning: <em>Zwar ist das Hotel teuer, aber es liegt zentral.</em> With <b>sowohl ... als auch</b> and <b>weder ... noch</b> the two elements can be subjects: <em>Sowohl Anna als auch Tom kommen.</em> With <em>weder ... noch</em> the verb is already negated: you do not add <em>nicht</em> or <em>kein</em>.</p><p>For the contrast with <em>obwohl</em> and <em>trotzdem</em> see the entry on the concessive.</p><p class='callout callout--trap'><b>For English speakers:</b> <em>both ... and</em> and <em>neither ... nor</em> map directly, and as in English you do not add a second negative: <em>Ich habe weder Zeit noch Lust</em>, not <s>Ich habe nicht weder Zeit noch Lust</s> (compare <em>I have neither time nor desire</em>). <em>zwar ... aber</em> has no fixed equivalent in English: it is rendered with <em>it’s true that ... but</em>, <em>admittedly ... but</em> or just <em>but</em>, while in German the <em>zwar</em> is a signal that the contrast is coming and the pair is much more frequent.</p><h4>B2: einerseits ... andererseits, jedoch, allerdings, sondern, vielmehr</h4><ul><li><b>einerseits ... andererseits</b> (<em>on the one hand ... on the other</em>): <em>Einerseits ist die Stadt teuer, andererseits gibt es dort viele Jobs.</em></li><li><b>jedoch</b> (<em>however</em>) stands in first position, with the verb right after it, or inside the clause: <em>Das Angebot ist gut, jedoch ist der Preis hoch. Der Preis ist jedoch hoch.</em></li><li><b>allerdings</b> (<em>admittedly, though</em>) limits what was just said: <em>Das Hotel war schön, allerdings war es etwas laut.</em></li><li><b>sondern</b> corrects after a negation: <em>Er kommt nicht heute, sondern morgen.</em></li><li><b>vielmehr</b> (<em>rather</em>) strengthens the correction: <em>Das ist kein Problem, vielmehr ist es eine Chance.</em></li></ul><p class='callout callout--trap'>English <em>but</em> has two German translations. Use <em>aber</em> when the second part adds a contrast (<em>Er ist müde, aber er arbeitet</em>), and <em>sondern</em> when it replaces what was denied (<em>nicht ich, sondern du</em>: <em>not me but you</em>). After <em>nicht</em> or <em>kein</em> with a replacement, <em>aber</em> is wrong. And <em>jedoch</em> in first position makes the verb come next, unlike English <em>however</em> followed by a comma.</p>"
  },
  "ref:g-wortstellung": {
    title: "Word order in the middle field",
    sub: "dative and accusative, pronouns and nouns; time, cause, manner, place",
    body: "<p>Between the conjugated verb (second position) and the second verbal element at the end lies the <b>middle field</b> (<em>Mittelfeld</em>). The order of its elements follows a few basic rules, which give the neutral form of the sentence: to stress something, you can move it to the front.</p><h4>Objects: dative and accusative</h4><div class='table-wrap'><table class='gt'><thead><tr><th>type</th><th>example</th></tr></thead><tbody><tr><td>two nouns: dative first</td><td class='it'>Ich schenke meiner Schwester ein Buch.</td></tr><tr><td>pronoun and noun: the pronoun first</td><td class='it'>Ich schenke ihr ein Buch. Ich schenke es meiner Schwester.</td></tr><tr><td>two pronouns: accusative first</td><td class='it'>Ich schenke es ihr.</td></tr></tbody></table></div><p>In short: <b>pronouns come before nouns</b>; between two nouns the <b>dative</b> comes before the accusative; between two pronouns the <b>accusative</b> comes before the dative.</p><h4>Details: time, cause, manner, place</h4><p>The elements that say <em>when, why, how, where</em> usually follow the order <b>te-ka-mo-lo</b> (temporal, kausal, modal, lokal): <em>Ich fahre morgen wegen der Arbeit mit dem Zug nach Berlin.</em> You do not need all of them at once: just keep the order of the elements that are present (<em>Ich fahre morgen mit dem Zug nach Berlin</em>).</p><p>The second verbal element stays at the end, so the whole middle field sits between the two: <em>Ich habe gestern meiner Schwester ein Buch geschenkt.</em></p><p class='callout callout--trap'><b>For English speakers:</b> two things match and one does not. For objects, English <em>I give my sister a book</em> has the same order as German (indirect object first, no <em>to</em>), and with two pronouns <em>I give it to her</em> puts the thing first, just like <em>Ich schenke es ihr</em>. The difference is in the details: English often puts the time expression last (<em>I’m going to Berlin by train tomorrow</em>), while German starts with time and ends with place (<em>morgen, mit dem Zug, nach Berlin</em>): the time comes early in the middle field. This is not a rigid rule: it helps you build natural sentences and recognize when the order is marked.</p>"
  },
  "ref:g-nebensatz-weil": {
    title: "The causal clause with weil and da",
    sub: "weil ich müde bin: the conjugated verb goes to the end",
    body: "<p><b>weil</b> (because) and <b>da</b> (since, as) introduce a <b>subordinate</b> clause: the conjugated verb goes <b>to the end</b>, and there is always a comma between the main clause and the subordinate clause.</p><p><em>Ich bleibe zu Hause, weil ich müde bin. Er kommt nicht, weil er krank ist.</em></p><div class='table-wrap'><table class='gt'><thead><tr><th>situation</th><th>example</th></tr></thead><tbody><tr><td>simple verb</td><td class='it'>weil ich müde bin</td></tr><tr><td>separable verb (prefix joined back)</td><td class='it'>weil ich früh aufstehe</td></tr><tr><td>modal verb: the modal at the end</td><td class='it'>weil ich arbeiten muss</td></tr><tr><td>Perfekt: auxiliary at the end</td><td class='it'>weil ich viel gearbeitet habe</td></tr></tbody></table></div><p>If the subordinate clause comes <b>first</b>, the main clause begins with the conjugated verb, right after the comma: <em>Weil ich müde bin, bleibe ich zu Hause.</em> <b>Da</b> does the same job, but it is usually found at the start of the sentence and in writing: <em>Da es regnet, bleiben wir zu Hause.</em> The question <em>Warum?</em> can be answered with the subordinate clause alone: <em>Warum kommst du nicht? Weil ich krank bin.</em></p><p class='callout callout--trap'><b>For English speakers:</b> English <em>because</em> does not change the word order: <em>I stay home because I’m tired</em>. German <b>weil</b> sends the verb to the end (<em>..., weil ich müde bin</em>), and the verb ends up after everything else: <em>..., weil ich arbeiten muss</em>, <em>..., weil ich viel gearbeitet habe</em>. There is also a comma, which English usually leaves out before <em>because</em>. English <em>because</em> has two German equivalents: <b>weil</b> (verb at the end) and <b>denn</b> (verb stays in second position, as in English: <em>Ich bleibe zu Hause, denn ich bin müde</em>). English <em>since</em> in the sense of <em>as</em> is <em>da</em>. In a direct question you say <em>warum</em>, not <em>*weil</em>.</p>"
  },
  "ref:g-nebensatz-temporal": {
    title: "When: als and wenn",
    sub: "als for a single past event, wenn for repeated events and the present",
    body: "<p>English has one <em>when</em>; German has three, depending on the situation. <b>als</b> and <b>wenn</b> introduce temporal subordinate clauses: the conjugated verb goes <b>to the end</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>situation</th><th>word</th><th>example</th></tr></thead><tbody><tr><td>a single event in the past</td><td class='it'>als</td><td class='it'>Als ich ankam, hat es geregnet.</td></tr><tr><td>a repeated event, also in the past</td><td class='it'>wenn</td><td class='it'>Immer wenn ich ihn sehe, lacht er.</td></tr><tr><td>present or future</td><td class='it'>wenn</td><td class='it'>Wenn ich müde bin, trinke ich Kaffee.</td></tr><tr><td>direct or indirect question</td><td class='it'>wann</td><td class='it'>Wann kommst du? Ich weiß nicht, wann er kommt.</td></tr></tbody></table></div><p>More examples with <b>als</b>: <em>Als ich ein Kind war, haben wir in Rom gewohnt. Als wir in Berlin waren, haben wir viel gesehen.</em> With <b>wenn</b> in the future: <em>Wenn ich morgen Zeit habe, rufe ich dich an.</em> If the subordinate clause comes first, the main clause begins with the conjugated verb: <em>Als ich ankam, hat es geregnet.</em></p><p class='callout callout--trap'><b>For English speakers:</b> English <em>when</em> is split three ways here: <b>als</b> (one past event: <em>when I arrived</em>), <b>wenn</b> (repeated or present and future: <em>whenever I see him, when I’m tired, when I have time tomorrow</em>) and <b>wann</b> (only in questions: <em>when are you coming? I don’t know when he’s coming</em>). Since <em>wenn</em> can also mean <em>if</em> (<em>Wenn es regnet, bleibe ich zu Hause</em>), the English <em>if</em> in the sense of <em>whether</em> is a different word, <em>ob</em> (see the entry on <em>dass</em> and <em>ob</em>). Like English, German uses the present tense after <em>wenn</em> for the future: <em>Wenn ich morgen Zeit habe</em>, <em>If I have time tomorrow</em>. <em>nachdem</em> and <em>bevor</em> are in the B1 part below; other time conjunctions (<em>seit, bis, während</em>) come at later levels.</p><h4>B1: nachdem and bevor</h4><p><b>nachdem</b> (after) and <b>bevor</b> (before; also <em>ehe</em>) introduce temporal subordinate clauses with the verb at the end. <b>nachdem</b> says that the action of the subordinate clause has <b>already happened</b> when the action of the main clause begins, and for this reason the subordinate clause is one tense <b>earlier</b>:</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>subordinate clause</th><th>main clause</th></tr></thead><tbody><tr><td>past (written texts)</td><td class='it'>Nachdem ich gegessen hatte,</td><td class='it'>ging ich spazieren.</td></tr><tr><td>past (speech)</td><td class='it'>Nachdem ich gegessen hatte,</td><td class='it'>bin ich spazieren gegangen.</td></tr><tr><td>present</td><td class='it'>Nachdem ich gegessen habe,</td><td class='it'>gehe ich spazieren.</td></tr><tr><td>bevor</td><td class='it'>Bevor ich gehe,</td><td class='it'>rufe ich dich an.</td></tr></tbody></table></div><p>With <em>nachdem</em> the standard pattern, especially in writing, is the <b>Plusquamperfekt</b> in the subordinate clause if the main clause is in the past, and in the <b>Perfekt</b> if the main clause is in the present. With <em>bevor</em> the verbs usually have the same tense: <em>Bevor ich ging, rief ich dich an. Ruf mich an, bevor du gehst.</em></p><p class='callout callout--trap'><b>For English speakers:</b> English often uses a gerund after <em>after</em> and <em>before</em> (<em>After eating, I went out; Before leaving, I’ll call you</em>). German needs a subordinate clause with its own subject: <em>Nachdem ich gegessen hatte, ...</em>, <em>Bevor ich gehe, ...</em>. The tenses are familiar: English also uses a perfect for the earlier event (<em>After I had eaten ...</em>) and the present for the future (<em>Before I leave, I’ll call you</em>), though in everyday English the simple past often replaces <em>had eaten</em>; German marks the earlier event. With a noun you can say <em>nach dem Essen</em> and <em>vor dem Gehen</em>.</p>"
  },
  "ref:g-nebensatz-dass": {
    title: "dass, ob and indirect questions",
    sub: "Ich glaube, dass er kommt: the verb goes to the end",
    body: "<p>After verbs of thinking, speaking or feeling (<em>glauben, wissen, sagen, hoffen, denken, finden</em>) the second part of the sentence opens with <b>dass</b>, and the conjugated verb goes <b>to the end</b>. The comma before <em>dass</em> is required.</p><div class='table-wrap'><table class='gt'><thead><tr><th>type</th><th>word</th><th>example</th></tr></thead><tbody><tr><td>a statement</td><td class='it'>dass</td><td class='it'>Ich glaube, dass er krank ist.</td></tr><tr><td>a doubt, a yes/no question</td><td class='it'>ob</td><td class='it'>Ich weiß nicht, ob er kommt.</td></tr><tr><td>a question with a question word</td><td class='it'>wann, wo, wer, warum ...</td><td class='it'>Ich weiß nicht, wann der Zug fährt.</td></tr></tbody></table></div><p>More examples: <em>Er sagt, dass er keine Zeit hat. Ich hoffe, dass du kommst. Weißt du, ob das Café offen ist? Sie fragt, wo der Bahnhof ist.</em> After verbs like <em>glauben, meinen, denken, sagen</em> you can also <b>leave out dass</b>, but then the verb stays in second position, as in a normal sentence: <em>Ich glaube, er ist krank.</em></p><p class='callout callout--trap'><b>For English speakers:</b> English <em>that</em> can be dropped (<em>I think he’s sick</em>), and German can drop <em>dass</em> too, but then the verb order changes back to main-clause order. English <em>that</em> is one word with several jobs; German splits them: <b>dass</b> (with a double <em>s</em>) is the conjunction, while <em>das</em> with one <em>s</em> is the article or a pronoun (<em>das Buch, das ich lese</em>, <em>the book that I’m reading</em>). German also puts a comma before <em>dass</em>, which English does not. <em>if</em> covers two meanings in English and German keeps them apart: <em>ob</em> for <em>whether</em> (<em>Ich weiß nicht, ob er kommt</em>) and <em>wenn</em> for the condition (<em>Wenn er kommt, ...</em>). In indirect questions English already uses statement order (<em>I don’t know where he lives</em>, not <em>where does he live</em>), and German does the same, with the verb at the end: <em>Ich weiß nicht, wo er wohnt</em>, not <em>*wo wohnt er</em>.</p><h4>B1: reported speech</h4><p>To report what somebody said you use a verb of communication (<em>sagen, erzählen, berichten, behaupten, meinen, fragen</em>) and a subordinate clause with <em>dass</em>. Pronouns and persons adapt to the point of view of the person reporting:</p><div class='table-wrap'><table class='gt'><thead><tr><th>direct speech</th><th>reported speech</th></tr></thead><tbody><tr><td class='it'>Anna sagt: „Ich habe keine Zeit.“</td><td class='it'>Anna sagt, dass sie keine Zeit hat.</td></tr><tr><td class='it'>Tom hat gesagt: „Ich komme morgen.“</td><td class='it'>Tom hat gesagt, dass er morgen kommt.</td></tr><tr><td class='it'>Er fragt: „Kommst du mit?“</td><td class='it'>Er fragt, ob ich mitkomme.</td></tr><tr><td class='it'>Sie fragt: „Wo wohnst du?“</td><td class='it'>Sie fragt, wo ich wohne.</td></tr><tr><td class='it'>Sie sagt zu mir: „Komm bald!“</td><td class='it'>Sie sagt, ich soll bald kommen.</td></tr></tbody></table></div><p>The tense of the reported clause follows the situation: if the fact is still true, the present stays even after a verb in the Perfekt (<em>Er hat gesagt, dass er krank ist</em>); a fact that is past relative to the speech goes into the Perfekt or the Präteritum (<em>Sie hat gesagt, dass sie in Rom gewesen ist</em>). In newspapers you often find the <em>Konjunktiv I</em> (<em>Er sagt, er sei krank</em>): at this level it is enough to recognize it and to use the indicative with <em>dass</em>.</p><p><b>Questions</b> are reported with <em>ob</em> (yes/no questions) or the question word (<em>wo, wann, warum</em>), always with the verb at the end. An <b>order</b> or a request is reported with <em>sollen</em> (<em>Sie sagt, ich soll kommen</em>) or with <em>bitten ... zu</em> (<em>Sie bat mich, zu kommen</em>).</p><p class='callout callout--trap'><b>For English speakers:</b> English usually shifts the tense back when it reports (<em>She said she had no time, He said he was sick</em>). German leaves the present when the fact is still valid: <em>Er hat gesagt, dass er keine Zeit hat</em>. Don’t carry the backshift over automatically. The Konjunktiv I of newspapers has no English counterpart, so just learn to recognize it. And do not write the clause with the order of the direct question: <em>Er fragt, ob ich komme</em>, not <s>ob komme ich</s>.</p>"
  },
  "ref:g-infinitiv-zu": {
    title: "The infinitive with zu",
    sub: "Ich habe Lust, ins Kino zu gehen: zu + infinitive at the end",
    body: "<p>After many expressions the next verb stands in the infinitive preceded by <b>zu</b>, at the end of the sentence: <em>Ich habe Lust, ins Kino zu gehen. Ich habe vor, im Sommer nach Wien zu fahren. Es ist wichtig, früh aufzustehen.</em></p><div class='table-wrap'><table class='gt'><thead><tr><th>expression</th><th>example</th></tr></thead><tbody><tr><td class='it'>Lust/Zeit haben</td><td class='it'>Ich habe keine Zeit, einkaufen zu gehen.</td></tr><tr><td class='it'>vorhaben</td><td class='it'>Wir haben vor, Deutsch zu lernen.</td></tr><tr><td class='it'>anfangen, aufhören</td><td class='it'>Er hört auf, im Büro zu arbeiten.</td></tr><tr><td class='it'>versuchen, vergessen</td><td class='it'>Ich versuche, dich zu verstehen.</td></tr><tr><td class='it'>es ist schön/wichtig/schwer ...</td><td class='it'>Es ist schön, dich zu sehen.</td></tr></tbody></table></div><p>In separable verbs <em>zu</em> stands <b>between the prefix and the verb</b>, and everything is written as one word: <em>aufstehen → aufzustehen, einkaufen → einzukaufen</em>. When the infinitive group is <b>expanded</b> (<em>zu</em> + other words) a comma is usually added for clarity: <em>Ich versuche, mehr Deutsch zu sprechen.</em> It is required with <em>um, ohne, statt, außer, als ... zu</em>, when the infinitive depends on a noun (<em>Ich habe keine Lust, heute zu arbeiten.</em>) and when a word in the main clause announces it (<em>Ich denke daran, dich anzurufen.</em>). With a simple <em>zu</em> + infinitive after a verb the comma is optional: <em>Ich fange an zu arbeiten</em> or <em>Ich fange an, zu arbeiten</em>. Modal verbs and <em>werden</em> do not take <em>zu</em>: <em>Ich muss gehen. Ich werde kommen.</em></p><p>If the subject changes, <em>dass</em> is usually used instead of the infinitive: <em>Ich möchte, dass du kommst.</em> The constructions <em>um ... zu</em>, <em>ohne ... zu</em>, <em>statt ... zu</em> come at later levels.</p><p class='callout callout--trap'><b>For English speakers:</b> <em>zu</em> + infinitive corresponds to English <em>to</em> + infinitive: <em>I have time to go shopping</em> is <em>Ich habe Zeit, einkaufen zu gehen</em>. The differences: <em>zu</em> goes to the end of its group, it sits inside separable verbs (<em>aufzustehen</em>), and a comma often appears, while English has none before <em>to</em>. Where English uses an <em>-ing</em> form (<em>I stop smoking, I start working</em>), German has no <em>-ing</em> form and uses <em>zu</em> + infinitive: <em>Ich höre auf zu rauchen, ich fange an zu arbeiten</em> (<em>an-/auf-</em> belong to the verb, they are not prepositions). And where English says <em>I’d like you to come</em>, with a new subject before the infinitive, German needs a clause: <em>Ich möchte, dass du kommst</em>. Modals work as in English: no <em>zu</em> (<em>Ich muss gehen</em>, <em>I must go</em>).</p><h4>B2: ohne ... zu, statt ... zu</h4><p><b>ohne ... zu</b> (<em>without</em> + -ing) and <b>statt / anstatt ... zu</b> (<em>instead of</em> + -ing) build an infinitive clause with the same subject as the main clause; <em>zu</em> + infinitive goes to the end: <em>Er ging, ohne sich zu verabschieden. Statt zu warten, rief sie sofort an.</em> With a separable verb, <em>zu</em> goes between the particle and the verb: <em>ohne aufzustehen</em>.</p><p>When the subject is different, use <b>ohne dass</b> or <b>anstatt dass</b> with the conjugated verb at the end: <em>Er ging, ohne dass ich es merkte. Anstatt dass du hilfst, schaust du nur zu.</em></p><p class='callout callout--trap'>English uses the <em>-ing</em> form after a preposition: <em>without asking me</em>, <em>instead of waiting</em>. German has no gerund here: it uses <em>zu</em> + infinitive at the end of the clause, <em>ohne mich zu fragen</em>, never <s>ohne fragend mich</s>. When English adds a different subject (<em>without me noticing</em>), German switches to <em>ohne dass</em> + a full clause.</p>"
  },
  "ref:g-relativsatz": {
    title: "The relative clause",
    sub: "Das Buch, das ich gelesen habe: der, die, das + verb at the end",
    body: "<p>A relative clause gives information about a noun. It starts with a <b>relative pronoun</b>, has the conjugated verb <b>at the end</b> and is set off <b>by commas</b>. The relative pronoun takes its <b>gender and number</b> from the noun it refers to, and its <b>case</b> from its role inside the relative clause. In the three cases of the table the forms are those of the definite article, except the dative plural (the relative genitive, <em>dessen, deren</em>, comes later):</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>plural</th></tr></thead><tbody><tr><td>nominative</td><td class='it'>der</td><td class='it'>die</td><td class='it'>das</td><td class='it'>die</td></tr><tr><td>accusative</td><td class='it'>den</td><td class='it'>die</td><td class='it'>das</td><td class='it'>die</td></tr><tr><td>dative</td><td class='it'>dem</td><td class='it'>der</td><td class='it'>dem</td><td class='it'>denen</td></tr></tbody></table></div><div class='table-wrap'><table class='gt'><thead><tr><th>case</th><th>example</th></tr></thead><tbody><tr><td>nominative</td><td class='it'>Der Mann, <b>der</b> dort steht, ist mein Lehrer.</td></tr><tr><td>accusative</td><td class='it'>Das Buch, <b>das</b> ich gelesen habe, ist spannend.</td></tr><tr><td>dative</td><td class='it'>Die Frau, <b>der</b> ich geholfen habe, heißt Eva.</td></tr><tr><td>dative plural</td><td class='it'>Die Kinder, <b>denen</b> ich das Buch gebe, sind sieben.</td></tr></tbody></table></div><h4>With a preposition</h4><p>The preposition comes <b>before</b> the pronoun and decides the case: <em>Der Mann, mit dem ich spreche, ist mein Chef. Das Thema, über das wir sprechen, ist wichtig. Die Freundin, auf die ich warte, kommt aus Rom.</em></p><h4>was after alles, nichts, etwas</h4><p>After <em>alles, nichts, etwas, vieles</em> and after a neuter superlative the usual pronoun is <b>was</b> (after <em>etwas</em>, <em>das</em> is also correct: <em>etwas, das mir gefällt</em>): <em>Alles, was du sagst, ist richtig. Das ist das Beste, was ich je gegessen habe.</em> <em>was</em> is also used to refer to a whole preceding clause: <em>Er hat gewonnen, was mich freut.</em></p><p class='callout callout--trap'><b>For English speakers:</b> English picks <em>who</em> for people and <em>which</em> for things, or uses <em>that</em>, and often drops the pronoun altogether (<em>the book I read</em>). German never drops it, and it does not care whether the noun is a person or a thing: it chooses <b>der, die, das</b> by gender and number and <b>den, dem</b> and so on by case. <em>Der Mann, <b>der</b> kommt</em> (subject), <em>der Mann, <b>den</b> ich sehe</em> (direct object). And where English leaves the preposition at the end (<em>the man I’m talking to</em>), German puts it in front: <em>der Mann, mit dem ich spreche</em>. Before you write the relative clause, ask: what role does the pronoun play <b>inside</b> it?</p><p class='callout callout--trap'><b>For English speakers:</b> in English a restrictive relative clause has no commas (<em>the man who is standing there is my teacher</em>). In German the clause is <b>always</b> set off by commas: <em>Der Mann, der dort steht, ist mein Lehrer.</em> And do not mix up the pronoun <em>das</em> (<em>das Buch, das ich lese</em>) with the conjunction <em>dass</em> (<em>Ich glaube, dass ...</em>): English <em>that</em> covers both, German keeps them apart.</p><h4>C2: dessen and deren, wo(r)-, and wer ... der</h4><p>The <b>genitive</b> relative pronoun is <b>dessen</b> when the noun it refers to is masculine or neuter, and <b>deren</b> when it is feminine or plural. It names the owner, takes gender and number <b>from the owner</b>, and never changes its form. It stands directly before the owned noun, in place of the article; if the relative clause needs a preposition, the preposition comes before the whole group (<em>mit deren Sohn</em>). An adjective after <em>dessen</em> or <em>deren</em> takes the strong ending: <em>dessen neuer Roman, mit deren kleinem Sohn</em>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>refers to</th><th>example</th></tr></thead><tbody><tr><td>masculine</td><td class='it'>Der Autor, dessen neuer Roman gerade erschienen ist, liest heute in Berlin.</td></tr><tr><td>neuter</td><td class='it'>Das Kind, dessen Eltern ich kenne, geht in meine Klasse.</td></tr><tr><td>feminine</td><td class='it'>Die Firma, deren Chef zurückgetreten ist, sucht einen Nachfolger.</td></tr><tr><td>plural</td><td class='it'>Die Nachbarn, mit deren kleinem Sohn unsere Tochter spielt, ziehen weg.</td></tr></tbody></table></div><p>Do not confuse <em>deren</em> with <em>derer</em>: <em>derer</em> is a demonstrative that points ahead to a relative clause (<em>die Zahl derer, die sich angemeldet haben</em>, the number of those who have signed up).</p><p><b>was and wo(r)-.</b> After <em>das, alles, nichts, vieles, das Einzige</em> and after a neuter superlative used as a noun the relative pronoun is <em>was</em>; when the superlative goes with a noun, it is <em>das</em> again: <em>das Schönste, was ich je gesehen habe</em>, but <em>das schönste Bild, das ich je gesehen habe</em>. Where <em>was</em> would follow a preposition, German uses <b>wo</b> + preposition (<b>wor-</b> before a vowel): <em>Das ist etwas, worüber ich nachdenken muss. Alles, wofür ich gekämpft habe, ist verloren. Er hat bestanden, worüber sich alle freuen.</em> <em>über was</em> is colloquial only.</p><p><b>wer ... der.</b> <em>wer</em> opens a relative clause with no noun to refer to and a general meaning (<em>whoever, anyone who</em>). In the main clause the demonstrative <em>der</em> picks it up, in the case the main verb needs. If the two cases are the same, <em>der</em> can be left out: <em>Wer zu spät kommt, (der) bekommt keinen Platz.</em> If they differ, standard German keeps it: <em>Wem das nicht gefällt, der kann gehen. Wer mir hilft, dem danke ich.</em></p><p class='callout callout--trap'>English <em>whose</em> never changes, whoever the owner is. German chooses by the <b>owner</b>: <em>der Autor, dessen Roman</em>; <em>die Autorin, deren Roman</em>; <em>die Autoren, deren Romane</em>. English also lets a preposition wait at the end (<em>something I have to think about</em>); German cannot strand it and puts <em>wo(r)</em> + preposition at the start: <em>etwas, worüber ich nachdenken muss</em>. And <em>which</em> pointing back to a whole clause is <em>was</em>, not <em>das</em>: <em>Er hat bestanden, was mich freut.</em></p>"
  },
  "ref:g-konditionalsatz": {
    title: "The conditional clause with wenn",
    sub: "Wenn es regnet, ...; Wenn ich Zeit hätte, ...: real and hypothetical",
    body: "<p><b>wenn</b> (if) introduces a subordinate clause: the conjugated verb goes <b>to the end</b> and there is a comma. If the <em>wenn</em> clause comes first, the main clause begins with the <b>conjugated verb</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>type</th><th>wenn clause</th><th>main clause</th></tr></thead><tbody><tr><td>real (possible)</td><td class='it'>Wenn es regnet,</td><td class='it'>bleibe ich zu Hause.</td></tr><tr><td>real, with the future</td><td class='it'>Wenn ich morgen Zeit habe,</td><td class='it'>rufe ich dich an.</td></tr><tr><td>hypothetical (present)</td><td class='it'>Wenn ich Zeit hätte,</td><td class='it'>würde ich kommen.</td></tr><tr><td>hypothetical (present)</td><td class='it'>Wenn ich du wäre,</td><td class='it'>würde ich ihm schreiben.</td></tr></tbody></table></div><p>In a <b>real</b> (open) condition the verbs are in the indicative, and the basic pattern is the Präsens in both clauses, even for the future. For a <b>hypothetical</b> condition (something that is not the case, is unlikely, or is only imagined, even if it is possible: <em>Wenn es morgen regnen würde, ...</em>) <b>both</b> verbs go into the Konjunktiv II: <em>hätte, wäre, könnte</em> with the frequent verbs, <em>würde + infinitive</em> with the others. Both constructions can appear in both clauses: <em>Wenn ich weniger arbeiten würde, hätte ich mehr Zeit.</em> With verbs like <em>arbeiten</em> you often find <em>würde</em> in the <em>wenn</em> clause as well, because the synthetic form would coincide with the Präteritum.</p><p>For a possible condition you can also use <b>falls</b> (<em>if</em>, in the sense of <em>if it happens that</em>): <em>Falls du Zeit hast, ruf mich an.</em> Without <em>wenn</em>, the hypothetical condition can open with the verb: <em>Hätte ich Zeit, würde ich kommen.</em></p><p class='callout callout--trap'><b>For English speakers:</b> the hypothetical pattern looks a lot like English: a past-looking form in the if-clause and <em>would</em> in the result (<em>If I had time, I would come</em>). The German <em>hätte</em> is a different form from the Präteritum <em>hatte</em> (<em>had</em>): only the umlaut tells them apart, so <em>Wenn ich Zeit hätte</em> is hypothetical and <em>Ich hatte Zeit</em> is a plain past. And <em>If I were you</em> is <em>Wenn ich du wäre</em>. One difference: standard English avoids <em>would</em> in the if-clause (<em>If I worked less</em>), while German allows <em>würde</em> in both clauses: <em>Wenn ich weniger arbeiten würde, hätte ich mehr Zeit</em>.</p><p class='callout callout--trap'><b>For English speakers:</b> for a real condition English also uses the present in the if-clause for the future (<em>If I have time tomorrow, I’ll call you</em>), and so does German: <em>Wenn ich morgen Zeit habe, ...</em>. What differs is the main clause: English uses <em>will</em>, while German uses the present as the basic form: <em>rufe ich dich an</em>. And when the <em>wenn</em> clause comes first, English keeps subject and verb in order (<em>I’ll stay home</em>), while German puts the verb first: <em>Wenn es regnet, <b>bleibe ich</b> zu Hause</em>.</p><h4>B2: past conditionals and their variants</h4><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>example</th></tr></thead><tbody><tr><td>real</td><td class='it'>Wenn es regnet, bleibe ich zu Hause.</td></tr><tr><td>unreal, present</td><td class='it'>Wenn ich Zeit hätte, käme ich mit.</td></tr><tr><td>unreal, past</td><td class='it'>Wenn ich Zeit gehabt hätte, wäre ich mitgekommen.</td></tr><tr><td>mixed</td><td class='it'>Wenn ich gestern früher ins Bett gegangen wäre, wäre ich jetzt nicht so müde.</td></tr></tbody></table></div><ul><li><b>falls</b> (<em>if</em>, in the sense of <em>if it happens that</em>): a possible condition, less certain than <em>wenn</em>. <em>Falls es regnet, nehmen wir den Bus.</em></li><li><b>sofern</b> (<em>provided that</em>), more formal: <em>Sofern nichts dazwischenkommt, sind wir um acht da.</em></li><li><b>es sei denn</b> (<em>unless</em>) is followed by a clause with the verb in second position: <em>Wir gehen spazieren, es sei denn, es regnet.</em></li><li><b>without wenn</b>: the conjugated verb goes first, and the main clause often starts with <em>dann</em> or <em>so</em>. <em>Hätte ich das gewusst, (dann) wäre ich gekommen. Regnet es, bleiben wir zu Hause.</em></li></ul><p class='callout callout--trap'>English has the same inversion only in formal style (<em>Had I known, ...</em>, <em>Should it rain, ...</em>); in German it is normal, even in speech, and works with any verb: <em>Regnet es, ...</em>. <em>falls</em> introduces a possible condition and can also express a precaution, like English <em>in case</em> (<em>Nimm einen Schirm mit, falls es regnet</em>); <em>für den Fall, dass</em> makes the precaution more explicit. And it is not <em>if</em> in every sense: it never means <em>whether</em> (that is <em>ob</em>) and never <em>when</em> in time (that is <em>wenn</em> or <em>als</em>).</p>"
  },
  "ref:g-konzessiv": {
    title: "The concessive: obwohl and trotzdem",
    sub: "obwohl es regnet: the verb goes to the end; Trotzdem gehe ich: the verb is second",
    body: "<p><b>obwohl</b> (although, even though) introduces a subordinate clause that says something you would expect to be an obstacle, and that is not one. The conjugated verb goes <b>to the end</b>, with a comma.</p><p><em>Obwohl es regnet, gehe ich spazieren. Ich gehe spazieren, obwohl es regnet.</em> If the subordinate clause comes first, the main clause begins with the conjugated verb. <em>obwohl</em> and <em>trotzdem</em> can appear together, and then <em>trotzdem</em> reinforces the contrast: <em>Obwohl es regnet, gehen wir trotzdem spazieren.</em></p><p>The same idea can be said in three ways, with three different word orders:</p><div class='table-wrap'><table class='gt'><thead><tr><th>word</th><th>type</th><th>order</th><th>example</th></tr></thead><tbody><tr><td class='it'>aber</td><td>conjunction (position zero)</td><td>verb in second position</td><td class='it'>Es regnet, aber ich gehe spazieren.</td></tr><tr><td class='it'>trotzdem</td><td>adverb (first position)</td><td>verb right after it</td><td class='it'>Es regnet. Trotzdem gehe ich spazieren.</td></tr><tr><td class='it'>obwohl</td><td>subordinating conjunction</td><td>verb at the end</td><td class='it'>Ich gehe spazieren, obwohl es regnet.</td></tr></tbody></table></div><p>With a noun you use the preposition <b>trotz</b> + genitive: <em>Trotz des Regens gehe ich spazieren.</em> (in speech also with the dative). With a real fact, <em>obwohl</em> normally takes the indicative.</p><p class='callout callout--trap'><b>For English speakers:</b> the three words map onto three English ones: <em>but</em> is <em>aber</em>, <em>still / nevertheless</em> is <em>trotzdem</em>, and <em>although / even though</em> is <em>obwohl</em>. The word order is where English helps least: English adverbs do not change the order (<em>It’s raining. Nevertheless, I’m going for a walk</em>), while German <em>trotzdem</em> inverts subject and verb: <em>Trotzdem gehe ich spazieren</em>. And <em>obwohl</em> sends the verb to the end, while the word order after <em>although</em> stays the same as in a main clause.</p><p class='callout callout--trap'><b>For English speakers:</b> English separates <em>even though</em> (a real fact: <em>even though it’s raining</em>) from <em>even if</em> (a hypothesis: <em>even if it rains tomorrow</em>), and German does the same: <em>obwohl</em> for the fact, <b>auch wenn</b> or <b>selbst wenn</b> for the hypothesis: <em>Auch wenn es morgen regnet, gehe ich spazieren.</em> And <em>obwohl</em> is not <em>weil</em>: <em>weil</em> introduces a cause; <em>obwohl</em> introduces a fact despite which the main clause happens.</p><h4>B2: obgleich, trotz, auch wenn, selbst wenn</h4><p><b>obgleich</b> and <b>obschon</b> mean <em>obwohl</em> but are more formal; the verb goes to the end. The same concession can be said in three ways:</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>example</th></tr></thead><tbody><tr><td>clause: obwohl</td><td class='it'>Obwohl es regnete, gingen wir spazieren.</td></tr><tr><td>adverb: trotzdem</td><td class='it'>Es regnete. Trotzdem gingen wir spazieren.</td></tr><tr><td>preposition: trotz + genitive</td><td class='it'>Trotz des Regens gingen wir spazieren.</td></tr></tbody></table></div><p>In speech <em>trotz</em> is also found with the dative (<em>trotz dem Regen</em>); in writing it takes the genitive. <b>auch wenn</b> and <b>selbst wenn</b> (<em>even if</em>) introduce a hypothesis: <em>Selbst wenn ich Zeit hätte, würde ich nicht mitkommen.</em></p><p class='callout callout--trap'>English <em>despite</em> and <em>in spite of</em> take a noun or an <em>-ing</em> form (<em>despite the rain</em>, <em>despite being tired</em>); German <em>trotz</em> takes only a noun, and a clause needs <em>obwohl</em>: <em>Obwohl ich müde war, ...</em>. Also, <em>even though</em> is <em>obwohl</em> (a fact), while <em>even if</em> is <em>selbst wenn</em> (a hypothesis).</p>"
  },
  "ref:g-nebensatz-final": {
    title: "The purpose clause: um ... zu and damit",
    sub: "Ich lerne Deutsch, um in Berlin zu arbeiten: the purpose",
    body: "<p>To say the <b>purpose</b> of an action (the answer to <em>Wozu? Wofür?</em>) there are two constructions.</p><div class='table-wrap'><table class='gt'><thead><tr><th>construction</th><th>when</th><th>example</th></tr></thead><tbody><tr><td class='it'>um ... zu + infinitive</td><td>same subject in both parts</td><td class='it'>Ich lerne Deutsch, um in Berlin zu arbeiten.</td></tr><tr><td class='it'>damit + clause with the verb at the end</td><td>different subjects</td><td class='it'>Ich rufe an, damit er Bescheid weiß.</td></tr></tbody></table></div><p>With <b>um ... zu</b> the infinitive goes to the end and <em>zu</em> comes right before the verb; with a separable verb <em>zu</em> goes in the middle: <em>um früh aufzustehen, um pünktlich anzukommen</em>. The comma before <em>um</em> is required. After <b>damit</b> there is a conjugated verb in the <b>indicative</b>, at the end: <em>Ich erkläre es noch einmal, damit du es verstehst.</em></p><p><em>damit</em> is possible even with the same subject (<em>Ich gehe früh, damit ich pünktlich bin</em>), but <em>um ... zu</em> is the more natural form. With different subjects <em>um ... zu</em> cannot be used: <s>Ich rufe an, um er Bescheid weiß</s>.</p><p>With a noun you can use <b>für</b>: <em>Ich lerne für die Prüfung.</em> For the purpose of an action use <em>um ... zu</em> instead.</p><p class='callout callout--trap'><b>For English speakers:</b> English often says purpose with a bare <em>to</em> (<em>I work to earn money</em>) or <em>in order to</em>. German needs <b>um ... zu</b>: <em>Ich arbeite, um Geld zu verdienen</em>, not <s>Ich arbeite, Geld zu verdienen</s>. Do not use <em>für</em> before a verb either: <em>for earning</em> is not <s>für Geld zu verdienen</s>. When the subjects differ, English says <em>so that</em> (<em>I’m calling so that he knows</em>), which is <b>damit</b>.</p><p class='callout callout--trap'><b>For English speakers:</b> English keeps <em>because</em> (cause) and <em>so that</em> (purpose) apart, and German does too: <em>weil</em> for the cause, <em>damit</em> for the purpose. The typical slip is to write <em>weil</em> where <em>damit</em> is needed, for example because the English sentence has <em>for</em> or <em>to</em> and no clear <em>so that</em>.</p>"
  },
  "ref:g-aussprache": {
    title: "Pronunciation",
    sub: "ä ö ü, ß, ch, sch, sp/st, w, v, z, ei/ie, eu/äu",
    body: "<p>German spelling is far more regular than English: each letter or letter group has one main sound. A few letters are silent or only mark length: the <em>h</em> in <em>sehen, fahren</em> is not pronounced, it shows that the vowel is long.</p><ul><li><b>ä</b> is short like <em>e</em> in <em>bed</em> in <em>hätte</em>, and long in <em>Käse</em> (many speakers say it like a long <em>e</em>); <b>ö</b>: for long <em>ö</em> (<em>schön</em>) hold a steady <em>eh</em> vowel (no glide, unlike English <em>say</em>) and round your lips; in <em>können</em> it is a short rounded vowel; <b>ü</b> as <em>ee</em> with rounded lips: long in <em>über</em> [yː], short in <em>müssen, fünf</em> [ʏ], where it is shorter and more open but still rounded. English has no ö and ü: practice them in minimal pairs.</li><li><b>ß</b> is a sharp <em>s</em> and stands after a long vowel or diphthong (<em>heißen, Straße</em>); after a short vowel you write <em>ss</em> (<em>müssen</em>). In Germany and Austria <em>ss</em> replaces <em>ß</em> only where the character is not available; Swiss standard spelling always writes <em>ss</em>.</li><li><b>ch</b> is back [x] after <em>a, o, u</em> and after the diphthong <em>au</em> (<em>ach, Buch, auch</em>); in native German words it is otherwise the voiceless soft [ç] (<em>ich, Milch</em>, like the <em>h</em> in <em>hue</em>), also after <em>äu</em> and <em>eu</em> (<em>Schläuche, euch</em>). At the start of a word and in loanwords the pronunciation varies, so check it word by word. <em>chs</em> is [ks] only when the <em>s</em> belongs to the stem (<em>wachsen, sechs</em>); with an ending <em>ch</em> keeps its sound (<em>machst</em> [xst], <em>höchste</em> [çst]). Final <b>-ig</b> is [ɪç] (<em>König, richtig</em>).</li><li><b>sch</b> = English <em>sh</em> (<em>Schule</em>); <b>sp-</b> and <b>st-</b> at the start of a word are <em>shp-, sht-</em> (<em>sprechen, Stadt</em>).</li><li><b>w</b> = English <em>v</em> (<em>Wasser</em>); <b>v</b> is usually English <em>f</em> (<em>Vater, viel</em>), but [v] in many loans (<em>Vase, Video</em>); <b>z</b> = <em>ts</em> (<em>Zeit</em>).</li><li><b>ei</b> = <em>eye</em> (<em>mein</em>); <b>ie</b> = long <em>ee</em> (<em>Brief</em>); <b>eu / äu</b> = <em>oy</em> (<em>neu, Häuser</em>).</li></ul><p><b>Final devoicing:</b> <em>b, d, g</em> at the end of a syllable are <em>p, t, k</em> (<em>Tag, Hand, ab</em>), except in the ending <em>-ig</em> (see above). <b>Stress</b> usually falls on the first syllable: <em>ARbeit, MORgen</em>.</p><p class='callout callout--trap'><b>Trap:</b> do not read German <em>w</em> and <em>v</em> as in English: <em>Wasser</em> starts with an English <em>v</em>, <em>Vater</em> with an <em>f</em>. German <em>th</em> never has the English [θ]/[ð] sound: in compounds like <em>Rathaus</em> you say <em>t</em> and <em>h</em> separately, and in words like <em>Theater</em> and <em>Thema</em> the group is just [t].</p>"
  },
  "ref:g-register": {
    title: "du and Sie, greetings",
    sub: "du / Sie, times of day, Tschüss / Auf Wiedersehen",
    body: "<p>German has two ways of saying <em>you</em> to one person, and the choice shows respect, not only grammar.</p><ul><li><b>du</b>: friends, family, children, peers and usually colleagues in informal workplaces. Plural: <em>ihr</em>.</li><li><b>Sie</b>: strangers, customers, officials, older people you do not know, and business contexts. Same form for one or many. Always capitalized; the verb is third person plural: <em>Wie heißen Sie?</em></li></ul><p>When in doubt, start with <em>Sie</em>. The switch to <em>du</em> is offered by the older or higher-ranking person (<em>Wir können uns duzen</em>); do not switch on your own.</p><h4>Greetings by time of day</h4><ul><li><em>Guten Morgen</em> (until about 10), <em>Guten Tag</em> (the whole day), <em>Guten Abend</em> (from the evening), <em>Gute Nacht</em> (when going to bed or saying goodbye late at night).</li><li><em>Hallo</em> and <em>Hi</em> are informal; <em>Wie geht's?</em> is common in informal exchanges, but asking how someone is is not an automatic greeting for everyone; with people you address as <em>Sie</em> use <em>Wie geht es Ihnen?</em>. The explicit pair is <em>Wie geht es dir?</em> (du) and <em>Wie geht es Ihnen?</em> (Sie).</li></ul><h4>Saying goodbye</h4><ul><li><em>Auf Wiedersehen</em> (formal), <em>Tschüss</em> (informal), <em>Bis später / Bis morgen</em>.</li></ul><h4>Regional greetings (for recognition)</h4><ul><li><em>Grüß Gott</em> (south Germany, Austria) and <em>Moin</em> (north, any time of day) are greetings, not goodbyes. <em>Servus</em> (Bavaria, Austria) works both ways.</li></ul><p class='callout callout--trap'><b>For English speakers:</b> English <em>you</em> hides the difference, so a wrong choice is easy. A greeting like <em>Hi</em> to a customer would sound too casual; <em>Guten Tag</em> is always safe.</p>"
  },
  "ref:g-modalpartikeln": {
    title: "Modal particles",
    sub: "mal, doch, ja, halt, eben, wohl, etwa: express certainty, expectations and the speaker’s intentions",
    body: "<p><b>Modal particles</b> are small words (<em>mal, doch, ja, halt, eben, wohl, etwa</em>) that the speaker puts into a sentence to show <b>what they think</b>: surprise, insistence, resignation, politeness. Without the particle the sentence is still correct but changes: the degree of certainty, what the speaker expects or the intention can change (<em>Er ist wohl krank</em> is an assumption, <em>Er ist krank</em> a statement). They are used mostly in speech and informal writing, and nearly always have only a rough translation.</p><div class='table-wrap'><table class='gt'><thead><tr><th>particle</th><th>effect</th><th>example</th></tr></thead><tbody><tr><td class='it'>mal</td><td>softens a request, an invitation</td><td class='it'>Komm mal her! Kannst du mal helfen?</td></tr><tr><td class='it'>doch</td><td>encourages or reminds</td><td class='it'>Komm doch mit! Das ist doch klar.</td></tr><tr><td class='it'>ja</td><td>something known, a surprise</td><td class='it'>Das ist ja toll! Ich bin ja müde.</td></tr><tr><td class='it'>halt / eben</td><td>that’s how it is, it cannot be changed</td><td class='it'>Das ist halt so.</td></tr><tr><td class='it'>wohl</td><td>assumption</td><td class='it'>Er ist wohl krank.</td></tr><tr><td class='it'>etwa</td><td>in a question: doubt, suspicion</td><td class='it'>Bist du etwa krank?</td></tr></tbody></table></div><p>The particles stand in the middle field, usually after the verb and after the pronouns: <em>Ich habe dir doch gesagt, dass ...</em> The sense depends on tone and context, so it is best to learn them inside whole sentences, by listening to them.</p><p class='callout callout--trap'><b>For English speakers:</b> English has no single class of words like these. It does the same work with intonation, tag questions (<em>isn’t it?</em>), and words such as <em>just, really, after all, I guess, by any chance</em>. The matches are rough, not translations: <em>mal</em> is close to <em>just</em> or <em>for a sec</em> (<em>Komm mal her!</em>), <em>doch</em> to <em>come on</em> or <em>after all</em>, <em>wohl</em> to <em>I guess, probably</em>, <em>etwa</em> to <em>by any chance</em>, but <em>etwa</em> often carries an expectation of “no” or surprise: <em>Bist du etwa krank?</em> can be <em>You're not sick, are you?</em> or <em>Don’t tell me you’re sick</em>, depending on context, so it is not a neutral softener. Many of these words also have <b>homonyms</b> with another job: <em>doch</em> is also the answer that contradicts a negative question (<em>Hast du keine Zeit? Doch!</em>, <em>Yes, I do</em>), <em>mal</em> is also <em>time</em> as in <em>once</em> (<em>einmal</em>), and <em>wohl</em> is also <em>well</em> (<em>sich wohlfühlen</em>, <em>to feel well</em>).</p><h4>B2: bloß and nur in wishes</h4><p>In unreal wishes <b>bloß</b>, <b>nur</b> and <b>doch</b> strengthen the Konjunktiv II: <em>Wenn ich bloß mehr Zeit hätte! Hätte ich nur nicht so viel gegessen! Wäre ich doch zu Hause geblieben!</em> In commands <em>bloß</em> and <em>ja</em> make the order more insistent or threatening: <em>Mach das bloß nicht! Komm ja nicht zu spät!</em></p><p class='callout callout--trap'>Here <em>nur</em> and <em>bloß</em> do not mean <em>only</em>: they match the English <em>if only</em>. German leaves out <em>if</em> in the inverted form (<em>Hätte ich nur ...!</em>) and puts the particle after the subject and before the negation, not at the front.</p>"
  },
  "ref:g-werden": {
    title: "The functions of werden",
    sub: "Er wird Arzt, er wird anrufen, das wird gemacht, er würde, er wird wohl müde sein",
    body: "<p><b>werden</b> has five functions, and a C1 text uses all of them. To recognize them, look at what comes with it.</p><div class='table-wrap'><table class='gt'><thead><tr><th>function</th><th>what comes with it</th><th>example</th></tr></thead><tbody><tr><td>full verb “to become”</td><td>a noun or an adjective</td><td class='it'>Er wird Arzt. Es wird dunkel.</td></tr><tr><td>future</td><td>an infinitive</td><td class='it'>Ich werde dich anrufen.</td></tr><tr><td>supposition</td><td>an infinitive, often with wohl</td><td class='it'>Sie wird wohl im Büro sein.</td></tr><tr><td>passive</td><td>a past participle</td><td class='it'>Das Haus wird renoviert.</td></tr><tr><td>Konjunktiv II</td><td>the form würde + infinitive</td><td class='it'>Ich würde gern mitkommen.</td></tr></tbody></table></div><p>In the Perfekt, the full verb has <em>geworden</em> (<em>Er ist Arzt geworden</em>), the passive <em>worden</em> (<em>Das Haus ist renoviert worden</em>). Future and supposition share the same form: the context and adverbs such as <em>wohl</em> decide.</p><p class='callout callout--trap'>English spreads these functions over different words: <em>become</em> (or <em>get</em>), <em>will</em>, <em>must</em> for supposition, <em>be</em> in the passive, <em>would</em>. In German it is always <em>werden</em>, and a classic mistake is reading <em>Das Haus wird renoviert</em> as a future: it is a present passive, “the house is being renovated”. Watch out too for <em>bekommen</em>: it means “to get, to receive”, never “to become”.</p>"
  },
  "ref:g-funktionsverbgefuege": {
    title: "Noun-verb collocations",
    sub: "eine Entscheidung treffen, zur Verfügung stellen, in Frage kommen",
    body: "<p>In formal texts many actions are expressed with a <b>noun</b> that carries the meaning and an almost empty <b>verb</b> (<em>stellen, kommen, nehmen, treffen, bringen, finden</em>): this is the <em>Funktionsverbgefüge</em>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>collocation</th><th>simple verb</th><th>meaning</th></tr></thead><tbody><tr><td class='it'>eine Entscheidung treffen</td><td class='it'>entscheiden</td><td>to make a decision</td></tr><tr><td class='it'>zur Verfügung stellen</td><td class='it'>bereitstellen</td><td>to make available</td></tr><tr><td class='it'>in Frage kommen</td><td class='it'>möglich sein</td><td>to be an option</td></tr><tr><td class='it'>zum Ausdruck bringen</td><td class='it'>ausdrücken</td><td>to express</td></tr><tr><td class='it'>in Kraft treten</td><td class='it'>gültig werden</td><td>to come into force</td></tr><tr><td class='it'>Rücksicht nehmen auf</td><td class='it'>berücksichtigen</td><td>to show consideration for</td></tr><tr><td class='it'>Anwendung finden</td><td class='it'>angewendet werden</td><td>to be applied</td></tr></tbody></table></div><p>The group is fixed: you don't choose the preposition or the article (<em>zur Verfügung</em>). Some have a passive meaning (<em>Anwendung finden, zur Sprache kommen</em>), others mark the start of an action (<em>in Gang bringen</em>). In the sentence the noun moves toward the end, like a separable particle: <em>Die Firma stellt uns die Räume zur Verfügung.</em></p><p class='callout callout--trap'>English has similar collocations (<em>make a decision</em>, <em>come into force</em>, <em>take into account</em>), and the verbs often don't match: <em>make a decision</em> is <em>eine Entscheidung treffen</em>, not <em>machen</em>; <em>ask a question</em> is <em>eine Frage stellen</em>; <em>take into account</em> is <em>in Betracht ziehen</em> or <em>berücksichtigen</em>.</p>"
  },
  "ref:g-nominalstil": {
    title: "Nominal style",
    sub: "Nach Abschluss der Arbeiten: the noun instead of the clause",
    body: "<p>In administrative, legal and academic texts German turns verbs into nouns and subordinate clauses into phrases with a preposition: this is the <b>Nominalstil</b>. The same content becomes more compact and more impersonal.</p><div class='table-wrap'><table class='gt'><thead><tr><th>verbal style</th><th>nominal style</th></tr></thead><tbody><tr><td class='it'>Nachdem die Arbeiten abgeschlossen worden sind, ...</td><td class='it'>Nach Abschluss der Arbeiten ...</td></tr><tr><td class='it'>Weil es stark regnete, ...</td><td class='it'>Wegen des starken Regens ...</td></tr><tr><td class='it'>Wenn Sie den Antrag zu spät abgeben, ...</td><td class='it'>Bei verspäteter Abgabe des Antrags ...</td></tr><tr><td class='it'>Um die Kosten zu senken, ...</td><td class='it'>Zur Senkung der Kosten ...</td></tr><tr><td class='it'>Während wir verhandelten, ...</td><td class='it'>Während der Verhandlungen ...</td></tr></tbody></table></div><p>The tools are nouns in <em>-ung, -heit, -keit</em>, the nominalized infinitive (<em>das Lesen</em>), the genitive for the object of the verb (<em>die Senkung der Kosten</em>) and prepositions such as <em>wegen, trotz, bei, nach, vor, zu, während</em>. It is the style of formal writing and of official language (<em>Amtsdeutsch</em>); in speech and in texts meant to be easy to read the verbal style is preferred, and it stays when the clause carries a lot of information.</p><p class='callout callout--trap'>Formal English nominalizes too (<em>upon completion of the work</em>, <em>in the event of late submission</em>), so the idea is familiar. German simply goes further and uses it more often, and the object of the verb becomes a genitive: <em>die Kosten senken</em> → <em>die Senkung der Kosten</em>, “the reduction of costs”.</p>"
  },
  "ref:g-partizipialattribut": {
    title: "Participles as attributes",
    sub: "der lachende Mann, das gestern gekaufte Buch",
    body: "<p>The <b>present participle</b> (infinitive + <em>-d</em>) and the <b>past participle</b> are used before a noun like adjectives and are declined like adjectives. The present participle shows a simultaneous, active action (<em>der lachende Mann</em>, the laughing man); the past participle usually a completed one (<em>das gekaufte Buch</em>, the book that was bought).</p><p>Other phrases can stand before the participle: the whole group sits between the article and the noun and is the compact way of saying a relative clause (<em>erweitertes Partizipialattribut</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th>relative clause</th><th>participle as attribute</th></tr></thead><tbody><tr><td class='it'>das Buch, das gestern gekauft wurde</td><td class='it'>das gestern gekaufte Buch</td></tr><tr><td class='it'>die Kinder, die im Garten spielen</td><td class='it'>die im Garten spielenden Kinder</td></tr><tr><td class='it'>die Kosten, die stark gestiegen sind</td><td class='it'>die stark gestiegenen Kosten</td></tr><tr><td class='it'>ein Problem, das gelöst werden muss</td><td class='it'>ein zu lösendes Problem</td></tr></tbody></table></div><p>The last form (<em>zu</em> + present participle) expresses necessity or possibility, like <em>sein + zu</em>. To read a long group: jump from the article to the noun, then go back and read from the participle leftward.</p><p class='callout callout--trap'>English allows a short participle before the noun (<em>the rising costs</em>) but puts longer phrases after it (<em>the book bought yesterday in the shop</em>). German puts them all before the noun, between the article and the noun, with the participle at the end of the group: <em>das gestern im Laden gekaufte Buch</em>. It is normal in formal writing; in speech a relative clause is preferred.</p><h4>C2: long and nested attributes, and the gerundive</h4><p>In academic, legal and administrative prose an attribute can hold many phrases, two coordinated participles, or even a second attribute inside the first one.</p><div class='table-wrap'><table class='gt'><thead><tr><th>attribute</th><th>unpacked as a relative clause</th></tr></thead><tbody><tr><td class='it'>die gestern angekommenen Gäste</td><td class='it'>die Gäste, die gestern angekommen sind</td></tr><tr><td class='it'>die von der Regierung beschlossene, aber heftig kritisierte Reform</td><td class='it'>die Reform, die von der Regierung beschlossen wurde, aber heftig kritisiert wird</td></tr><tr><td class='it'>die in dem von der Firma gemieteten Gebäude arbeitenden Angestellten</td><td class='it'>die Angestellten, die in dem Gebäude arbeiten, das die Firma gemietet hat</td></tr><tr><td class='it'>die noch zu klärenden Fragen</td><td class='it'>die Fragen, die noch geklärt werden müssen</td></tr><tr><td class='it'>ein nicht zu unterschätzendes Risiko</td><td class='it'>ein Risiko, das man nicht unterschätzen darf</td></tr><tr><td class='it'>die bis Freitag einzureichenden Unterlagen</td><td class='it'>die Unterlagen, die bis Freitag eingereicht werden müssen</td></tr></tbody></table></div><p><b>How to read them.</b> (1) An article followed straight away by a preposition or an adverb (<em>die von ..., das seit ..., die in dem ...</em>) announces an extended attribute. (2) The right noun is usually the one that agrees with the article; if the first noun you meet does not agree (<em>dem ... Gebäude</em> after <em>die</em>), it belongs to an inner attribute and the group goes on. (3) The participle right before the noun is the verb of the hidden relative clause, and everything between the article and that participle is its phrases. (4) The kind of participle gives the meaning: participle I is active and simultaneous; participle II of a transitive verb is passive; participle II of an intransitive verb of motion or change of state (perfect with <em>sein</em>) is active and completed (<em>die angekommenen Gäste</em>).</p><p><b>The gerundive</b> (<em>zu</em> + participle I) is formed mostly from transitive verbs and has a passive meaning of necessity or possibility: <em>die zu klärenden Fragen</em> are questions that must be clarified. With separable verbs <em>zu</em> goes inside the word: <em>die einzureichenden Unterlagen, der abzuschließende Vertrag</em>. It is not used as a predicate; there you say <em>Die Fragen sind noch zu klären.</em></p><p><b>When to unpack.</b> In speech, and in a text that has to be read quickly, an attribute with more than two phrases or with a nested attribute is better turned into a relative clause. In formal writing keep it: it is compact and readers expect it. When you write, one level of nesting is usually the limit of easy reading.</p><p class='callout callout--trap'>English has the meaning but puts it after the noun: <em>the questions still to be clarified, a risk not to be underestimated</em>. German moves the whole group in front of the noun and declines it: <em>die noch zu klärenden Fragen</em>. Watch the form: the meaning is passive, as in <em>to be clarified</em>, but German uses participle I (<em>klärend</em>), not participle II (<em>geklärt</em>).</p>"
  }
});
